      ["pvp-break-stun"] = { title = "Überlebenswille, Schmuckstück auf Ctrl", use = "Volksfähigkeit der Menschen, die alle Betäubungseffekte entfernt. Halte Ctrl, um stattdessen dein oberes Schmuckstück zu nutzen und die Volksfähigkeit für später aufzuheben.",
        requires = "Mensch; ein PvP-Schmuckstück im oberen Schmuckplatz für Ctrl", mods = { "Überlebenswille", "Oberes Schmuckstück benutzen" } },
      ["pvp-charge-spearing-strike"] = { title = "Sturmangriff auf einen Reiter, dann Aufspießender Stoß", use = "Sturmangriff auf einen berittenen Gegner, solange du außerhalb des Kampfes bist, dann drück erneut, um ihn mit Aufspießender Stoß vom Reittier zu holen. Im Kampf ist die Taste einfach Aufspießender Stoß.",
        requires = "Talent Aufspießender Stoß; Kampfhaltung; außerhalb des Kampfes für Sturmangriff", mods = {  } },
      ["pvp-concussion-blow"] = { title = "Erschütternder Schlag auf Ziel oder Mouseover", use = "Betäubt dein Ziel 5 Sek. lang, oder mit Shift dein Mouseover. Es löst keine globale Abklingzeit aus, also kannst du direkt einen weiteren Angriff folgen lassen.",
        requires = "Talent Erschütternder Schlag", mods = { "Dein Ziel betäuben", "Stattdessen dein Mouseover betäuben" } },
      ["pvp-concussion-shield-slam"] = { title = "Erschütternder Schlag, dann Schildschlag", use = "Betäubung und Schildschlag mit einem Tastendruck. Erschütternder Schlag löst keine globale Abklingzeit aus, also kann Schildschlag direkt folgen.",
        requires = "Talente Erschütternder Schlag und Schildschlag; ein Schild angelegt", mods = {  } },
      ["pvp-cooldown-by-stance"] = { title = "Die große Abklingzeit deiner Haltung", use = "Gegenschlag in Kampfhaltung, Schildwall (jetzt 15 Min. Abklingzeit) in Verteidigungshaltung mit Schild, Tollkühnheit in Berserkerhaltung. In Verteidigungshaltung ohne Schild wechselst du in Kampfhaltung.",
        requires = "Gegenschlag, Schildwall und Tollkühnheit erlernt", mods = {  } },
      ["pvp-death-wish-trinket"] = { title = "Blutrausch, Todeswunsch und unteres Schmuckstück", use = "Burst mit Furcht-Immunität: Blutrausch bezahlt Todeswunsch, und dein unteres Schmuckstück geht mit, damit der obere Platz für dein PvP-Schmuckstück frei bleibt. Mit Todeswunsch erleidest du jetzt 5% mehr Schaden.",
        requires = "Talent Todeswunsch; ein Schmuckstück mit Benutzen-Effekt im unteren Platz", mods = {  } },
      ["pvp-disarm"] = { title = "Entwaffnen aus Verteidigungshaltung", use = "Wechsle in Verteidigungshaltung, wenn du nicht darin bist, und wirke Entwaffnen für 10 Sek. auf dein Ziel oder mit Shift auf dein Mouseover-Ziel.",
        requires = "Entwaffnen erlernt; Verteidigungshaltung", mods = { "Entwaffnen auf dein Ziel", "Stattdessen Entwaffnen auf dein Mouseover-Ziel" } },
      ["pvp-disarm-battle"] = { title = "Entwaffnen und zurück in Kampfhaltung", use = "Drück einmal, um in Verteidigungshaltung zu wechseln, und noch einmal für Entwaffnen und direkt zurück in Kampfhaltung. Mit Verbesserter Taktiker behältst du bei jedem Wechsel bis zu 25 Wut.",
        requires = "Entwaffnen erlernt; ein Ziel mit Waffe in der Hand", mods = {  } },
      ["pvp-drop-protection"] = { title = "Segen des Schutzes entfernen und angreifen", use = "Segen des Schutzes von einem freundlichen Paladin hindert dich am Angreifen. Das bricht ihn ab und startet deine Schläge wieder.",
        requires = "", mods = {  } },
      ["pvp-fear-bandage"] = { title = "Drohruf, Verband auf Shift", use = "Hör auf zuzuschlagen und wirke Drohruf auf dein Ziel, dann halte Shift, um dich zu verbinden, während es wegläuft. Schaden unterbricht den Verband, also achte auf DoTs. Trag den Verband ein, den du dabeihast.",
        requires = "Erste Hilfe; Schwerer Runenstoffverband, oder setz den Verband ein, den du dabeihast", mods = { "Stopp den Angriff und wirke Drohruf auf dein Ziel", "Dich selbst verbinden" } },
      ["pvp-free-action-potion"] = { title = "Trank der freien Aktion, Hurtigkeitstrank auf Shift", use = "Trink einen Trank der freien Aktion, bevor eine Wurzel oder Betäubung landet, oder mit Shift einen Hurtigkeitstrank, um Flüchtende einzuholen. Tränke teilen sich eine Abklingzeit, also gibt's nur das eine oder das andere.",
        requires = "Trank der freien Aktion und Hurtigkeitstrank in den Taschen (aus der Alchemie)", mods = { "Trank der freien Aktion trinken", "Stattdessen einen Hurtigkeitstrank trinken" } },
      ["pvp-hamstring-defensive"] = { title = "Kniesehne und zurück in Verteidigungshaltung", use = "Kniesehne geht nicht in Verteidigungshaltung. Drück einmal, um in Kampfhaltung zu wechseln, und noch einmal für Kniesehne und direkt zurück in die Verteidigungshaltung. Shift wählt dein Mouseover-Ziel.",
        requires = "Kniesehne erlernt", mods = { "Kniesehne auf dein Ziel, dann zurück in Verteidigungshaltung", "Stattdessen Kniesehne auf dein Mouseover-Ziel" } },
      ["pvp-hamstring-howl"] = { title = "Kniesehne, Durchdringendes Heulen auf Ctrl", use = "Verlangsame dein Ziel oder mit Shift dein Mouseover-Ziel. Ctrl macht stattdessen mit Durchdringendes Heulen alles in deiner Nähe benommen.",
        requires = "Kampf- oder Berserkerhaltung für Kniesehne; Talent Durchdringendes Heulen für Ctrl", mods = { "Kniesehne auf dein Ziel", "Stattdessen Kniesehne auf dein Mouseover-Ziel", "Durchdringendes Heulen auf alles in deiner Nähe" } },
      ["pvp-howl-or-fear"] = { title = "Durchdringendes Heulen, Drohruf auf Shift", use = "Mach mit Durchdringendes Heulen jeden Gegner im Umkreis von 10 Metern benommen oder halte Shift, um mit dem Zuschlagen aufzuhören und Drohruf auf dein Ziel zu wirken. Das verängstigt außerdem bis zu fünf Gegner im Umkreis von 8 Metern um dich.",
        requires = "Talent Durchdringendes Heulen", mods = { "Durchdringendes Heulen auf jeden Gegner im Umkreis von 10 Metern", "Stopp den Angriff und wirke Drohruf auf dein Ziel" } },
      ["pvp-intercept"] = { title = "Abfangen auf Ziel oder Mouseover", use = "Wechsle bei Bedarf in Berserkerhaltung und nutze Abfangen für eine Betäubung von 3 Sek. Halte Shift, um dein Mouseover-Ziel zu wählen.",
        requires = "Abfangen erlernt; Berserkerhaltung", mods = { "Abfangen auf dein Ziel", "Stattdessen Abfangen auf dein Mouseover-Ziel" } },
      ["pvp-intercept-bloodthirst"] = { title = "Abfangen, dann Blutdurst bei der Landung", use = "Wechsle bei Bedarf in Berserkerhaltung und nutze Abfangen, dann drück erneut, sobald du beim Ziel bist, für Blutdurst. Das zusätzliche Lauftempo hilft dir, dranzubleiben, wenn die Betäubung ausläuft.",
        requires = "Talent Blutdurst; Abfangen erlernt; Berserkerhaltung", mods = {  } },
      ["pvp-intercept-defensive"] = { title = "Abfangen und zurück in Verteidigungshaltung", use = "Drück einmal, um in Berserkerhaltung zu wechseln, und noch einmal für Abfangen und direkt zurück in Verteidigungshaltung. Ist Abfangen nicht bereit, bringt dich der zweite Tastendruck nur zurück.",
        requires = "Abfangen erlernt; 10 Wut für Abfangen", mods = {  } },
      ["pvp-intercept-hamstring"] = { title = "Abfangen, dann Kniesehne bei der Landung", use = "Wechsle bei Bedarf in Berserkerhaltung und nutze Abfangen für die Betäubung von 3 Sek. Drück erneut, sobald du beim Ziel bist, für Kniesehne, bevor es weglaufen kann.",
        requires = "Abfangen erlernt; Berserkerhaltung", mods = {  } },
      ["pvp-interrupt"] = { title = "Unterbrechung auf einer Taste", use = "Schildhieb mit Schild in Kampf- oder Verteidigungshaltung, Zuschlagen in Berserkerhaltung. Ohne Schild wechselst du zuerst in Berserkerhaltung. Außerdem bricht es dein eigenes Zerschmettern ab.",
        requires = "Schildhieb und Zuschlagen erlernt", mods = { "Dein Ziel unterbrechen", "Stattdessen dein Mouseover unterbrechen" } },
      ["pvp-intimidating-shout"] = { title = "Drohruf ohne Schlagen", use = "Stopp deinen automatischen Angriff, damit du die Gegner, die du gerade verängstigt hast, nicht triffst, und wirke dann Drohruf auf dein Ziel oder mit Shift auf dein Mouseover-Ziel.",
        requires = "", mods = { "Dein Ziel und Gegner in seiner Nähe verängstigen", "Stattdessen dein Mouseover verängstigen" } },
      ["pvp-last-stand-potion"] = { title = "Letztes Gefecht und ein Heiltrank", use = "Letztes Gefecht und ein Heiltrank mit einem Tastendruck, wenn du kurz vor dem Umfallen bist, etwa während du eine Flagge trägst. Trag den Trank ein, den du dabeihast.",
        requires = "Talent Letztes Gefecht; ein Großer Heiltrank, oder trag den ein, den du dabeihast", mods = {  } },
      ["pvp-mortal-strike-mouseover"] = { title = "Tödlicher Stoß auf einen Heiler", use = "Tödlicher Stoß auf dein Ziel oder mit Shift auf dein Mouseover-Ziel, um die Heilung dieses Gegners 10 Sek. lang um 50% zu senken.",
        requires = "Talent Tödlicher Stoß", mods = { "Tödlicher Stoß auf dein Ziel", "Stattdessen Tödlicher Stoß auf dein Mouseover-Ziel" } },
      ["pvp-mortal-strike-two-hander"] = { title = "Tödlicher Stoß, vorher zurück zum Zweihänder", use = "Hast du nach Schildwall oder Schildhieb noch Schwert und Schild in der Hand, legt das deinen Zweihänder wieder an und wirkt Tödlicher Stoß. Passiert nur der Wechsel, drück erneut.",
        requires = "Talent Tödlicher Stoß; eine Zweihandwaffe in den Taschen. Trag ihren Namen dort ein, wo Two-Hander Name steht", mods = {  } },
      ["pvp-off-hand-shield"] = { title = "Schildhand zu Schild und zurück", use = "Tausch deine Schildhandwaffe gegen einen Schild oder zurück, ohne die Waffenhand anzurühren. Praktisch vor Schildwall oder Schildblock. Setz deine eigenen Gegenstandsnamen ein.",
        requires = "Beidhändigkeit; ein Schild und deine Schildhandwaffe in den Taschen", mods = {  } },
      ["pvp-one-key-stances"] = { title = "Alle drei Haltungen auf einer Taste", use = "Kampfhaltung bei normalem Tastendruck, Verteidigungshaltung mit Shift und Berserkerhaltung mit Ctrl. Haltungen haben 1 Sek. Abklingzeit, und beim Wechsel behältst du bis zu 10 Wut.",
        requires = "", mods = { "Kampfhaltung", "Verteidigungshaltung", "Berserkerhaltung" } },
      ["pvp-overpower-mouseover"] = { title = "Überwältigen auf Ziel oder Mouseover", use = "Wechsle bei Bedarf in Kampfhaltung und wirke Überwältigen auf den Gegner, der ausgewichen ist, oder mit Shift auf dein Mouseover-Ziel. Mit Rausch des Blutes können es auch Gegner mit deinem Verwunden freischalten.",
        requires = "Kampfhaltung; der Gegner ist ausgewichen oder ein Proc von Rausch des Blutes", mods = { "Überwältigen auf dein Ziel", "Stattdessen Überwältigen auf dein Mouseover-Ziel" } },
      ["pvp-shield-bash-swap"] = { title = "Schildhieb mit Schildwechsel", use = "Leg Einhandwaffe und Schild an und wirke Schildhieb aus Kampfhaltung, damit du für Zuschlagen nicht in die Berserkerhaltung tanzen musst. Klappt nur der Wechsel, drück erneut für den Hieb.",
        requires = "Schildhieb erlernt; eine Einhandwaffe und ein Schild in den Taschen. Trag ihre Namen statt One-Hand Name und Shield Name ein", mods = {  } },
      ["pvp-shield-slam-purge"] = { title = "Buff mit Schildschlag von Ziel oder Mouseover schlagen", use = "Schildschlag auf dein Ziel oder mit Shift auf dein Mouseover-Ziel. Mit 50% Chance entfernt es einen Magieeffekt, also lohnt es sich gegen einen Priester mit Schild oder einen Paladin mit Segen der Freiheit.",
        requires = "Talent Schildschlag; ein Schild angelegt", mods = { "Schildschlag auf dein Ziel", "Stattdessen Schildschlag auf dein Mouseover-Ziel" } },
      ["pvp-shield-wall-swap"] = { title = "Schildwall mit Schildwechsel", use = "Leg deine Einhandwaffe und deinen Schild an, wenn du keinen Schild trägst, wechsle in Verteidigungshaltung und nutze Schildwall. Trag deine eigenen Gegenstandsnamen ein.",
        requires = "Eine Einhandwaffe und ein Schild in den Taschen", mods = {  } },
      ["pvp-spearing-strike"] = { title = "Aufspießender Stoß gegen Reiter", use = "Aufspießender Stoß auf dein Ziel oder mit Shift auf dein Mouseover-Ziel, um einen berittenen Gegner vom Reittier zu holen.",
        requires = "Talent Aufspießender Stoß; Kampfhaltung. Das Update vom 1. Oktober hat die Pflicht zur Zweihandwaffe entfernt", mods = { "Aufspießender Stoß auf dein Ziel", "Stattdessen Aufspießender Stoß auf dein Mouseover-Ziel" } },
      ["pvp-sweeping-mortal-strike"] = { title = "Weitreichende Stöße und Tödlicher Stoß zusammen", use = "Nutze das Makro, wenn zwei Gegner zusammenstehen, etwa ein Heiler neben deinem Ziel. Weitreichende Stöße läuft außerhalb der globalen Abklingzeit, also gehen beide mit einem Tastendruck raus, wenn du 60 Wut hast.",
        requires = "Talente Weitreichende Stöße und Tödlicher Stoß; Kampfhaltung", mods = {  } },
      ["pvp-target-swap"] = { title = "Nächster Gegner oder zurück zum letzten", use = "Wählt den nächsten Gegner, wenn du keinen lebenden hast, und greift an. Halte Shift, um stattdessen zu deinem vorherigen Gegner zurückzugehen.",
        requires = "", mods = { "Bei Bedarf den nächsten Gegner anvisieren, dann angreifen", "Zurück zu deinem letzten feindlichen Ziel und angreifen" } },
      ["pvp-vanguard-concussion"] = { title = "Sturmangriff aus Verteidigungshaltung in Erschütternder Schlag", use = "Mit Frontkämpfer kannst du Sturmangriff außerhalb des Kampfes nutzen, ohne die Verteidigungshaltung zu verlassen. Drück bei der Landung erneut, um Erschütternder Schlag 5 Sek. lang auf das Ziel zu wirken.",
        requires = "Talente Frontkämpfer und Erschütternder Schlag; Verteidigungshaltung; außerhalb des Kampfes für Sturmangriff", mods = {  } },
    },
  },
  PALADIN = {
    guides = {
      ["holy"] = { name = "Heilig", tagline = "Gewirkte Heilung mit sofortiger Rettung", why = {
        "Heiliges Licht, und ab Stufe 20 auch Lichtblitz, bekommen eine Chance von 70%, Zauberverzögerung zu ignorieren, wenn dich ein Mob trifft. Es hat jetzt fünf Ränge, und die öffnen die zweite Reihe.",
        "Heiliges Licht heilt jetzt 12% mehr, und Lichtblitz (20) und Heiliger Schock (30) bekommen denselben Bonus.",
        "30% deiner Manaregeneration läuft beim Zaubern weiter, und beide Ränge schalten Illumination frei.",
        "Dein nächster Einsatz von Heiliges Licht oder Lichtblitz trifft garantiert kritisch, einmal alle 2 Min. Nutz das für Heiliges Licht mit hohem Rang, wenn der Tank schnell Gesundheit verliert.",
        "Kritische Heilungen haben eine Chance von 80%, die Hälfte der Grund-Manakosten des Zaubers zu erstatten. Krits von Göttliche Gunst zählen auch.",
        "Schwöre deinem Tank 5 Min. lang einen Eid, und dein Heiliges Licht, dein Lichtblitz und dein Heiliger Schock heilen ihn stärker. Der Bonus wächst mit deiner Stufe, bis zu 400 bei Heiliges Licht auf Stufe 60.",
        "Ein kritischer Treffer von Lichtblitz zieht 1 Sek. von deinem nächsten Heiliges Licht innerhalb von 15 Sek. ab, und kritische Treffer von Heiliger Schock zählen auch, sobald du es auf Stufe 30 hast.",
        "Läutern kostet 20% weniger und Exorzismus ist 33% früher wieder bereit. Vor allem sind das aber die Punkte, die du für Heiliger Schock auf Stufe 30 brauchst.",
        "Eine sofortige Heilung um 110–118 mit 10 Sek. Abklingzeit, die du in Bewegung wirken kannst. Trifft außerdem Gegner für 129–139.",
        "Der letzte Rang von Illumination: Jede kritische Heilung gibt Mana zurück, und mit Heiliger Schock heilst du oft kritisch.",
        "8% mehr Trefferchance mit Heiligzaubern, also landen Heiliger Schock und Exorzismus auch bei Mobs über deiner Stufe, und Stilleeffekte auf dir enden früher.",
        "Heiliger Schock bekommt 30% mehr Kritchance auf Verbündeten ohne deinen Eid des Lichts, also trifft es bei allen außer dem Tank kritisch.",
        "Deine kritischen Heiligheilungen heilen mehr. Mit diesen Punkten kommst du auf 30 in Heilig.",
        "Das 31-Punkte-Talent von Heilig: Leg es vor einem großen Treffer auf jemanden, dann hat dein nächster Einsatz von Heiliger Schock auf diese Person keine Abklingzeit und heilt die ganze Gruppe.",
        "Der letzte Rang von Heilige Kraft, für 50% mehr kritische Heilung bei Heiligzaubern.",
        "10% mehr Intelligenz für einen größeren Manavorrat. Am 2. November ist es in Schutz-Reihe 1 gewandert.",
        "Deine Spontanzauber kosten 10% weniger Mana, Heiliger Schock und deine Segen eingeschlossen.",
        "Seit dem 2. November 6% mehr Krit mit jedem Zauber und Angriff, also mehr kritische Treffer mit Heiliger Schock und Heiliges Licht.",
        "1% mehr Trefferchance, und dein 6. Punkt in Schutz.",
        "Segen des Schutzes ist 2 Min. früher wieder bereit, und Segen der Freiheit hält 6 Sek. länger.",
        "Gottesschild, Göttlicher Schutz und Bollwerk des Templers sind früher wieder bereit, und Vorahnung läuft 10 Sek. früher aus.",
        "Ein Absorptionsschild in Höhe deiner vollen Gesundheit, alle 5 Min. Deine Antwort, wenn ein Pull schiefgeht und der Tank fällt.",
      } },
      ["protection"] = { name = "Schutz", tagline = "Schildtanken von Anfang an", why = {
        "Nahkampftreffer gegen dich haben eine Chance von 10%, dir 10 Sek. lang oder für 5 Blocks 30% mehr Blockchance zu geben. Blocken braucht einen Schild, nimm also von Anfang an einen.",
        "3% mehr Trefferchance mit Angriffen und Zaubern, also gehen weniger Schläge daneben und dein Spott durch Siegel des Furors sitzt öfter.",
        "Gottesschild, Göttlicher Schutz und Bollwerk des Templers sind eine Minute früher wieder bereit, und Vorahnung läuft 10 Sek. früher aus. Diese Punkte öffnen auf Stufe 20 die dritte Reihe.",
        "Absorbiert 8 Sek. lang Schaden in Höhe deiner vollen Gesundheit, mit Heilige Pflicht alle 4 Min. Teilt sich Vorahnung mit Göttlicher Schutz, also sperrt das eine das andere eine Weile.",
        "Dein Schild blockt 30% mehr Schaden, und jeder Block kann 4% deines Manas zurückgeben, einmal alle 3 Sek. Mit Verschanzen halten Blocks bei langen Pulls dein Mana oben.",
        "4% mehr Rüstung durch deine Ausrüstung. Diese zwei Punkte bringen dich auf 15 für Schnelles Richturteil auf Stufe 25.",
        "Einmal pro Minute sprichst du mit deinem aktiven Siegel ein Richturteil auf ein Ziel im Umkreis von 10 Metern, ohne das Siegel zu verbrauchen oder deine Abklingzeit von Richturteil anzutasten. Mit Siegel des Furors ist das ein zweiter Spott, wenn ein Mob zu deinem Heiler rennt.",
        "Mit aktivem Zorn der Gerechtigkeit erleidest du 9% weniger Schaden durch alles. Lehrer bringen dir Zorn der Gerechtigkeit jetzt auf Stufe 10 bei, also hast du es von Anfang an.",
        "4 Verteidigungsfertigkeit für etwas mehr Vermeidung, und der 20. Punkt, der Heiliger Schild öffnet.",
        "30% mehr Blockchance für 10 Sek., und jeder Block verursacht 75 Heiligschaden mit zusätzlicher Bedrohung, für bis zu 4 Blocks. Es hat 10 Sek. Abklingzeit, also halt es bei jedem Pull aufrecht.",
        "Blocks und kritische Treffer gegen dich speichern Extra-Angriffe, bis zu 4, für mehr Bedrohung beim Tanken.",
        "Heiliger Stoß erzeugt 30% mehr Bedrohung, und mit aktivem Zorn der Gerechtigkeit senkt es außerdem 6 Sek. lang deinen erlittenen Schaden um 6%.",
        "Zähigkeit auf 6% mehr Rüstung durch deine Ausrüstung, und der 30. Punkt in Schutz, den du auf Stufe 40 brauchst.",
        "Seit dem 2. November das 31-Punkte-Talent von Schutz: Heiliger Stoß ist 4 Sek. früher bereit und trifft mit deinem Schild, was Heiliger Schild und Schild-Spezialisierung auslöst, ohne ihre Aufladungen zu verbrauchen.",
        "Die letzten vier Ränge von Vorahnung, für insgesamt 20 Verteidigungsfertigkeit.",
        "5% Parieren, also treffen dich weniger Schläge.",
        "Richturteil ist 2 Sek. früher wieder bereit, also setzt du es für Bedrohung öfter ein.",
        "Seit dem 2. November 6% mehr Krit mit jedem Zauber und Angriff.",
        "Richturteil gibt 60% des Manas zurück, das das gerichtete Siegel gekostet hat, also kannst du längere Pulls tanken.",
        "15% mehr Bewegungstempo, zu Fuß und beritten.",
        "Heiliger Stoß verursacht 20% mehr Schaden und erneuert deine Richturteile auf dem Ziel.",
      } },
      ["retribution"] = { name = "Vergeltung", tagline = "Questen mit Zweihänder", why = {
        "Siegel, Richturteil und deine anderen Sofortzauber kosten 10% weniger Mana, und Vergeltung wirkt kaum etwas anderes.",
        "Richturteil ist alle 8 Sek. statt alle 10 wieder bereit.",
        "6% mehr kritische Trefferchance mit deinem Zweihänder und deinen Zaubern. Drei Ränge sind jetzt das ganze Talent.",
        "Jeder Proc fügt 70% eines Waffentreffers als Heiligschaden hinzu, also holt eine langsame Zweihandwaffe am meisten heraus. Sprich das Richturteil auf ein Ziel, das du mit Hammer der Gerechtigkeit betäubt hast, für etwa doppelten Schaden.",
        "Du läufst 15% schneller, zu Fuß oder beritten, es stapelt aber nicht mit anderen Tempoboni.",
        "Richturteil hat eine Chance von 66%, 40% der Manakosten des Siegels zu erstatten, das du richtest.",
        "Heiliger Stoß trifft 20% härter und erneuert alle Richturteil auf dem Ziel, auch die anderer Paladine, also musst du bei langen Kämpfen nicht neu richten.",
        "6% mehr körperlicher Schaden und 20% weniger Bedrohung, während du eine Zweihandwaffe führst. Es ist in die vierte Reihe hochgerückt und passt deshalb vor 30.",
        "Jeder Einsatz von Richturteil erstattet jetzt 60% des Siegel-Manas, und dieser 20. Punkt öffnet die fünfte Reihe.",
        "Setzt einen Humanoiden bis zu 6 Sek. außer Gefecht, einmal pro Minute. Jeder Schaden weckt ihn, also lass ihn in Ruhe, bis du bereit bist.",
        "Nach einem Krit verursachst du 30 Sek. lang 3% mehr körperlichen und Heiligschaden, bis zu 3-mal stapelbar. Blizzards Patchnotes vom 2. November erhöhen die Obergrenze auf 5 Stapel.",
        "Furcht- und Desorientierungseffekte auf dir enden 15% früher, und dein 25. Punkt in Vergeltung.",
        "Zauberschaden in Höhe von 60% deiner Intelligenz für deine Siegel, Richturteile und Exorzismus, und Hammer des Zorns wird 1 Sek. schneller gewirkt. Mit diesen Punkten kommst du auf 30 in Vergeltung.",
        "Seit dem 2. November das 31-Punkte-Talent von Vergeltung: Deine Schläge speichern dein Siegel, bis zu 3 Kopien. Wechsle das Siegel, und der nächste Treffer löst jede gespeicherte Kopie aus.",
        "10% mehr Stärke, für mehr Angriffskraft und Blockwert.",
