      ["pvp-party-shock"] = { title = "Heiliger Schock auf party 1 oder party 2", use = "Schockt ein Gruppenmitglied, ohne über sein Fenster zu fahren. Shift wählt party 1 und Ctrl party 2. Ohne Modifikator geht es auf dein Mouseover, dann dein freundliches Ziel, dann dich.",
