      ["pvp-repentance"] = { title = "Buße auf Ziel, Mouseover oder dessen Ziel", use = "Macht einen Humanoiden bis zu 6 Sekunden handlungsunfähig. Shift wählt dein Mouseover, Alt das Ziel deines Ziels, wenn es ein Gegner ist.",
