      ["pvp-repentance-heal"] = { title = "Buße, ohne sie zu brechen, dann heilen", use = "Stoppt deinen automatischen Angriff, damit dein nächster Schlag das Ziel nicht aufweckt, dann geht Buße auf dein Ziel. Halte Shift für Lichtblitz oder Ctrl für Heiliges Licht auf dich selbst, solange es außer Gefecht ist.",
