      ["pvp-repentance-judgement"] = { title = "Buße, dann richten für doppelten Schaden", use = "Buße ohne Modifikator, Richturteil mit Shift. Richturteil von Siegel des Befehls trifft ein handlungsunfähiges Ziel etwa doppelt so hart, genau wie ein betäubtes, und der Treffer bricht Buße.",
        requires = "Talente Buße und Siegel des Befehls; Siegel des Befehls aktiv", mods = { "Buße auf dein Ziel", "Richturteil auf dein Ziel" } },
      ["pvp-seal-pick-pvp"] = { title = "Siegel des Befehls, der Gerechtigkeit, des Lichts oder der Weisheit", use = "Standardmäßig Siegel des Befehls. Shift wählt Gerechtigkeit, das bei einem Treffer betäuben kann. Ctrl wählt Licht, Alt wählt Weisheit.",
        requires = "Talent Siegel des Befehls; Siegel der Weisheit gibt es ab Stufe 38", mods = { "Siegel des Befehls", "Siegel der Gerechtigkeit", "Siegel des Lichts", "Siegel der Weisheit" } },
      ["pvp-shock-their-target"] = { title = "Heiliger Schock auf den, den dein Gegner schlägt", use = "Behalte den Gegner im Ziel und heile den Verbündeten, den er angreift, mit deinem freundlichen Mouseover zuerst. Schlägt er dich, heilt es dich. Halte Shift, um stattdessen den Gegner zu schocken.",
