      ["pvp-shock-then-holy-light"] = { title = "Heiliger Schock, dann ein schnelleres Heiliges Licht", use = "Der erste Tastendruck schockt dein freundliches Mouseover-Ziel, dein freundliches Ziel oder dich, der nächste wirkt Heiliges Licht auf dieselbe Weise. Trifft der Schock kritisch, verkürzt Lichtinfusion die Zauberzeit um bis zu eine Sekunde.",
        requires = "Talente Heiliger Schock und Lichtinfusion; solange Heiliger Schock Abklingzeit hat, wartet die Sequenz an diesem Schritt", mods = { "Heiliger Schock, beim nächsten Tastendruck dann Heiliges Licht", "Zuerst Göttliche Gunst, damit die nächste Heilung sicher kritisch trifft" } },
      ["pvp-shock-yourself"] = { title = "Zaubern abbrechen und Heiliger Schock auf dich selbst", use = "Bricht die Heilung ab, die du gerade wirkst, und schockt dich sofort, für wenn dich jemand mitten im Zauber anspringt. Halte Shift, um dein freundliches Mouseover zu schocken. Der Zauber wird auch abgebrochen, wenn der Schock Abklingzeit hat.",
        requires = "Talent Heiliger Schock (in Forever ab Stufe 30); 10 Sekunden Abklingzeit", mods = { "Brich das Zaubern ab, dann Heiliger Schock auf dich selbst", "Brich das Zaubern ab, dann Heiliger Schock auf dein freundliches Mouseover-Ziel" } },
      ["pvp-stun-into-repentance"] = { title = "Hammer der Gerechtigkeit, dann Buße", use = "Verkettet deine Betäubung und Buße auf einem Ziel. Der erste Tastendruck stoppt deinen Schlag und betäubt es; drück kurz vor Ende der Betäubung erneut für Buße. Nutze die Zeit zum Heilen oder Neuansetzen.",
        requires = "Talent Buße; Hammer der Gerechtigkeit erlernt; solange Hammer der Gerechtigkeit Abklingzeit hat, wartet die Sequenz an diesem Schritt", mods = {  } },
      ["pvp-stun-then-justice"] = { title = "Hammer der Gerechtigkeit, dann Siegel der Gerechtigkeit", use = "Der erste Tastendruck betäubt dein Ziel und startet deine Schläge. Drück erneut für Siegel der Gerechtigkeit, damit jeder Treffer eine Chance hat, es weitere 2 Sekunden zu betäuben, wenn der Hammer ausläuft.",
