      ["pvp-target-nearest"] = { title = "Nächsten Gegner anvisieren und angreifen", use = "Wählt den nächsten Gegner, wenn du kein lebendes gegnerisches Ziel hast, und startet dann den Autoangriff. Shift springt immer zum nächsten Gegner, Alt zurück zu deinem letzten gegnerischen Ziel.",
        requires = "", mods = { "Nächster Gegner, wenn du keinen hast, dann angreifen", "Immer der nächste Gegner", "Dein letztes gegnerisches Ziel" } },
      ["pvp-trinket-freedom"] = { title = "Schmuckstück, dann Freiheit auf dich selbst", use = "Nutzt das Schmuckstück im ersten Schmuckstückplatz, dann Segen der Freiheit auf dich. Halte Shift, um das Schmuckstück zu überspringen.",
