      ["pvp-twist-justice"] = { title = "Zwischen Siegel des Befehls und der Gerechtigkeit wechseln", use = "Jeder Tastendruck wechselt zwischen Siegel des Befehls und Siegel der Gerechtigkeit. Mit Entfesselter Zorn gibt der erste Treffer, nachdem du vom Siegel der Gerechtigkeit wegwechselst, jeder gespeicherten Kopie davon eine Chance zu betäuben.",
