      ["pvp-vigil-yourself"] = { title = "Lichtwacht auf dich selbst, dann Heiliger Schock darauf", use = "Leg Lichtwacht auf dich, ohne dein feindliches Ziel zu verlieren. Halte danach Shift für Heiliger Schock auf dich selbst. Das heilt deine ganze Gruppe und kostet keine Abklingzeit von Heiliger Schock.",
        requires = "Talente Lichtwacht und Heiliger Schock; nur ein Vigil pro Gruppe gleichzeitig", mods = { "Lichtwacht auf dich selbst", "Heiliger Schock auf dich selbst" } },
      ["retribution-consecration-judgement"] = { title = "Richturteil, oder Weihe auf Shift", use = "Ein normaler Tastendruck wirkt Richturteil und lässt den automatischen Angriff laufen. Halte Shift für Weihe, wenn Gegner um dich herum stehen.",
        requires = "Weihe erlernt (Stufe 20); ein Siegel aktiv", mods = { "Richturteil auf dein Ziel", "Weihe" } },
      ["retribution-exorcism-judgement"] = { title = "Exorzismus mit Richturteil", use = "Fordere Exorzismus und Richturteil auf dein Ziel an. Exorzismus braucht weiterhin einen Untoten oder Dämon; Richturteil braucht ein aktives Siegel und ein Ziel in Reichweite.",
        requires = "Exorzismus und Richturteil erlernt; ein aktives Siegel für Richturteil", mods = {  } },
      ["retribution-hammer-wrath"] = { title = "Hammer des Zorns oder Heiliger Stoß", use = "Halte Shift für den Fernkampf-Finisher auf ein Ziel mit 20% Gesundheit oder weniger. Ein normaler Tastendruck nutzt Heiliger Stoß.",
        requires = "Hammer des Zorns erlernt (Stufe 44); Heiliger Stoß erlernt", mods = { "Heiliger Stoß", "Hammer des Zorns" } },
      ["retribution-judge-and-strike"] = { title = "Richturteil und Heiliger Stoß", use = "Richturteil läuft außerhalb der globalen Abklingzeit, also wirkt ein Tastendruck Richturteil und Holy Strike. Mit Heiliger Richter frischt Heiliger Stoß außerdem jedes Richturteil auf dem Ziel auf, auch die anderer Paladine.",
        requires = "Ein aktives Siegel; Talent Heiliger Richter für die Erneuerung", mods = {  } },
      ["retribution-opener"] = { title = "Opener: Kreuzfahrer, Richturteil, Befehl", use = "Drei Tastendrücke: Siegel des Kreuzfahrers, Richturteil, dann Siegel des Befehls. 10 Sekunden nach deinem letzten Tastendruck beginnt die Sequenz von vorn.",
