      ["retribution-seal-command"] = { title = "Siegel des Befehls oder Richturteil", use = "Halte Shift, um Siegel des Befehls anzuwenden, und drück dann normal für das Richturteil. Richturteil verbraucht das aktive Siegel nicht mehr, also reicht ein Siegel für viele Richturteile.",
        requires = "Talent Siegel des Befehls; Siegel und Richturteil sind getrennte Tastendrücke", mods = { "Richturteil auf dein Ziel", "Siegel des Befehls" } },
      ["retribution-seal-pick-ret"] = { title = "Siegel der Rechtschaffenheit, des Befehls oder des Kreuzfahrers", use = "Standardmäßig Siegel der Rechtschaffenheit. Shift wählt Siegel des Befehls, Ctrl wählt Siegel des Kreuzfahrers.",
        requires = "Siegel des Kreuzfahrers (Stufe 6); Siegel des Befehls braucht das passende Talent", mods = { "Siegel der Rechtschaffenheit", "Siegel des Befehls", "Siegel des Kreuzfahrers" } },
      ["retribution-seal-twist"] = { title = "Siegel tauschen für Entfesselter Zorn", use = "Jeder Tastendruck wechselt zwischen Siegel des Befehls und Siegel der Rechtschaffenheit. Entfesselter Zorn speichert aus deinen Schlägen bis zu 3 Kopien deines Siegels, und der erste Treffer nach einem Wechsel gibt jeder Kopie ihre Chance auszulösen.",
