      ["class-wide-eagle-eye"] = { title = "Adlerauge-Blickpunkte aneinanderreihen", use = "Öffne den Zielkreis von Adlerauge, ohne die bestehende Ansicht abzubrechen. Wähl den nächsten Punkt per Klick; Bewegung oder Escape beendet das Auskundschaften.",
        requires = "Adlerauge erlernt", mods = {  } },
      ["class-wide-feed-pet"] = { title = "Begleiter außerhalb des Kampfes füttern", use = "Wirkt Tier füttern und gibt das Futter, nur wenn dein Begleiter draußen ist und du nicht im Kampf bist.",
        requires = "Essen in deinen Taschen, das dein Begleiter frisst; setz seinen Namen statt „Chunk of Boar Meat“ ein", mods = {  } },
      ["class-wide-feign-death"] = { title = "Totstellen, das den Kampf beendet", use = "Lässt deinen Begleiter zurückweichen und stoppt zuerst deine Schüsse, dann stellst du dich tot, aber nur im Kampf.",
        requires = "Totstellen erlernt (Stufe 30)", mods = {  } },
      ["class-wide-mark-pet"] = { title = "Markieren und Begleiter schicken", use = "Markiere dein Ziel und schick deinen Begleiter mit einer Taste darauf.",
        requires = "Mal des Jägers erlernt; lebender Begleiter für den Begleiterbefehl", mods = {  } },
      ["class-wide-mend-pet"] = { title = "Begleiter heilen", use = "Heil deinen Begleiter, während dein Gegner ausgewählt bleibt.",
        requires = "Tier heilen erlernt", mods = {  } },
      ["class-wide-pet-attack-mouseover"] = { title = "Begleiter auf dein Mouseover schicken", use = "Dein Begleiter greift den Gegner unter deiner Maus an, ohne dein Ziel zu wechseln; ist nichts unter der Maus, geht er auf dein Ziel.",
        requires = "Ein lebender Begleiter", mods = {  } },
      ["class-wide-pet-attack-recall"] = { title = "Begleiter angreifen, Shift zum Zurückrufen", use = "Schick deinen Begleiter auf dein Ziel. Halt Shift, um ihn passiv zu stellen und zurückzuholen; beim Zurückrufen geht im selben Druck nie ein weiterer Angriffsbefehl raus.",
        requires = "Ein lebender Begleiter", mods = { "Begleiter greift dein Ziel an", "Begleiter wird passiv und folgt" } },
      ["class-wide-pet-call-revive"] = { title = "Begleiter rufen, wiederbeleben oder heilen", use = "Heilt einen lebenden Begleiter, ruft ihn, wenn er nicht da ist, und belebt ihn wieder, wenn er tot ist.",
        requires = "Tier rufen, Tier wiederbeleben und Tier heilen erlernt", mods = { "Heilen, Rufen oder Wiederbeleben, je nachdem, was dein Begleiter braucht", "Tier wiederbeleben" } },
      ["class-wide-track"] = { title = "Aufspüren auf einer Taste", use = "Wechsel das Aufspüren mit Modifier-Tasten, statt das Zauberbuch zu öffnen.",
        requires = "Die Aufspürzauber, die du gelernt hast", mods = { "Humanoide aufspüren", "Wildtiere aufspüren", "Untote aufspüren", "Verborgenes aufspüren" } },
      ["marksmanship-aimed-multi"] = { title = "Gezielter Schuss oder Mehrfachschuss auf einer Taste", use = "Gezielter Schuss und Mehrfachschuss teilen sich in Forever eine Abklingzeit von 6 Sekunden, also gibt dir das Makro pro Fenster das eine oder das andere.",
        requires = "Gezielter Schuss erlernt (Stufe 20)", mods = { "Gezielter Schuss", "Mehrfachschuss auf dein Ziel", "Mehrfachschuss auf dein Mouseover-Ziel" } },
      ["marksmanship-aimed-shot"] = { title = "Gezielter Schuss und Begleiterangriff", use = "Schick deinen Begleiter los, wenn du mit dem Zaubern von Gezielter Schuss beginnst.",
        requires = "Gezielter Schuss erlernt mit 20; lebender Begleiter für den Begleiterbefehl", mods = {  } },
      ["marksmanship-auto-shot"] = { title = "Automatischen Schuss starten", use = "Such dir einen Gegner, wenn du kein gültiges Ziel hast, und fang dann an zu schießen.",
        requires = "", mods = {  } },
      ["marksmanship-distracting-shot"] = { title = "Ablenkender Schuss auf dein Mouseover", use = "Zieh einen losen Gegner von einem Gruppenmitglied, indem du mit der Maus darüberfährst, oder triff dein Ziel, wenn nichts unter der Maus ist.",
        requires = "Ablenkender Schuss erlernt", mods = {  } },
      ["marksmanship-lone-wolf-pet"] = { title = "Begleiter wegschicken oder rufen für Einsamer Wolf", use = "Ruft deinen Begleiter oder schickt ihn weg, damit du ohne Begleiter für die 20% Schaden von Einsamer Wolf kämpfen kannst; Wegschicken kostet den Begleiter 50 Zufriedenheit.",
        requires = "Talent Einsamer Wolf", mods = { "Begleiter rufen, wenn er weg ist, wegschicken, wenn er da ist", "Tier wiederbeleben" } },
      ["marksmanship-pull-sequence"] = { title = "Opener mit Mal, Schlangenbiss und Arkaner Schuss", use = "Bis zu dreimal drücken für Mal, Stich und Arkaner Schuss, während dein Begleiter angreift und Automatischer Schuss an bleibt; ein neues Ziel oder 8 Sekunden setzen es zurück.",
        requires = "Mal des Jägers, Schlangenbiss und Arkaner Schuss erlernt", mods = {  } },
      ["marksmanship-rapid-fire"] = { title = "Schnellfeuer mit beiden Schmuckstücken", use = "Nutzt beide Schmuckstücke und Schnellfeuer zusammen und sorgt dafür, dass Automatischer Schuss läuft.",
        requires = "Schnellfeuer erlernt (Stufe 26)", mods = {  } },
      ["marksmanship-serpent-spread"] = { title = "Schlangenbiss auf Ziel oder Mouseover", use = "Legt Schlangenbiss auf dein Ziel oder mit Shift auf den Gegner unter deiner Maus und lässt Automatischer Schuss an.",
        requires = "Schlangenbiss erlernt", mods = { "Schlangenbiss auf dein Ziel", "Schlangenbiss auf dein Mouseover-Ziel" } },
      ["marksmanship-shoot-after-melee"] = { title = "Nach dem Nahkampf wieder schießen", use = "Stoppt deine Nahkampfschläge, sucht einen Gegner, falls du dein Ziel verloren hast, und schaltet Automatischer Schuss wieder ein. Die am 15. Oktober hinzugefügte Option Automatischer Angriff/Automatischer Schuss kann diesen Wechsel für dich übernehmen.",
        requires = "", mods = {  } },
      ["marksmanship-sniper-shot"] = { title = "Heckenschützenschuss und Automatischer Schuss", use = "Wirk Heckenschützenschuss auf dein Ziel oder per Shift auf dein Mouseover-Ziel und lass Automatischer Schuss an. Das Update vom 1. Oktober legt 45 Meter Reichweite fest und +10 Meter für deine nächsten drei Schüsse.",
        requires = "Talent Heckenschützenschuss (Stufe 40); Ziel außerhalb der Mindestreichweite. Der gespeicherte Tooltip aus Build 70009 zeigte 8–35 Meter.", mods = { "Heckenschützenschuss auf dein Ziel", "Heckenschützenschuss auf dein Mouseover-Ziel" } },
      ["pvp-aimed-burst"] = { title = "Gezielter Schuss, mit Schnellfeuer auf Shift", use = "Wirkt Gezielter Schuss. Halte in deinem Burst-Fenster Shift, um auch dein erstes Schmuckstück und Schnellfeuer zu nutzen, die beide nicht an die globale Abklingzeit gebunden sind.",
        requires = "Gezielter Schuss erlernt; Schnellfeuer (Stufe 26) für Shift", mods = { "Gezielter Schuss", "Erstes Schmuckstück, Schnellfeuer und Gezielter Schuss" } },
      ["pvp-aspect-dance"] = { title = "Aspektwechsel auf Modifier-Tasten", use = "Standardmäßig Falke, Gepard fällt dafür vorher weg; Gepard, Affe und Rudel liegen auf Modifier-Tasten zum Laufen oder Verteidigen.",
        requires = "Aspekt des Rudels erlernt (Stufe 40)", mods = { "Aspekt des Falken", "Aspekt des Geparden", "Aspekt des Affen", "Aspekt des Rudels" } },
      ["pvp-black-arrow"] = { title = "Schwarzer Pfeil auf Ziel oder Mouseover", use = "Verlangsamt den Gegner um 70% und entzieht ihm Mana; Shift setzt ihn auf dein Mouseover.",
        requires = "Schwarzer Pfeil erlernt (Stufe 50)", mods = { "Schwarzer Pfeil auf dein Ziel", "Schwarzer Pfeil auf dein Mouseover-Ziel" } },
      ["pvp-cat-ambush"] = { title = "Katze schleicht, dann Hinterhalt mit Einschüchterung", use = "Versetzt deine Katze passiv in Schleichen. Shift schickt sie mit eingereihtem Einschüchterung aus der Verstohlenheit, so betäubt der erste Treffer und bekommt die 100% zusätzliche Kritchance aus Forever.",
        requires = "Eine Katze mit Schleichen (Begleiterstufe 30); Talent Einschüchterung für Shift", mods = { "Katze wird passiv und schleicht", "Katze greift dein Mouseover-Ziel oder Ziel an, Einschüchterung eingereiht" } },
      ["pvp-clip-kick"] = { title = "Zurechtstutzen, dann Streichertritt", use = "Verlangsamt dein Ziel um 60%, dann nutzt der nächste Druck Streichertritt für 30% Laufgeschwindigkeit, um wieder auf Distanz zu kommen oder mit einem Flüchtenden mitzuhalten. Setzt sich nach 8 Sek. zurück.",
        requires = "Talent Streichertritt; Zurechtstutzen erlernt", mods = {  } },
      ["pvp-concussive-arcane"] = { title = "Erschütternder Schuss, dann Arkaner Schuss", use = "Verlangsamt einen Verfolger, dann feuert der nächste Druck Arkaner Schuss, beides ohne Zauberzeit, damit du beim Kiten schießen kannst. Automatischer Schuss bleibt an. Ein neues Ziel oder 12 Sek. setzen es zurück.",
        requires = "Erschütternder Schuss und Arkaner Schuss erlernt; Verb. Erschütternder Schuss bringt eine Betäubungschance", mods = {  } },
      ["pvp-concussive-wing-clip"] = { title = "Erschütternder Schuss oder Zurechtstutzen", use = "Verlangsamt dein Ziel auf Distanz mit Erschütternder Schuss, mit Shift dein Mouseover-Ziel, oder mit Ctrl im Nahkampf mit Zurechtstutzen.",
        requires = "Erschütternder Schuss und Zurechtstutzen erlernt", mods = { "Erschütternder Schuss auf dein Ziel", "Erschütternder Schuss auf dein Mouseover-Ziel", "Zurechtstutzen auf dein Ziel" } },
      ["pvp-counterattack-mouseover"] = { title = "Gegenangriff aufs Mouseover, Abschreckung auf Shift", use = "Sobald Gegenangriff nach einem Parieren aufleuchtet, wurzelt es den Gegner unter deiner Maus oder dein Ziel 5 Sek. lang fest. Shift zündet vorher Abschreckung für 25% mehr Parieren.",
        requires = "Talente Gegenangriff und Abschreckung", mods = { "Gegenangriff auf dein Mouseover-Ziel oder Ziel", "Abschreckung, dann Gegenangriff" } },
      ["pvp-flare"] = { title = "Leuchtfeuer oder Zauberflamme", use = "Setzt Leuchtfeuer dort, wo du klickst, um verborgene Gegner aufzudecken; Shift nutzt die verzauberte Variante von Leuchtfeuer, die auch magische Dunkelheit fernhält.",
        requires = "Leuchtfeuer erlernt (Stufe 32)", mods = { "Leuchtfeuer", "Verzaubert Leuchtfeuer" } },
      ["pvp-freezing-trap"] = { title = "Eiskältefalle oder Frostfalle", use = "Legt Eiskältefalle, nachdem Begleiter und Schüsse gestoppt sind, oder mit Shift Frostfalle, während du weiterkämpfst. Fallen funktionieren im Kampf zu deinen Füßen, und alle Fallen teilen sich eine Abklingzeit von 30 Sek.",
        requires = "Eiskältefalle erlernt; Frostfalle (Stufe 28) für Shift", mods = { "Eiskältefalle, Begleiter und Schüsse gestoppt", "Frostfalle, Begleiter kämpft weiter" } },
      ["pvp-hunters-mark"] = { title = "Mal des Jägers auf Ziel oder Mouseover", use = "Markiert mit Shift den Gegner unter deiner Maus; ein markiertes Ziel siehst du immer, selbst wenn es in Verstohlenheit geht.",
        requires = "Mal des Jägers erlernt", mods = { "Mal des Jägers auf dein Ziel", "Mal des Jägers auf dein Mouseover-Ziel" } },
      ["pvp-intimidation-pet-target"] = { title = "Einschüchterung auf das Ziel deines Begleiters", use = "Bereitet die Betäubung auf das vor, was dein Begleiter schon beißt, etwa einen Heiler, ohne ihn abzuziehen oder dein eigenes Ziel zu wechseln. Hat der Begleiter kein Ziel, nimmt es deins.",
        requires = "Talent Einschüchterung; lebender Begleiter", mods = {  } },
      ["pvp-kick-trap"] = { title = "Streichertritt, dann Eiskältefalle", use = "Tritt den Nahkämpfer an dir weg und lauf mit dem Tempobonus davon, dann drück erneut, um Eiskältefalle in seinen Weg zu legen. Dein Begleiter kommt zurück, damit er das Eis nicht bricht.",
        requires = "Talent Streichertritt; Eiskältefalle erlernt", mods = {  } },
      ["pvp-lacerate-mouseover"] = { title = "Aufschlitzen auf Ziel oder Mouseover", use = "Legt die Blutung von 21 Sek. auf dein Ziel oder auf den Schurken unter deiner Maus, damit die Ticks ihn aus Verschwinden holen können.",
        requires = "Aufschlitzen erlernt (Stufe 30)", mods = {  } },
      ["pvp-melee-rapid-fire"] = { title = "Schnellfeuer für Nahkampf-Bursts", use = "In Forever beschleunigt Schnellfeuer Nahkampfschläge wie Schüsse, also nutzt dieses Makro beide Schmuckstücke und Schnellfeuer, beginnt zu schlagen und reiht Raptorstoß ein.",
        requires = "Schnellfeuer erlernt (Stufe 26); in Nahkampfreichweite sein", mods = {  } },
      ["pvp-melee-reactions"] = { title = "Zurechtstutzen mit Nahkampfreaktionen", use = "Reiht Raptorstoß ein und verlangsamt dein Ziel mit Zurechtstutzen, oder antwortet auf ein Parieren mit Gegenangriff (Shift) bzw. auf ein Ausweichen mit Mungobiss (Ctrl).",
        requires = "Talent Gegenangriff für Shift", mods = { "Raptorstoß und Zurechtstutzen", "Raptorstoß und Gegenangriff", "Raptorstoß und Mungobiss" } },
      ["pvp-mine-disarm"] = { title = "Entwaffnen mit deinem Raubvogel", use = "Dein Raubvogel entwaffnet 3 Sek. lang, wen er gerade bekämpft. Shift schickt ihn zuerst auf dein Mouseover; er muss in Nahkampfreichweite sein, also drück erneut, sobald er dort ist.",
        requires = "Ein Raubvogel als Begleiter (Forevers umbenannte Eulen-Familie), der Meins! beherrscht", mods = { "Meins! auf das Ziel deines Begleiters oder deins", "Begleiter greift dein Mouseover an und nutzt Meins! darauf" } },
      ["pvp-pet-assist-teammate"] = { title = "Begleiter auf das Ziel eines Mitspielers", use = "Fahr mit der Maus über einen Mitspieler oder nimm ihn ins Ziel, und dein Begleiter greift mit Spurt oder Sturzflug an, was er im Ziel hat. Shift reiht auf diesen Gegner zusätzlich Einschüchterung ein.",
        requires = "Lebender Begleiter; Spurt oder Sturzflug fürs Tempo; Talent Einschüchterung für Shift", mods = { "Begleiter greift das Ziel deines Mitspielers an, mit Spurt oder Sturzflug", "Dasselbe, plus Einschüchterung auf diesen Gegner" } },
      ["pvp-pet-control"] = { title = "Begleitersteuerung auf einer Taste", use = "Schick deinen Begleiter auf dein Ziel oder Mouseover, ruf ihn zurück oder park ihn, alles auf einer Taste.",
        requires = "Ein lebender Begleiter", mods = { "Begleiter greift dein Ziel an", "Begleiter greift dein Mouseover an", "Begleiter wird passiv und folgt", "Begleiter bleibt, wo er ist" } },
      ["pvp-pet-hawk-mouseover"] = { title = "Begleiter und ein Falke auf dein Mouseover", use = "Schickt deinen Begleiter und einen Falken auf den Gegner unter deiner Maus, oft ein Heiler, während du weiter auf dein eigenes Ziel schießt. Falke beschwören und Arkaner Schuss teilen sich eine Abklingzeit.",
        requires = "Talent Falke beschwören (Stufe 25); lebender Begleiter", mods = {  } },
      ["pvp-pet-rescue"] = { title = "Begleiter rausholen und heilen", use = "Ruft einen gefokusten Begleiter passiv mit Spurt oder Sturzflug zurück und wirkt Tier heilen auf ihn. Mit Verb. Tier heilen kann jede Heilung auch einen Debuff entfernen. Schick ihn wieder rein, wenn es sicher ist.",
        requires = "Tier heilen erlernt; Talent Verb. Tier heilen für die Reinigung", mods = {  } },
      ["pvp-root-trap"] = { title = "Gegenangriff, dann Eiskältefalle", use = "Wurzelt das Ziel 5 Sek. lang fest, sobald Gegenangriff aufleuchtet. Tritt zurück und drück erneut, um Eiskältefalle zwischen euch zu legen, damit es hineinläuft, wenn die Wurzeln enden.",
        requires = "Talent Gegenangriff; Eiskältefalle erlernt", mods = {  } },
      ["pvp-scare-beast-pet-off"] = { title = "Wildtier ängstigen mit gestoppten Schüssen und zurückgerufenem Begleiter", use = "Ängstigt den Begleiter eines gegnerischen Jägers oder einen Druiden in Tiergestalt, nachdem es deine Schüsse gestoppt und deinen Begleiter zurückgeholt hat, damit nichts von dir den Effekt bricht. Shift zielt auf dein Mouseover.",
        requires = "Wildtier ängstigen erlernt. Druidengestalten zählen in Classic als Wildtiere; für Forever noch nicht bestätigt", mods = { "Wildtier ängstigen auf dein Ziel", "Wildtier ängstigen auf dein Mouseover-Ziel" } },
      ["pvp-scatter-aimed"] = { title = "Streuschuss, dann Gezielter Schuss", use = "Trifft dein Ziel mit Streuschuss, während dein Begleiter zurückgehalten wird, dann wirkt der nächste Druck Gezielter Schuss mit voller Zauberzeit. Die 2 Sek. Zauberzeit passen in die 4 Sek. Desorientierung. Ein neues Ziel oder 6 Sek. setzen es zurück.",
        requires = "Talent Streuschuss; Gezielter Schuss erlernt", mods = {  } },
      ["pvp-scatter-concussive"] = { title = "Streuschuss, dann Erschütternder Schuss", use = "Trifft dein Ziel mit Streuschuss, während dein Begleiter zurückgehalten wird. Geh auf Abstand und drück erneut, wenn es ausläuft, um es zu verlangsamen; Verb. Erschütternder Schuss kann daraus eine Betäubung machen.",
        requires = "Talent Streuschuss; Verb. Erschütternder Schuss für die Betäubungschance", mods = {  } },
      ["pvp-scatter-shot"] = { title = "Streuschuss mit zurückgerufenem Begleiter", use = "Schickt deinen Begleiter weg, damit er die Desorientierung nicht bricht, und wirkt dann Streuschuss auf dein Ziel oder mit Shift auf dein Mouseover.",
        requires = "Talent Streuschuss", mods = { "Streuschuss auf dein Ziel", "Streuschuss auf dein Mouseover-Ziel" } },
      ["pvp-scatter-trap"] = { title = "Streuschuss, dann Eiskältefalle", use = "Einmal drücken für Streuschuss und erneut, um Eiskältefalle unter dem Gegner zu deinen Füßen zu legen; nach 6 Sekunden setzt es sich zurück.",
        requires = "Talent Streuschuss; Eiskältefalle erlernt", mods = {  } },
      ["pvp-shadowmeld-hide"] = { title = "Schattenmimik mit verstecktem Begleiter", use = "Stoppt deine Schüsse, holt deinen Begleiter auf Passiv zurück, lässt eine Katze schleichen und versteckt dich mit Schattenmimik. In Forever geht Schattenmimik auch im Kampf, mit 2 Min. Abklingzeit.",
        requires = "Nachtelf; eine Katze mit Schleichen, denn jeder andere Begleiter neben dir verrät dich", mods = {  } },
      ["pvp-sniper-opener"] = { title = "Heckenschützenschuss-Opener aus großer Entfernung", use = "Eröffnet mit Heckenschützenschuss aus bis zu 45 Metern, dann Gezielter Schuss und Arkaner Schuss bei den nächsten Drücken, solange die zusätzlichen 10 Meter anhalten. Ein neues Ziel oder 10 Sek. setzen es zurück.",
        requires = "Talent Heckenschützenschuss (Stufe 40)", mods = {  } },
      ["pvp-sniper-scatter"] = { title = "Heckenschützenschuss, oder abbrechen für Streuschuss", use = "Wirkt Heckenschützenschuss. Kommt dir jemand beim Zaubern zu nah, bricht Shift den Zauber ab, hält deinen Begleiter zurück und trifft dein Ziel mit Streuschuss.",
        requires = "Talente Heckenschützenschuss (Stufe 40) und Streuschuss", mods = { "Heckenschützenschuss", "Zauber abbrechen und Streuschuss auf dein Ziel" } },
      ["pvp-strider-kick"] = { title = "Streichertritt auf Ziel oder Mouseover", use = "Tritt dein Ziel und startet deine Nahkampfschläge, oder tritt mit Shift den Gegner unter deiner Maus, und macht dich in beiden Fällen schneller.",
        requires = "Talent Streichertritt", mods = { "Streichertritt auf dein Ziel und losschlagen", "Streichertritt auf dein Mouseover-Ziel" } },
      ["pvp-trap-feign"] = { title = "Falle, dann Totstellen", use = "Legt eine Falle und stellt sich im selben Druck tot, damit Verfolger hineinlaufen; dein Begleiter zieht sich vorher zurück.",
        requires = "Eiskältefalle erlernt; Totstellen (Stufe 30); Frostfalle (Stufe 28) für Shift", mods = { "Eiskältefalle, dann Totstellen", "Frostfalle, dann Totstellen" } },
      ["pvp-viper-sting"] = { title = "Vipernbiss auf Heiler und Caster", use = "Entzieht deinem Ziel Mana oder mit Shift deinem Mouseover-Ziel; Ctrl nutzt Skorpidstich, in Forever senkt das die Trefferchance des Ziels.",
        requires = "Vipernbiss (Stufe 36); Skorpidstich für Ctrl", mods = { "Vipernbiss auf dein Ziel", "Vipernbiss auf dein Mouseover-Ziel", "Skorpidstich auf dein Ziel" } },
      ["pvp-wing-clip-mouseover"] = { title = "Zurechtstutzen auf dein Mouseover im Nahkampf", use = "Schlägt mit eingereihtem Raptorstoß weiter auf dein Ziel und nutzt Zurechtstutzen auf den zweiten Nahkämpfer unter deiner Maus. Verb. Zurechtstutzen gibt jedem Stutzen eine Chance festzuwurzeln.",
        requires = "Zurechtstutzen erlernt; Talent Verb. Zurechtstutzen für die Chance festzuwurzeln", mods = {  } },
      ["pvp-wrath-racial"] = { title = "Zorn des Wildtiers mit deiner Volksfähigkeit", use = "Schickt deinen Begleiter und feuert Zorn des Wildtiers mit Kochendes Blut, Berserker oder Elunes Licht, je nachdem, was dein Volk hat. Zeilen, die dein Volk nicht nutzen kann, tun nichts.",
        requires = "Talent Zorn des Wildtiers; Orc, Troll oder Nachtelf für die Volksfähigkeit", mods = {  } },
      ["pvp-wrath-stun"] = { title = "Zorn des Wildtiers und Einschüchterung", use = "Schickt deinen Begleiter rein, versetzt ihn in Raserei und betäubt das Ziel mit Einschüchterung oder mit Shift dein Mouseover-Ziel.",
        requires = "Talente Einschüchterung und Zorn des Wildtiers; lebender Begleiter", mods = { "Begleiterangriff, Zorn des Wildtiers und Einschüchterung auf dein Ziel", "Dasselbe auf dein Mouseover" } },
      ["survival-aspect-melee"] = { title = "Aspekte für den Nahkampf", use = "Legt Affe für Ausweichen oder Wildtier für Nahkampf-Angriffskraft auf eine Taste, mit Falke und Gepard auf den anderen Modifiern.",
        requires = "Aspekt des Wildtiers (Stufe 30); Aspekt des Geparden (Stufe 20) für Alt", mods = { "Aspekt des Affen", "Aspekt des Wildtiers", "Aspekt des Falken", "Aspekt des Geparden" } },
      ["survival-deterrence-monkey"] = { title = "Abschreckung mit Aspekt des Affen", use = "Zündet Abschreckung und legt das Ausweichen von Aspekt des Affen obendrauf, wenn Gegner im Nahkampf an dir dran sind.",
        requires = "Talent Abschreckung", mods = {  } },
      ["survival-fire-trap"] = { title = "Feuerbrand- oder Sprengfalle", use = "Leg im Kampf Feuerbrandfalle oder mit Shift Sprengfalle zu deinen Füßen. Seit dem 2. November teilen sich alle Fallen eine Abklingzeit von 30 Sek.",
        requires = "Feuerbrandfalle; Sprengfalle (Stufe 34) für Shift", mods = { "Feuerbrandfalle", "Sprengfalle" } },
      ["survival-lacerate"] = { title = "Aufschlitzen und Nahkampfangriff", use = "Legt die 21-sekündige Blutung von Aufschlitzen auf dein Ziel und lässt deine Nahkampfschläge weiterlaufen.",
        requires = "Aufschlitzen erlernt (Stufe 30)", mods = {  } },
      ["survival-mark-melee"] = { title = "Markieren für Beute aufspüren", use = "Markiert dein Ziel, damit Beute aufspüren Mungobiss aktivieren kann, schickt deinen Begleiter und startet deine Nahkampfschläge, sobald du in Reichweite bist.",
        requires = "Talent Beute aufspüren; Mal des Jägers erlernt", mods = {  } },
