        requires = "Blenden (Stufe 34) mit Blendungspulver; Erste Hilfe und den Verband in den Taschen. Jeder Schaden beendet Blenden vorzeitig, und ein Treffer unterbricht den Verband", mods = { "Stopp den Angriff und wirke Blenden auf dein Ziel", "Dich selbst verbinden" } },
      ["pvp-blind-sap"] = { title = "Blenden und Kopfnuss auf Ziel oder Mouseover", use = "Blenden auf dein Ziel, mit Shift auf dein Mouseover-Ziel; Ctrl und Alt wirken stattdessen Kopfnuss auf das Mouseover-Ziel oder das Ziel.",
        requires = "Blenden (Stufe 34) mit Blendungspulver in den Taschen; Kopfnuss braucht einen Humanoiden außerhalb des Kampfes und markiert dich jetzt für PvP, wenn du damit einen PvP-markierten Spieler triffst (Blizzard, 24. September)", mods = { "Blenden auf dein Ziel", "Blenden auf dein Mouseover-Ziel", "Kopfnuss auf dein Mouseover-Ziel", "Kopfnuss auf dein Ziel" } },
      ["pvp-burst"] = { title = "Burst-Fenster: Schmuckstücke, Kaltblütigkeit und Volksfähigkeit", use = "Zünde beide Schmuckstücke, Kaltblütigkeit und deine Orc- oder Troll-Volksfähigkeit zusammen und setz dann deinen stärksten Angriff nach.",
        requires = "Talent Kaltblütigkeit (Stufe 25); Schmuckstücke mit Benutzen-Effekt; Kochendes Blut (Orc) oder Berserker (Troll), die sich in Forever beide geändert haben. Alles, was du nicht hast, wird übersprungen", mods = {  } },
      ["pvp-cheap-gouge-kidney"] = { title = "Fieser Trick, Solarplexus, dann Nierenhieb", use = "Fieser Trick aus der Verstohlenheit, dann bau während der Betäubung Punkte auf; drück erneut, wenn sie endet, für Solarplexus, warte, solange das Ziel unter Solarplexus steht, und drück dann noch einmal für Nierenhieb.",
        requires = "Fieser Trick (Stufe 26) und Nierenhieb (Stufe 30) erlernt; beginne in Verstohlenheit; für Solarplexus muss dich das Ziel ansehen. Verbesserter Solarplexus und Verbesserter Nierenhieb, in Forever beides Meucheln-Talente, lassen Solarplexus länger halten und Nierenhieb härter treffen", mods = {  } },
      ["pvp-cheap-shot-mutilate"] = { title = "Fieser Trick aus der Verstohlenheit, danach Verstümmeln", use = "Eröffne verborgen mit Fieser Trick; danach ist dieselbe Taste für den Rest der Betäubung Verstümmeln mit automatischem Angriff. Shift eröffnet stattdessen mit Erdrosseln.",
        requires = "Talent Verstümmeln und in jeder Hand ein Dolch; Fieser Trick erlernt (Stufe 26); hinter deinem Ziel für Erdrosseln", mods = { "Fieser Trick aus der Verstohlenheit, sonst Verstümmeln", "Erdrosseln aus der Verstohlenheit statt Fieser Trick" } },
      ["pvp-cold-blood-kidney"] = { title = "Nierenhieb, dann Verstümmeln mit Kaltblütigkeit in der Betäubung", use = "Der erste Tastendruck zündet Kaltblütigkeit und wirkt Nierenhieb auf dein Ziel. Nierenhieb verbraucht Kaltblütigkeit nicht, also ist der nächste Tastendruck Verstümmeln mit der zusätzlichen kritischen Trefferchance.",
        requires = "Talente Kaltblütigkeit und Verstümmeln; Dolche angelegt; Nierenhieb (Stufe 30) und Combopunkte. Kaltblütigkeit wird ausgelöst, auch wenn Nierenhieb fehlschlägt, also drück erst, wenn die Punkte bereit sind", mods = {  } },
      ["pvp-cold-blood-opener"] = { title = "Kaltblütigkeit vor Hinterhalt oder Meucheln", use = "Kaltblütigkeit, dann Hinterhalt aus der Verstohlenheit für einen Opener mit 100% kritischer Trefferchance; halte Shift für Meucheln, wenn du schon sichtbar bist.",
        requires = "Talent Kaltblütigkeit (Stufe 25); ein Dolch in der Waffenhand; hinter deinem Ziel", mods = { "Kaltblütigkeit, dann Hinterhalt", "Kaltblütigkeit, dann Meucheln" } },
      ["pvp-finisher-control"] = { title = "Ausweiden, Nierenhieb oder Scharfe Klinge für Toxin", use = "Ausweiden bei normalem Tastendruck, Nierenhieb mit Shift, wenn du die Betäubung brauchst, und Scharfe Klinge mit Ctrl, damit Toxin dein Verkrüppelndes oder Gedankenbenebelndes Gift öfter sitzen lässt.",
        requires = "Talent Toxin; Scharfe Klinge (Stufe 24) und Nierenhieb (Stufe 30) erlernt; Combopunkte für die Finisher", mods = { "Ausweiden", "Nierenhieb", "Scharfe Klinge" } },
      ["pvp-free-action-sprint"] = { title = "Trank der freien Aktion und Sprinten", use = "Trink einen Trank der freien Aktion und nutze Sprinten, bevor du erwischt wirst; Shift trinkt stattdessen nur einen Hurtigkeitstrank.",
        requires = "Trank der freien Aktion (Stufe 20) oder Hurtigkeitstrank in den Taschen; Freie Aktion entfernt keine Effekte, die schon auf dir liegen", mods = { "Trank der freien Aktion und Sprinten", "Nur Hurtigkeitstrank" } },
      ["pvp-ghostly-evasion"] = { title = "Entrinnen und Geisterhafter Stoß zusammen", use = "Wenn ein Krieger oder Schurke auf dir klebt, stapelt ein Tastendruck das Ausweichen von Entrinnen mit dem von Geisterhafter Stoß. Mit Reinlegen können Angriffe deines Ziels, denen du ausweichst, einen Combopunkt geben.",
        requires = "Talent Geisterhafter Stoß; Entrinnen bereit (außerhalb der globalen Abklingzeit). Reinlegen ist optional", mods = {  } },
      ["pvp-ghostly-hemorrhage"] = { title = "Geisterhafter Stoß, sonst Blutsturz", use = "Zuerst kommt Geisterhafter Stoß; geht das nicht, weil die Abklingzeit läuft oder dir die 40 Energie fehlen, wird derselbe Tastendruck zu Blutsturz.",
        requires = "Talente Geisterhafter Stoß und Blutsturz", mods = {  } },
      ["pvp-gouge-backstab"] = { title = "Solarplexus, dann Meucheln von hinten", use = "Solarplexus beim ersten Tastendruck, stell dich hinter das Ziel, solange es stillsteht, und drück dann erneut für Meucheln.",
        requires = "Ein Dolch in der Waffenhand; für Solarplexus muss dich das Ziel ansehen. Durchbohrende Wunden gibt Meucheln mehr kritische Trefferchance und eine Chance auf einen zusätzlichen Combopunkt", mods = {  } },
      ["pvp-gouge-sprint"] = { title = "Solarplexus und wegsprinten", use = "Sprinten und Solarplexus auf dein Ziel mit einem Tastendruck, um aus einem Kampf rauszukommen, den du verlierst. Mit dem Talent Verbessertes Sprinten entfernt das auch Kniesehne und andere Verlangsamungen.",
        requires = "Sprinten bereit (außerhalb der globalen Abklingzeit); für Solarplexus muss dich das Ziel ansehen. Talent Verbessertes Sprinten, um Verlangsamungen zu entfernen", mods = {  } },
      ["pvp-gouge-vanish"] = { title = "Solarplexus, dann Verschwinden", use = "Solarplexus beim ersten Tastendruck, dann drück erneut, während das Ziel dasteht, für Verschwinden, und du bist für einen neuen Opener wieder in Verstohlenheit.",
        requires = "Solarplexus (Stufe 6) und Verschwinden (Stufe 22) erlernt; für Solarplexus muss dich das Ziel ansehen. Verbesserter Solarplexus, in Forever ein Meucheln-Talent, bringt bis zu 1.5 Sek. mehr", mods = {  } },
      ["pvp-interrupt-keys"] = { title = "Tritt oder Solarplexus auf Ziel oder Mouseover", use = "Tritt auf dein Ziel bei normalem Tastendruck; Shift wechselt auf dein Mouseover-Ziel, Ctrl oder Alt nehmen stattdessen Solarplexus.",
        requires = "Tritt (Stufe 12) und Solarplexus (Stufe 6) erlernt; für Solarplexus muss dich das Ziel ansehen", mods = { "Tritt auf dein Ziel", "Tritt auf dein Mouseover-Ziel", "Solarplexus auf dein Ziel", "Solarplexus auf dein Mouseover-Ziel" } },
      ["pvp-kick-kidney"] = { title = "Tritt, dann Nierenhieb", use = "Tritt beim ersten Tastendruck und Nierenhieb beim nächsten, damit ein Heiler direkt von der Unterbrechung in eine Betäubung geht. Die Stille durch das Talent Verbesserter Tritt verhindert, dass er dazwischen etwas wirkt.",
        requires = "Tritt (Stufe 12) und Nierenhieb (Stufe 30) erlernt; Combopunkte für Nierenhieb. Talent Verbesserter Tritt für die 2 Sek. Stille", mods = {  } },
      ["pvp-kick-then-gouge"] = { title = "Tritt, dann Solarplexus, während Tritt abklingt", use = "Tritt beim ersten Tastendruck und Solarplexus beim nächsten, solange Tritt noch Abklingzeit hat, auf dein Mouseover-Ziel oder dein Ziel.",
        requires = "Tritt und Solarplexus erlernt; für Solarplexus muss dich das Ziel ansehen", mods = {  } },
      ["pvp-kidney-blind"] = { title = "Nierenhieb, dann Blenden", use = "Nierenhieb beim ersten Tastendruck; drück erneut, wenn die Betäubung ausläuft, für Blenden auf dasselbe Ziel. Jeder Tastendruck stoppt den automatischen Angriff, damit kein verirrter Schlag Blenden bricht.",
        requires = "Nierenhieb (Stufe 30) mit Combopunkten; Blenden (Stufe 34) mit Blendungspulver in den Taschen. Ein Zielwechsel startet die Sequenz wieder bei Nierenhieb", mods = {  } },
      ["pvp-kidney-burst"] = { title = "Nierenhieb mit Schmuckstücken und Volksfähigkeit", use = "Nierenhieb, beide Schmuckstücke und deine Orc- oder Troll-Volksfähigkeit mit einem Tastendruck, damit deine Schadens-Abklingzeiten laufen, während das Ziel dank Talent Verbesserter Nierenhieb zusätzlichen Schaden nimmt.",
        requires = "Nierenhieb (Stufe 30) und Combopunkte; Talent Verbesserter Nierenhieb; Schmuckstücke mit Benutzen-Effekt; Kochendes Blut (Orc) oder Berserker (Troll). Alles, was du nicht hast, wird übersprungen, und die Schmuckstücke zünden, auch wenn Nierenhieb nicht ausgelöst wird", mods = {  } },
      ["pvp-mutilate-kidney"] = { title = "Zweimal Verstümmeln, dann Nierenhieb", use = "Drück wiederholt: zweimal Verstümmeln für vier oder mehr Punkte, dann Nierenhieb, dann geht es von vorn los. Verbesserter Nierenhieb lässt deine Angriffe und Gifte während der Betäubung härter treffen.",
        requires = "Talent Verstümmeln; Dolche angelegt; Nierenhieb erlernt (Stufe 30). Ein Verfehlen oder Ausweichen macht die Betäubung kürzer. Verbesserter Nierenhieb ist optional", mods = {  } },
      ["pvp-premeditation-garrote"] = { title = "Konzentration mit Erdrosseln oder Hinterhalt", use = "Aus der Verstohlenheit bringt das die zwei Punkte von Konzentration und eröffnet mit Erdrosseln; halte Shift, um stattdessen mit Hinterhalt zu eröffnen.",
        requires = "Talent Konzentration; Verstohlenheit. Für Erdrosseln musst du hinter dem Ziel stehen, außer du hast Gemeinheiten; Hinterhalt braucht einen Dolch in der Waffenhand, und du musst hinter dem Ziel stehen", mods = { "Konzentration, dann Erdrosseln", "Konzentration, dann Hinterhalt" } },
      ["pvp-preparation-blind"] = { title = "Blenden, und Vorbereitung für ein zweites Blenden", use = "Hör auf zuzuschlagen und wirke Blenden auf dein Ziel. Halte Ctrl für Vorbereitung. Das beendet die Abklingzeit von Blenden und deine anderen Schurken-Abklingzeiten, sodass du Blenden auf einen zweiten Gegner wirken kannst.",
        requires = "Blenden (Stufe 34) mit Blendungspulver; Talent Vorbereitung (10 Min. Abklingzeit). Laut Tooltip beendet es die Abklingzeit aller anderen Schurkenfähigkeiten; bei Blenden haben wir das im Spiel noch nicht gesehen. Flüchtigkeit verkürzt außerdem die Abklingzeit von Blenden", mods = { "Stopp den Angriff und wirke Blenden auf dein Ziel", "Vorbereitung" } },
      ["pvp-pvp-poisons"] = { title = "Gifte gegen Spieler", use = "Verkrüppelndes Gift bei einfachem Druck, Wundgift mit Shift gegen Heiler und Gedankenbenebelndes Gift mit Ctrl gegen Caster; Alt wählt die Schildhand.",
        requires = "Verkrüppelndes Gift (Stufe 20), Gedankenbenebelndes Gift (24) und Wundgift (32) erlernt und in deinen Taschen; nutze den genauen Rangnamen jedes Gifts", mods = { "Verkrüppelndes Gift auf die Waffenhand", "stattdessen Wundgift", "stattdessen Gedankenbenebelndes Gift", "Deine Schildhand statt deiner Waffenhand" } },
      ["pvp-racial-break"] = { title = "Volksfähigkeit zum Befreien, oder ein Schmuckstück mit Shift oder Ctrl", use = "Drück für die Volksfähigkeit deines Volks, die einen Effekt abschüttelt; Shift und Ctrl nutzen das obere und untere Schmuckstück.",
        requires = "Mensch (Überlebenswille entfernt Betäubungen), Untoter (Wille der Verlassenen entfernt Bezauberung, Furcht und Schlaf), Gnom (Entfesselungskünstler löst bewegungseinschränkende Effekte) oder Zwerg (Steingestalt entfernt Blutungen, Gifte und Krankheiten); benutzbare Schmuckstücke für Shift und Ctrl", mods = { "Überlebenswille, Wille der Verlassenen, Entfesselungskünstler oder Steingestalt deines Volks", "Schmuckstück in Platz 13 benutzen", "Schmuckstück in Platz 14 benutzen" } },
      ["pvp-riposte-finisher"] = { title = "Riposte, dann Ausweiden oder Nierenhieb", use = "Versucht Riposte (geht nur direkt nach einer Parade) und setzt dann im selben Tastendruck deinen Finisher ein: Ausweiden oder mit Shift Nierenhieb.",
        requires = "Talent Riposte; Riposte läuft außerhalb der globalen Abklingzeit. Nierenhieb erlernt (Stufe 30); Combopunkte", mods = { "Riposte, falls nach einer Parade verfügbar, dann Ausweiden", "Riposte, falls nach einer Parade verfügbar, dann Nierenhieb" } },
      ["pvp-riposte-mouseover"] = { title = "Riposte auf den Gegner unter deinem Mauszeiger", use = "Nach einer Parade Riposte, um den Krieger oder Schurken unter deinem Mauszeiger zu entwaffnen, während du dein eigenes Ziel behältst. Ist nichts unter dem Mauszeiger, trifft es dein Ziel.",
        requires = "Talent Riposte; geht nur direkt nach einer Parade. Die Entwaffnung hält 6 Sek.", mods = {  } },
      ["pvp-sap-then-open"] = { title = "Kopfnuss auf einen Gegner, dann einen anderen angreifen", use = "Halte Shift für Kopfnuss auf den Gegner unter deinem Mauszeiger, lass dann los und drück erneut, um mit Konzentration und Fieser Trick auf dein Ziel zu eröffnen. Kopfnuss bricht in Forever Verstohlenheit nicht mehr.",
        requires = "Kopfnuss und Fieser Trick (Stufe 26) erlernt; Talent Konzentration; der Gegner für die Kopfnuss muss ein Humanoide außerhalb des Kampfes sein. Faule Tricks und Gemeinheiten senken die Energiekosten für beide", mods = { "Konzentration und Fieser Trick auf dein Ziel", "Kopfnuss auf dein Mouseover-Ziel oder, wenn nichts unter dem Mauszeiger ist, auf dein Ziel" } },
      ["pvp-sneak-sprint"] = { title = "Absteigen, Verstohlenheit und Sprinten", use = "Steig ab, wechsle in Verstohlenheit und nutze Sprinten mit einem Tastendruck, um verborgen die Distanz zu schließen.",
        requires = "Außerhalb des Kampfes für Verstohlenheit; laut Tooltip von Sprinten bricht das Verstohlenheit nicht", mods = {  } },
      ["pvp-sprint-kick"] = { title = "Tritt, mit Sprinten auf Shift, um zum Zaubernden zu kommen", use = "Tritt auf dein Mouseover-Ziel oder Ziel. Halte Shift, um zuerst Sprinten zu nutzen; mit dem Talent Verbessertes Sprinten befreit dich das aus Wurzeln und Verlangsamungen. Drück erneut, sobald du in Reichweite bist, für Tritt.",
        requires = "Tritt erlernt (Stufe 12); Talent Verbessertes Sprinten, um Wurzeln und Verlangsamungen zu entfernen; Verbesserter Tritt fügt 2 Sek. Stille hinzu", mods = { "Tritt auf dein Mouseover-Ziel oder Ziel", "Sprinten, dann Tritt, wenn du schon in Reichweite bist" } },
      ["pvp-stun"] = { title = "Fieser Trick aus der Verstohlenheit, Nierenhieb im Kampf", use = "Eröffne verborgen mit Fieser Trick und nutze Nierenhieb, sobald der Kampf läuft; Shift richtet beides auf dein Mouseover-Ziel.",
        requires = "Fieser Trick (Stufe 26) und Nierenhieb (Stufe 30) erlernt; Nierenhieb braucht Combopunkte", mods = { "Fieser Trick aus der Verstohlenheit, sonst Nierenhieb, auf dein Ziel", "Dasselbe auf dein Mouseover" } },
      ["pvp-throw"] = { title = "Werfen auf dein Ziel oder Mouseover", use = "Wirf eine Waffe auf dein Ziel, oder mit Shift auf den, der unter deinem Mauszeiger ist.",
        requires = "Eine Wurfwaffe im Fernkampfplatz", mods = { "Werfen auf dein Ziel", "Werfen auf dein Mouseover" } },
      ["pvp-vanish-premeditation"] = { title = "Verschwinden, dann Konzentration und Fieser Trick", use = "Im Kampf stoppt der erste Tastendruck deine Schläge und nutzt Verschwinden; der nächste, während du verborgen bist, fügt Konzentration hinzu und eröffnet erneut mit Fieser Trick.",
        requires = "Verschwinden (Stufe 22) und Fieser Trick (Stufe 26) erlernt; Talent Konzentration. Außerhalb des Kampfes ist der erste Tastendruck einfach Verstohlenheit", mods = {  } },
      ["pvp-vanish-sap"] = { title = "Verschwinden, dann Kopfnuss", use = "Im Kampf stoppt das deine Schläge und nutzt Verschwinden; drück erneut, während du verborgen bist, für Kopfnuss auf dein Mouseover-Ziel oder Ziel. Außerhalb des Kampfes ist der erste Tastendruck einfach Verstohlenheit.",
        requires = "Verschwinden (Stufe 22) und Kopfnuss erlernt. Kopfnuss sitzt erst, wenn der Gegner aus dem Kampf fällt, deine Blutungen und Gifte auf ihm stehen also im Weg. Kopfnuss bricht Verstohlenheit nicht mehr (Blizzard, 7. Oktober)", mods = {  } },
      ["pvp-vanish-sprint"] = { title = "Verschwinden und wegsprinten", use = "Hör auf zuzuschlagen, Verschwinden und Sprinten, um dich zu lösen; Shift ist nur Sprinten, Ctrl nur Entrinnen.",
        requires = "Verschwinden (Stufe 22) und Sprinten (Stufe 10) bereit; keins von beiden löst die globale Abklingzeit aus", mods = { "Stopp den Angriff, Verschwinden, dann Sprinten", "Nur Sprinten", "Nur Entrinnen" } },
      ["subtlety-cheap-shot"] = { title = "Fieser Trick aus der Verstohlenheit", use = "Drück einmal, um in Verstohlenheit zu wechseln, und noch einmal für Fieser Trick auf dein Ziel.",
        requires = "Verstohlenheit und Fieser Trick erlernt", mods = {  } },
      ["subtlety-dagger-openers"] = { title = "Dolch anlegen für Hinterhalt oder Meucheln", use = "Ersetze beide Waffennamen durch deine. Leg den Dolch für Hinterhalt an, mit Shift für Meucheln. Ein Waffenwechsel im Kampf braucht nach der globalen Abklingzeit eventuell einen weiteren Tastendruck.",
        requires = "Dolch in der Waffenhand; Beidhändigkeit für die Schildhand; hinter dem Ziel; Verstohlenheit für Hinterhalt", mods = { "Leg deinen Dolch an und versuch Hinterhalt", "Leg deinen Dolch an und versuch Meucheln" } },
      ["subtlety-ghostly-ambush"] = { title = "Hinterhalt nach Geisterhafter Stoß, sonst Meucheln", use = "Hinterhalt aus der Verstohlenheit oder offen innerhalb von 7 Sek. nach einem Geisterhaften Stoß; jeder andere Tastendruck ist Meucheln.",
        requires = "Talent Geisterhafter Stoß für Hinterhalt außerhalb der Verstohlenheit; ein Dolch in der Waffenhand; hinter deinem Ziel", mods = {  } },
      ["subtlety-ghostly-backstab"] = { title = "Geisterhafter Stoß, wenn bereit, sonst Meucheln", use = "Geisterhafter Stoß, sobald die Abklingzeit von 20 Sekunden um ist, und dazwischen Meucheln.",
        requires = "Talent Geisterhafter Stoß; ein Dolch in der Waffenhand und ein Platz hinter dem Ziel für Meucheln", mods = {  } },
      ["subtlety-hemorrhage"] = { title = "Blutsturz und Autoangriff", use = "Blutsturz und weiter zuschlagen; in Forever verstärkt das deine eigene Blutung und dein Erdrosseln, statt körperlichen Schaden hinzuzufügen.",
        requires = "Talent Blutsturz", mods = {  } },
      ["subtlety-hemorrhage-key"] = { title = "Blutsturz, Blutung und Meucheln auf einer Taste", use = "Eine Taste für den Ablauf rund um Blutung: Blutsturz bei normalem Tastendruck, Blutung mit Shift und Meucheln mit Ctrl.",
        requires = "Talent Blutsturz (verstärkt in Forever deine eigene Blutung und dein Erdrosseln); Blutung erlernt (Stufe 20); ein Dolch und ein Platz hinter dem Ziel für Meucheln", mods = { "Blutsturz", "Blutung", "Meucheln" } },
      ["subtlety-pick-pocket-sap"] = { title = "Taschendiebstahl, dann Kopfnuss aus der Verstohlenheit", use = "Bestiehl den Gegner unter deinem Mauszeiger (oder dein Ziel) und wirke im selben Tastendruck Kopfnuss darauf.",
        requires = "Verstohlenheit; Kopfnuss erlernt (Stufe 10); ein Humanoide außerhalb des Kampfes. Kopfnuss bricht Verstohlenheit nicht (Blizzard, 7. Oktober)", mods = {  } },
      ["subtlety-premeditation-chain"] = { title = "Konzentration, Fieser Trick, dann Nierenhieb", use = "Aus der Verstohlenheit bringt das die zwei Punkte von Konzentration und Fieser Trick; drück erneut, sobald du im Kampf bist, für Nierenhieb.",
        requires = "Talent Konzentration (das Zeitfenster beträgt in Forever 20 Sekunden, in Classic 10); Nierenhieb erlernt (Stufe 30)", mods = {  } },
      ["subtlety-preparation-reset"] = { title = "Fluchtfähigkeiten verbrauchen, dann Vorbereitung", use = "Entrinnen und Sprinten werden ausgelöst, und Vorbereitung setzt sie zurück; halte Shift für Verschwinden statt Entrinnen und hör auf zuzuschlagen.",
        requires = "Talent Vorbereitung; Entrinnen und Sprinten bereit", mods = { "Entrinnen und Sprinten, dann Vorbereitung", "Verschwinden und Sprinten, dann Vorbereitung" } },
      ["subtlety-sap-nearest"] = { title = "Nächsten Gegner anvisieren und Kopfnuss", use = "Stoppt deine Schläge, wählt den nächsten Gegner, wenn du kein feindliches Ziel hast, und setzt Kopfnuss; drück erneut, sobald du in Reichweite bist.",
        requires = "Kopfnuss erlernt (Stufe 10); ein Humanoide, der nicht im Kampf ist. Lösch vorher dein Ziel, wenn es die falsche Art Gegner ist", mods = {  } },
    },
  },
  PRIEST = {
    guides = {
      ["discipline"] = { name = "Disziplin", tagline = "Schilde beim Leveln", why = {
        "25% mehr Zauberstabschaden. Wenn du Mobs mit dem Zauberstab erledigst, sparst du Mana für den nächsten Pull; seit dem 15. Oktober stehst du eine halbe Sekunde still, bevor er schießt.",
        "Göttliche Pein und Sühne verursachen 6% mehr an einem Ziel, auf dem Heiliges Feuer oder seit dem 15. Oktober Schattenwort: Schmerz von dir liegt. Jeden Quest-Mob eröffnest du mit einem davon.",
        "8% mehr Intelligenz, also mehr Mana für Schilde und Heilungen. Am 15. Oktober rückte es in die zweite Reihe auf, mit 2% pro Rang.",
        "6% mehr Trefferchance mit Heiligzaubern, also verfehlen Göttliche Pein und Heiliges Feuer selten Mobs, die eine oder zwei Stufen über dir sind. Außerdem ist es dein 10. Punkt.",
        "Machtwort: Schild absorbiert 20% mehr. Das Talent ist am 15. Oktober in die dritte Reihe gerutscht; nimm alle drei Ränge, denn Seelenwehr setzt sie voraus.",
        "Ein Drittel deiner Manaregeneration läuft beim Zaubern weiter, und dieser 15. Punkt schaltet Seelenwehr frei.",
        "Machtwort: Schild verliert die Abklingzeit von 4 Sek. und kostet 15% weniger, also kannst du erst den Tank und dann dich selbst direkt nacheinander abschirmen.",
        "Der dritte Rang: Die Hälfte deiner Manaregeneration läuft jetzt beim Zaubern weiter.",
        "Alle 3 Min. ein kostenloser Zauber, mit 25% mehr Kritchance, wenn es ein Direktzauber ist. Heb ihn dir für eine große Heilung auf.",
        "Der fünfte Rang, für insgesamt 10% mehr Intelligenz.",
        "Deine Zauber erzeugen 10% weniger Bedrohung, seit dem 15. Oktober alle statt nur Heiligzauber. Außerdem ist es der 20. Punkt, der Sühne freischaltet.",
        "Drei Geschosse über 2 Sek., die einen Verbündeten um je 126 heilen oder einen Gegner für 42 treffen, mit 12 Sek. Abklingzeit. Seit dem 8. Oktober kostet der Zauber 150 Mana und wirkt schwächer als vorher.",
        "Deine Direktheilungen bekommen 10% mehr Krit auf Zielen mit Geschwächte Seele und verkürzen deren Dauer um 5 Sek., also kannst du ihnen früher wieder einen Schild geben.",
        "Deine kritischen Heilungen hinterlassen einen Schild in Höhe von 15% der Heilung, bis zu 1,200 Schaden. Mit Erneuerte Hoffnung heilst du auf Zielen mit Schild oft kritisch.",
        "Spontanzauber, Göttliche Pein und Heiliges Feuer kosten 3% weniger Mana. Mit diesem Punkt kommst du auf 30 in Disziplin.",
        "Das 31-Punkte-Talent von Disziplin: alle 3 Min. ein Schub für Zauberschaden und Heilung von jemandem. Leg es für einen Boss auf dich oder einen anderen Zauberwirker.",
        "Die letzten zwei Ränge von Mentale Beweglichkeit: Machtwort: Schild, Erneuerung und Göttliche Pein kosten 10% weniger Mana.",
        "Deine Spontanzauber verursachen und heilen 5% mehr, das gilt für Erneuerung, Schattenwort: Schmerz und Sühne.",
        "5% mehr Krit für Heiligzauber, also mehr Schilde von Göttliche Aegis.",
        "Göttliche Pein, Heiliges Feuer, Heilen und Große Heilung werden 0.5 Sek. schneller gewirkt.",
        "Erneuerung heilt um 15% mehr, und du kannst es in der Bewegung wirken.",
      } },
      ["holy"] = { name = "Heilig", tagline = "Direkte Heilung mit Schaden fürs Questen", why = {
        "Jeder Zauber, ob Heilung oder Göttliche Pein, hat eine Chance von 70%, die Verzögerung durch Schaden zu ignorieren.",
        "2% mehr Kritchance für Heiligzauber, also für deine Heilungen und Göttliche Pein.",
        "Göttliche Pein hat nur noch 2 Sek. Zauberzeit und Heilen 2.5 Sek., so tötest und heilst du schneller.",
        "Ein sofortiger Stoß um dich herum, der die Gruppe heilt und Gegner trifft, ganz ohne Bedrohung. Nutze ihn, wenn die Gruppe verletzt ist und eng bei dir steht.",
        "Trifft eine Direktheilung kritisch, bekommt das Ziel 15 Sek. lang 25% mehr Rüstung. Auf dem Tank heißt das weniger Schaden durch die nächsten Treffer.",
        "Ein dritter Rang für 3% Krit auf Heiligzauber, also mehr Inspiration am Tank. Außerdem ist es der 15. Punkt, für Holy Binding ab 25.",
        "Deine Blitzheilungen auf andere heilen dich um 50% dieses Betrags, ohne Bedrohung.",
        "Geringes Heilen und Heilen kosten 15% weniger Mana, was sich über einen langen Dungeon summiert.",
        "Göttliche Pein reicht 10% weiter und Heilige Nova deckt 10% mehr Fläche ab. Mit diesem 20. Punkt wird Geistige Führung frei.",
        "Wandelt 5% deiner Willenskraft in Zauberheilung und 1% in Zauberschaden um. Jeder weitere Rang nach 30 gibt mehr.",
        "Die letzten vier Ränge von Geistige Führung: Heilung in Höhe von 25% deiner Willenskraft und dazu ein wenig Zauberschaden.",
        "Alle deine Heilungen heilen 10% mehr, der größte Heilgewinn im Baum.",
        "Wechsle deine Heilungen ab, dann gibt jeder Zauber 5% seiner Grund-Manakosten zurück.",
        "Wenn du stirbst, heilst du als Geist noch 15 Sek. weiter. Gebet der Besserung braucht es, und es bringt dich auf 30 in Heilig.",
        "Das 31-Punkte-Talent von Heilig: eine Heilung, die auf ihrem Ziel wartet und bis zu 5-mal durch die Gruppe springt, wenn jemand Schaden nimmt. Leg sie vor dem Pull auf den Tank.",
        "Der letzte Rang von Litanei des Lichts: Wechselnde Heilungen geben 10% der Grundkosten jedes Zaubers zurück.",
        "Die letzten zwei Ränge von Heiligspezialisierung, 5% mehr Krit für Heiligzauber.",
        "Erneuerung heilt um 15% mehr, und du wirkst es in der Bewegung.",
        "Deine Spontanzauber verursachen und heilen 5% mehr: Erneuerung, Gebet der Besserung und Heilige Nova.",
        "10% mehr Intelligenz für einen größeren Manavorrat.",
        "Die Hälfte deiner Manaregeneration läuft beim Zaubern weiter, also kannst du auch einen langen Dungeon-Pull heilen.",
        "Alle 3 Min. ist dein nächster Zauber kostenlos und hat mehr Krit. Heb es dir für Gebet der Heilung auf.",
      } },
      ["shadow"] = { name = "Schatten", tagline = "Ausdauernder Schatten-Schaden solo", why = {
        "Ein getöteter Mob verdoppelt 15 Sek. lang deine Willenskraft, und die Hälfte deiner Manaregeneration läuft beim Zaubern weiter. Ein Kill mit dem Zauberstab zählt auch.",
        "Schattenwort: Schmerz hält 24 Sek. statt 18, ein Drittel mehr Schaden aus einem Zauber.",
        "Schattenzauber reichen 20% weiter, 36 Meter bei Gedankenschlag, so kannst du aus größerer Entfernung pullen.",
        "Gedankenschlag ist 0.5 Sek. früher wieder bereit. Das Talent ist am 15. Oktober eine Reihe nach oben gerückt, und dieser 10. Punkt schaltet Gedankenschinden ab 20 frei.",
        "Eine Kanalisierung über 3 Sek., die das Ziel um 50% verlangsamt, solange sie tickt. Fang damit an, während der Mob noch auf dich zuläuft.",
        "Seit dem 15. Oktober trifft jeder Tick von Gedankenschinden 20% härter als der vorige, und die Verlangsamung bleibt bei 50%. Lass den Kanalzauber durchlaufen, um den letzten, stärksten Tick mitzunehmen.",
        "2% mehr Trefferchance mit Schattenzaubern und der 15. Punkt, den Vampirumarmung braucht.",
        "30 Sek. lang heilen 20% deines Schattenschadens deine Gruppe, und seit dem 15. Oktober ist es alle 30 Sek. wieder bereit. Stirbt das Ziel, während es aktiv ist, löst Willensentzug aus, auch wenn jemand anderes den Kill bekommt.",
        "Jeder Schattenzauber lässt das Ziel 15 Sek. lang 2% mehr Schattenschaden von dir erleiden, stapelbar bis 10%. Am meisten bringt das bei Elites und in langen Kämpfen.",
        "Gedankenschlag und vollständig kanalisiertes Gedankenschinden geben dir und deiner Gruppe 10 Sek. lang 3% mehr Willenskraft, zusätzlich zu Willensentzug. Außerdem ist es der 20. Punkt, der Stille freischaltet.",
        "Bringt einen Zauberwirker 5 Sek. lang zum Schweigen, alle 45 Sek. Ziel damit auf die Heilung eines Mobs oder einen großen Zauber.",
        "Verschlingende Seuche kostet nur halb so viel Mana und springt auf Gegner in der Nähe über, wenn sein Ziel stirbt.",
        "Gedankenschlag ist 1 Sek. früher wieder bereit, also bekommst du in jedem Kampf mehr davon unter.",
        "10% mehr Schattenschaden. Mit diesen Punkten kommst du auf 30 in Schatten.",
        "Das 31-Punkte-Talent von Schatten: 10% mehr Schattenschaden, Schattenzauber zum halben Preis, doppelter Kritbonus und 15% weniger erlittener körperlicher Schaden. Darin kannst du nicht heilen, also heil, bevor du die Gestalt wechselst.",
        "Die letzten zwei Ränge von Verbesserter Gedankenschlag, insgesamt 2.5 Sek. weniger Abklingzeit.",
        "Die letzten drei Ränge von Schattenfokus, für 5% mehr Trefferchance mit Schattenzaubern bei Mobs über deiner Stufe.",
        "Schattenwort: Tod bekommt 30% mehr Krit auf Zielen mit 20% Gesundheit oder weniger, also ist es dein Finisher.",
        "Deine Spontanzauber verursachen 5% mehr: Schattenwort: Schmerz, Schattenwort: Tod, Verschlingende Seuche und Gedankenschinden.",
        "10% mehr Intelligenz, also trinkst du zwischen den Pulls weniger.",
        "Die Hälfte deiner Manaregeneration läuft beim Zaubern weiter, was sich dank Willensentzug nach jedem Kill richtig auszahlt.",
      } },
    },
    macros = {
      ["class-wide-dispel"] = { title = "Magiebannung aufs Mouseover", use = "Banne ein freundliches oder feindliches Mouseover oder dein ausgewähltes Ziel.",
        requires = "Magiebannung erlernt", mods = {  } },
      ["class-wide-fear-ward"] = { title = "Furchtzauberschutz aufs Mouseover", use = "Schütze den Verbündeten unter deinem Mauszeiger gegen Furcht, sonst dein Ziel, oder dich selbst, wenn keiner davon freundlich ist.",
        requires = "Furchtzauberschutz erlernt (Stufe 20). In Forever bekommt jeder Priester den Zauber, mit 3 Min. Abklingzeit und 3 Min. Schutz. In Classic war es eine Volksfähigkeit.", mods = {  } },
      ["class-wide-fortitude"] = { title = "Seelenstärke aufs Mouseover", use = "Buffe eine freundliche Einheit unter deinem Mauszeiger, ohne das Ziel zu wechseln.",
        requires = "", mods = {  } },
      ["class-wide-lesser-heal-or-smite"] = { title = "Geringes Heilen auf Verbündete, Göttliche Pein auf Gegner", use = "Heile zuerst ein freundliches Mouseover-Ziel. Sonst wirke Göttliche Pein auf ein feindliches Ziel, heile ein freundliches Ziel oder, ohne gültiges Ziel, dich selbst. Nützlich ab Stufe 1.",
        requires = "", mods = {  } },
      ["class-wide-levitate"] = { title = "Absteigen und Levitieren", use = "Steig vom Reittier und wirke Levitieren auf dich selbst. Halte Shift, um Levitieren abzubrechen.",
        requires = "Levitieren erlernt (Stufe 34). Aufsitzen oder erlittener Schaden beendet den Effekt.", mods = { "Steig ab, dann Levitieren auf dich selbst", "Levitieren abbrechen" } },
      ["class-wide-resurrection"] = { title = "Auferstehung aufs Mouseover", use = "Belebe den toten Spieler unter deinem Mauszeiger oder dein totes Ziel wieder.",
        requires = "Auferstehung erlernt. Kann nicht im Kampf gewirkt werden.", mods = {  } },
      ["class-wide-self-buffs"] = { title = "Selbstbuffs der Reihe nach", use = "Stärke dich selbst, ein Zauber pro Tastendruck: Inneres Feuer, dann Machtwort: Seelenstärke, dann Göttlicher Willen.",
        requires = "Göttlicher Willen erlernt (Stufe 30). In Forever ist der Zauber Grundausstattung, deshalb kommt er in die Stärkungszauber-Sequenz aus Classic. Bis du ihn hast, lass ihn am Ende weg.", mods = {  } },
      ["class-wide-shackle-undead"] = { title = "Untote fesseln aufs Mouseover", use = "Fessle einen untoten Gegner unter deinem Mauszeiger oder dein Ziel, ohne zu wechseln, was du angreifst.",
        requires = "Untote fesseln erlernt (Stufe 20). Es kann immer nur ein Ziel gefesselt sein.", mods = {  } },
      ["class-wide-wand"] = { title = "Zauberstab, der an bleibt", use = "Zauberstab starten. Erneutes Drücken lässt ihn weiterschießen, statt ihn abzuschalten.",
        requires = "Ein Zauberstab im Fernkampfplatz", mods = {  } },
      ["discipline-contingency-plan"] = { title = "Notfallplan aufs Mouseover", use = "Schütze einen Verbündeten unter deinem Mauszeiger, dein Ziel oder dich selbst. Fällt seine Gesundheit unter 35 %, bekommt er einen Schild und eine Heilung über Zeit. Schild und HoT davon können neben Machtwort: Schild und Erneuerung bestehen.",
        requires = "Gnom-Priester, Stufe 20; ein Schutz pro Ziel. Blizzards Guide vom 30. September nennt 5 Min. Abklingzeit; der Live-Client zeigt noch 10 Min.", mods = {  } },
      ["discipline-divine-grace"] = { title = "Göttliche Anmut auf einen verletzten Verbündeten", use = "Heile einen Verbündeten unter halber Gesundheit sofort und entferne seine Geschwächte Seele, damit du ihm wieder einen Schild geben kannst.",
        requires = "Menschen-Priester. Ziel unter 50 % Gesundheit; nicht auf dich selbst. Blizzards Guide vom 30. September nennt 5 Min. Abklingzeit; der Live-Client zeigt noch 10 Min.", mods = {  } },
      ["discipline-divine-spirit"] = { title = "Göttlicher Willen aufs Mouseover", use = "Gib dem Verbündeten unter deinem Mauszeiger Göttlicher Willen, sonst deinem Ziel oder dir selbst.",
        requires = "Göttlicher Willen erlernt (Stufe 30). In Forever bekommt jeder Priester den Zauber. In Classic war es ein Disziplin-Talent.", mods = {  } },
      ["discipline-inner-focus-heal"] = { title = "Innerer Fokus vor Große Heilung", use = "Zünde Innerer Fokus und wirke Große Heilung kostenlos auf dein Mouseover-Ziel, dein Ziel oder dich selbst.",
        requires = "Talent Innerer Fokus und Große Heilung erlernt (Stufe 40)", mods = {  } },
      ["discipline-mana-burn"] = { title = "Manabrand aufs Mouseover", use = "Verbrenne das Mana eines anderen Gegners und behalte dabei dein ausgewähltes Ziel.",
        requires = "Manabrand erlernt", mods = {  } },
      ["discipline-penance"] = { title = "Sühne zum Heilen, Shift für Schaden", use = "Heile ein freundliches Mouseover-Ziel, dein Ziel oder dich selbst; halte Shift, um deinem feindlichen Ziel Schaden zuzufügen. Wiederholtes Drücken lässt die laufende Kanalisierung von Sühne zu Ende laufen.",
        requires = "Talent Sühne (Disziplin). Rang 1 gibt es ab Stufe 30, mit 12 Sek. Abklingzeit.", mods = { "Mouseover heilen, dann Ziel, dann dich selbst", "Schaden auf dein feindliches Ziel" } },
      ["discipline-power-infusion"] = { title = "Seele der Macht auf einen Verbündeten oder dich", use = "Leg Seele der Macht auf den Verbündeten unter deinem Mauszeiger, dann dein Ziel, dann dich selbst. Alt wählt immer dich.",
        requires = "Talent Seele der Macht (Disziplin, Stufe 40)", mods = { "Seele der Macht auf Mouseover, dann Ziel, dann dich selbst", "Seele der Macht auf dich selbst" } },
      ["discipline-prayer-of-fortitude"] = { title = "Gebet der Seelenstärke aufs Mouseover", use = "Wirke Gebet der Seelenstärke auf den Verbündeten unter deinem Mauszeiger, dein Ziel oder dich selbst.",
        requires = "Gebet der Seelenstärke erlernt (Stufe 48). Der Tooltip in Forever umfasst alle Gruppen- und Schlachtgruppenmitglieder, in Classic war es die Gruppe des Ziels.", mods = {  } },
      ["discipline-shield"] = { title = "Machtwort: Schild aufs Mouseover", use = "Schild auf ein freundliches Mouseover, dein Ziel oder dich selbst.",
        requires = "Machtwort: Schild erlernt", mods = {  } },
      ["discipline-shield-downrank"] = { title = "Machtwort: Schild, Rang 6 mit Shift", use = "Schild auf dein Mouseover, Ziel oder dich selbst. Halte Shift für Rang 6, wenn ein leichterer, günstigerer Schild reicht.",
        requires = "Machtwort: Schild Rang 6 erlernt (Stufe 36)", mods = { "Schild im höchsten Rang auf Mouseover, Ziel oder dich", "Schild Rang 6 auf dasselbe Ziel" } },
      ["discipline-shield-modifiers"] = { title = "Machtwort: Schild mit Shift und Alt", use = "Schild auf dein Mouseover, Ziel oder dich selbst. Shift schützt das Ziel deines Ziels, Alt schützt dich.",
        requires = "Machtwort: Schild erlernt", mods = { "Schild auf Mouseover, dann Ziel, dann dich selbst", "Schild auf das Ziel deines Ziels, wenn es ein Verbündeter ist", "Schild auf dich selbst" } },
      ["holy-disease-cleanse"] = { title = "Krankheit aufheben, Krankheit heilen mit Shift", use = "Krankheit aufheben auf dein Mouseover-Ziel, dein Ziel oder dich selbst. Halte Shift, um einmalig Krankheit heilen zu wirken.",
        requires = "Krankheit aufheben erlernt (Stufe 32). Vorher nutzt du ein eigenes Makro nur für Krankheit heilen.", mods = { "Krankheit aufheben auf dein Mouseover-Ziel, dein Ziel oder dich", "Krankheit heilen auf dasselbe Ziel" } },
      ["holy-flash-heal"] = { title = "Blitzheilung aufs Mouseover", use = "Heile ein Gruppenfenster unter deinem Mauszeiger, sonst dein Ziel, sonst dich selbst.",
        requires = "Blitzheilung erlernt", mods = {  } },
      ["holy-greater-heal"] = { title = "Große Heilung, Rang 1 mit Shift", use = "Große Heilung auf dein Mouseover-Ziel, dein Ziel oder dich selbst. Halte Shift für Rang 1, wenn der Schaden gering ist.",
        requires = "Große Heilung erlernt (Stufe 40)", mods = { "Große Heilung im höchsten Rang auf dein Mouseover-Ziel, dein Ziel oder dich", "Große Heilung Rang 1 auf dasselbe Ziel" } },
      ["holy-holy-fire"] = { title = "Heiliges Feuer oder Göttliche Pein", use = "Halte Shift für Göttliche Pein; normal drücken für Heiliges Feuer.",
        requires = "Heiliges Feuer erlernt", mods = { "Heiliges Feuer wirken", "Göttliche Pein wirken" } },
      ["holy-litany-alternate"] = { title = "Zwei Heilungen abwechseln für Litanei des Lichts", use = "Wechsle Blitzheilung und Große Heilung auf einer Taste ab, damit sich jeder Zauber vom letzten unterscheidet. Genau das belohnt Litanei des Lichts.",
        requires = "Talent Litanei des Lichts (Heilig) und Große Heilung erlernt (Stufe 40). Die Sequenz beginnt nach 4 Sekunden ohne Tastendruck von vorn.", mods = {  } },
      ["holy-prayer-of-healing"] = { title = "Gebet der Heilung auf eine gewählte Gruppe", use = "Wirke Gebet der Heilung auf den Verbündeten unter deinem Mauszeiger, um seine Gruppe samt Begleitern zu heilen. So wählst du, welche Gruppe die Heilung bekommt.",
        requires = "Gebet der Heilung erlernt (Stufe 30). Blizzard bestätigt, dass der Zauber die Gruppe des Ziels samt Begleitern heilt; der Client nennt einen Radius von 40 Metern. In Classic wurde deine eigene Gruppe geheilt.", mods = {  } },
      ["holy-prayer-of-mending"] = { title = "Gebet der Besserung aufs Mouseover", use = "Leg Gebet der Besserung auf dein Mouseover-Ziel, dein Ziel oder dich selbst. Schaden oder nicht-periodische Heilung lösen die Heilung und einen Sprung zu einem Gruppen- oder Schlachtgruppenmitglied in der Nähe aus.",
        requires = "Talent Gebet der Besserung (Heilig); Rang 1 gibt es laut Client ab Stufe 40, mit 10 Sek. Abklingzeit. Blizzard beschreibt fünf Heilungen und eine aktive Anwendung pro Ziel; der Tooltip nennt fünf Sprünge und ein Ziel pro Zauberwirker. Diese Grenzen haben wir im Spiel noch nicht getestet.", mods = {  } },
      ["holy-pull-wand"] = { title = "Pull mit Heiliges Feuer, dann Zauberstab", use = "Eröffne beim ersten Tastendruck mit Heiliges Feuer und drück dann erneut, um mit dem Zauberstab zu schießen.",
        requires = "Heiliges Feuer erlernt und ein Zauberstab angelegt", mods = {  } },
      ["holy-renew"] = { title = "Erneuerung aufs Mouseover, Rang 5 mit Shift", use = "Erneuerung auf dein Mouseover-Ziel, dein Ziel oder dich selbst. Halte Shift für Rang 5, um Mana zu sparen. Blizzard bestätigt, dass Erneuerung von verschiedenen Priestern gleichzeitig auf demselben Ziel aktiv bleiben kann.",
        requires = "Erneuerung erlernt. Rang 5 kommt auf Stufe 32.", mods = { "Erneuerung im höchsten Rang auf dein Mouseover-Ziel, dein Ziel oder dich", "Erneuerung Rang 5 auf dasselbe Ziel" } },
      ["holy-smite-target-of-target"] = { title = "Göttliche Pein auf das Ziel deines Tanks", use = "Göttliche Pein auf dein feindliches Ziel oder auf den Gegner, den dein freundliches Ziel angreift. Lass deinen Tank im Ziel, während du zwischen Heilungen Schaden machst; eine laufende Kanalisierung wird nicht unterbrochen.",
        requires = "", mods = {  } },
      ["pvp-assist-flay"] = { title = "Gedankenschinden auf das Ziel deines Verbündeten", use = "Gedankenschinden auf dein feindliches Ziel. Hast du einen Verbündeten im Ziel, triffst und verlangsamst du dessen Ziel, etwa den Gegner, den dein Krieger jagt, ohne den Verbündeten aus dem Ziel zu nehmen.",
        requires = "Talent Gedankenschinden (Schatten, Stufe 20)", mods = {  } },
      ["pvp-chastise"] = { title = "Züchtigung auf Ziel oder Mouseover", use = "Züchtigung auf dein Ziel, um es 2 Sekunden lang bewegungsunfähig zu machen. Halte Shift für dein Mouseover-Ziel.",
        requires = "Zwergen-Priester. Züchtigung ist in Forever eine Volksfähigkeit der Zwerge (2 Min. Abklingzeit, 20 Meter). Sie wirkt nur auf Humanoide.", mods = { "Züchtigung auf dein Ziel", "Züchtigung auf dein Mouseover-Ziel" } },
      ["pvp-confounding-flash"] = { title = "Stoppen und Verwirrender Lichtblitz", use = "Brich deinen Zauber ab und verwirre 3 Sekunden lang jeden Gegner im Umkreis von 8 Metern. Jeder Schaden bricht es.",
        requires = "Gnomen-Priester. Verwirrender Lichtblitz ist eine Volksfähigkeit der Gnome (Stufe 10, 0.5 Sek. Zauberzeit, 2 Min. Abklingzeit).", mods = {  } },
      ["pvp-control"] = { title = "Gedankenkontrolle, Shift für Untote fesseln", use = "Gedankenkontrolle auf den Gegner unter deinem Mauszeiger oder auf dein Ziel. Halte Shift, um stattdessen Untote fesseln zu wirken.",
        requires = "Gedankenkontrolle erlernt (Stufe 30). Rang 3 wirkt auf Humanoide bis Stufe 62. Untote fesseln für Shift erlernt.", mods = { "Gedankenkontrolle auf dein Mouseover-Ziel, dann dein Ziel", "Untote fesseln auf dein Mouseover-Ziel, dann dein Ziel" } },
      ["pvp-desperate-prayer"] = { title = "Verzweifeltes Gebet, Shift für einen Schild", use = "Brich deinen Zauber ab und nutze Verzweifeltes Gebet. Halte Shift, um dich stattdessen mit einem Schild zu schützen.",
        requires = "Zwergen-Priester. Verzweifeltes Gebet ist in Forever eine Volksfähigkeit der Zwerge (10 Min. Abklingzeit). Menschen bekommen stattdessen Göttliche Anmut.", mods = { "Brich deinen Zauber ab, Verzweifeltes Gebet", "Zauber stoppen, Schild auf dich selbst" } },
      ["pvp-dispel-keys"] = { title = "Magiebannung auf vier Ziele", use = "Eine Taste für Magiebannung: standardmäßig dein Ziel, mit Shift dein Mouseover-Ziel, mit Ctrl du selbst, mit Alt das Ziel deines Ziels.",
        requires = "Magiebannung erlernt", mods = { "Dein Ziel bannen", "Dein Mouseover bannen", "Dich selbst bannen", "Ziel deines Ziels bannen, wenn es ein Verbündeter ist" } },
      ["pvp-dot-button"] = { title = "Schattenwort: Schmerz, Shift für Verschlingende Seuche", use = "Schattenwort: Schmerz auf dein Mouseover-Ziel oder Ziel. Halte Shift für Verschlingende Seuche auf dasselbe Ziel.",
        requires = "Verschlingende Seuche erlernt (Stufe 20). In Forever bekommt jeder Priester den Zauber, mit 24 Sek. Abklingzeit.", mods = { "Schattenwort: Schmerz auf dein Mouseover-Ziel, dann dein Ziel", "Verschlingende Seuche auf dein Mouseover-Ziel, dann dein Ziel" } },
      ["pvp-elunes-grace"] = { title = "Elunes Anmut, Shift für einen Schild", use = "Brich deinen Zauber ab und nutze Elunes Anmut, wenn ein Nahkämpfer oder Jäger auf dich losgeht. Halte Shift, um dich stattdessen mit einem Schild zu schützen.",
        requires = "Nachtelfen-Priester. Elunes Anmut ist eine Volksfähigkeit der Nachtelfen (Stufe 20, 5 Min. Abklingzeit). In Forever treffen dich Nah- und Fernkampfangriffe damit 15 Sek. lang oder bis drei verfehlt haben mit 50% geringerer Chance. In Classic senkte sie den Fernkampfschaden und erhöhte das Ausweichen.", mods = { "Brich deinen Zauber ab, Elunes Anmut", "Zauber stoppen, Schild auf dich selbst" } },
      ["pvp-emergency-heal"] = { title = "Stoppen und Blitzheilung", use = "Brich deinen Zauber ab und wirke Blitzheilung auf dein Mouseover-Ziel, dein Ziel oder dich selbst. Halte Shift, um dich selbst zu heilen.",
        requires = "Blitzheilung erlernt", mods = { "Zauber stoppen, Mouseover, Ziel oder dich heilen", "Zauber stoppen, dich selbst heilen" } },
      ["pvp-feedback"] = { title = "Stoppen und Rückkopplung", use = "Brich deinen Zauber ab und aktiviere Rückkopplung. 15 Sek. lang verbrennt jeder Zauber, der dich trifft, etwas Mana des Zauberwirkers und fügt ihm für jeden verbrannten Punkt Schattenschaden zu.",
        requires = "Menschen-Priester. Rückkopplung ist in Forever eine Volksfähigkeit der Menschen (Stufe 20, 3 Min. Abklingzeit). Rang 1 verbrennt 18 Mana pro Zauber.", mods = {  } },
      ["pvp-flash-heal-enemy-target"] = { title = "Blitzheilung über dein gegnerisches Ziel", use = "Blitzheilung auf dein freundliches Mouseover-Ziel oder Ziel. Hast du einen Gegner im Ziel, heilt das Makro den Verbündeten, hinter dem dieser Gegner her ist. So musst du den Gegner nie aus dem Ziel nehmen.",
        requires = "Talent Holy Binding (Heilig), damit jede Blitzheilung auf einem Verbündeten auch dich um die Hälfte heilt", mods = {  } },
      ["pvp-flash-heal-party"] = { title = "Stoppen und Blitzheilung, party 1 oder 2", use = "Brich deinen Zauber ab und wirke Blitzheilung auf dein freundliches Mouseover-Ziel oder Ziel. Shift heilt Gruppenmitglied 1, Ctrl Gruppenmitglied 2, und Holy Binding heilt dich jedes Mal um die Hälfte.",
        requires = "Talent Holy Binding (Heilig) für die Heilung auf dir", mods = { "Brich deinen Zauber ab, Blitzheilung auf dein Mouseover-Ziel, dann dein Ziel", "Brich deinen Zauber ab, Blitzheilung auf Gruppenmitglied 1", "Brich deinen Zauber ab, Blitzheilung auf Gruppenmitglied 2" } },
      ["pvp-flay-death"] = { title = "Gedankenschinden, Shift für Schattenwort: Tod", use = "Gedankenschinden auf dein feindliches Ziel, ohne die Kanalisierung neu zu starten. Halte Shift, um die Kanalisierung abzubrechen und dein feindliches Mouseover-Ziel oder Ziel mit Schattenwort: Tod zu erledigen.",
        requires = "Talent Gedankenschinden (Schatten, Stufe 20) und Schattenwort: Tod erlernt (Stufe 32). Trifft Schattenwort: Tod und tötet nicht, erleidest du 30% deiner maximalen Gesundheit als Schaden. Vorzeitiges Ableben (Schatten) erhöht die kritische Trefferchance bei 20% Gesundheit oder weniger.", mods = { "Gedankenschinden auf dein feindliches Ziel, sofern du es nicht schon kanalisierst", "Brich die Kanalisierung ab, Schattenwort: Tod auf dein Mouseover-Ziel, dann dein Ziel" } },
      ["pvp-flay-silence"] = { title = "Gedankenschinden, Shift für Stille", use = "Gedankenschinden auf dein feindliches Ziel, ohne die Kanalisierung neu zu starten. Halte Shift, um die Kanalisierung abzubrechen und Stille auf dein feindliches Mouseover-Ziel oder Ziel zu wirken. So liegt deine Unterbrechung auf deiner Hauptschadenstaste.",
        requires = "Talente Gedankenschinden und Stille (Schatten). Stille kommt auf Stufe 30, mit 20 Metern Reichweite und 45 Sek. Abklingzeit.", mods = { "Gedankenschinden auf dein feindliches Ziel, sofern du es nicht schon kanalisierst", "Brich die Kanalisierung ab, Stille auf dein Mouseover-Ziel, dann dein Ziel" } },
      ["pvp-form-blast-or-heal"] = { title = "Gedankenschlag in Schattengestalt, Blitzheilung außerhalb", use = "In Schattengestalt wirkt es Gedankenschlag auf dein feindliches Mouseover oder Ziel. Außerhalb der Schattengestalt wirkt dieselbe Taste Blitzheilung auf dein freundliches Mouseover oder dich, also deckt eine Belegung beide Seiten eines Gestaltwechsels ab.",
        requires = "Talent Schattengestalt (Schatten, Stufe 40) und Blitzheilung erlernt (Stufe 20). Classic-Makros zählen Schattengestalt als Gestalt 1. Im Forever-Client haben wir das noch nicht geprüft.", mods = {  } },
      ["pvp-hex-of-weakness"] = { title = "Verhexung der Schwäche auf Ziel oder Mouseover", use = "Leg Verhexung der Schwäche auf dein Ziel. Das senkt seine Nahkampf-Angriffskraft und die Heilung, die es erhält. Halte Shift für dein Mouseover-Ziel.",
        requires = "Troll-Priester. Verhexung der Schwäche ist eine Volksfähigkeit der Trolle. In Forever senkt sie die Nahkampf-Angriffskraft, in Classic senkte sie den Schaden. Blizzards Übersicht vom 30. September nennt sie unverändert; die Beschreibungen im gespeicherten Client und in Classic unterscheiden sich.", mods = { "Dein Ziel verhexen", "Dein Mouseover verhexen" } },
      ["pvp-holy-fire-nova"] = { title = "Heiliges Feuer, Shift für Heilige Nova", use = "Heiliges Feuer auf dein feindliches Mouseover-Ziel oder Ziel. Halte Shift für Heilige Nova, sobald der Gegner nah dran ist; Sengendes Licht kann den Zauber nach den Schadensticks von Heiliges Feuer kostenlos machen.",
        requires = "Talente Heilige Nova und Sengendes Licht (Heilig). Sengendes Licht gibt jedem Tick von Heiliges Feuer eine Chance, dass Heilige Nova beim nächsten Mal kein Mana kostet.", mods = { "Heiliges Feuer auf dein feindliches Mouseover-Ziel, dann dein Ziel", "Heilige Nova um dich herum" } },
      ["pvp-holy-nova-sweep"] = { title = "Heilige Nova Rang 1 als Rundumschlag, Shift für höchsten Rang", use = "Heilige Nova Rang 1 trifft Gegner im Umkreis von 10 Metern für wenig Mana, genug, um einen Schurken oder Druiden in der Nähe aus der Verstohlenheit zu holen. Halte Shift, um deinen Zauber abzubrechen und deinen höchsten Rang als schnelle Gruppenheilung zu nutzen.",
        requires = "Talent Heilige Nova (Heilig). Rang 1 kostet 185 Mana, der Rang auf Stufe 60 kostet 750.", mods = { "Heilige Nova Rang 1", "Brich deinen Zauber ab, Heilige Nova im höchsten Rang" } },
      ["pvp-inner-focus-flash-heal"] = { title = "Stoppen, Innerer Fokus und Blitzheilung", use = "Brich deinen Zauber ab, zünde Innerer Fokus und wirke Blitzheilung auf dein Mouseover-Ziel, dein freundliches Ziel, das Ziel deines Gegners oder dich selbst. Shift heilt dich. Hat Innerer Fokus Abklingzeit, kommt die Heilung trotzdem.",
        requires = "Talent Innerer Fokus (Disziplin, 3 Min. Abklingzeit) und Blitzheilung erlernt (Stufe 20)", mods = { "Brich deinen Zauber ab, Innerer Fokus, Blitzheilung auf dein Mouseover-Ziel, dein Ziel, das Ziel des Gegners oder dich", "Brich deinen Zauber ab, Innerer Fokus, Blitzheilung auf dich selbst" } },
      ["pvp-inner-focus-mana-burn"] = { title = "Innerer Fokus vor Manabrand", use = "Zünde Innerer Fokus, damit Manabrand beim nächsten Mal nichts kostet, und starte den Zauber dann auf deinem feindlichen Mouseover-Ziel oder Ziel. Ist kein Gegner da, wartet Innerer Fokus auf deinen nächsten Zauber.",
        requires = "Talent Innerer Fokus (Disziplin) und Manabrand erlernt (Stufe 24). Verbesserter Manabrand (Disziplin) verkürzt die Zauberzeit von 3 Sek. um bis zu 1 Sek.", mods = {  } },
      ["pvp-inner-focus-mind-blast"] = { title = "Innerer Fokus vor Gedankenschlag", use = "Zünde Innerer Fokus und wirke Gedankenschlag auf dein feindliches Mouseover-Ziel oder Ziel: Gedankenschlag kostenlos und mit höherer Chance auf einen Krit. Ein guter Opener gegen Zauberwirker.",
        requires = "Talent Innerer Fokus (Disziplin, 3 Min. Abklingzeit). Gedankenschlag erlernt (Stufe 10).", mods = {  } },
      ["pvp-inner-focus-penance"] = { title = "Innerer Fokus vor Sühne", use = "Zünde Innerer Fokus und wirke Sühne kostenlos auf dein Mouseover-Ziel, dein freundliches Ziel, das Ziel deines Gegners oder dich selbst. Shift richtet den Zauber auf dein feindliches Ziel. Drückst du erneut, darf Sühne zu Ende kanalisieren.",
        requires = "Talente Innerer Fokus und Sühne (Disziplin). Sühne Rang 1 gibt es ab Stufe 30, mit 12 Sek. Abklingzeit.", mods = { "Innerer Fokus, Sühne als Heilung auf dein Mouseover-Ziel, dein Ziel, das Ziel des Gegners oder dich", "Innerer Fokus, Sühne für Schaden auf dein feindliches Ziel" } },
      ["pvp-litany-renew-flash"] = { title = "Erneuerung und Blitzheilung abwechseln", use = "Wechsle Erneuerung und Blitzheilung auf deinem Mouseover-Ziel, deinem freundlichen Ziel oder dem Ziel deines Gegners ab. Litanei des Lichts gibt Mana zurück, wenn sich jede Heilung von der letzten unterscheidet, und Erneuerung hat keine Zauberzeit.",
        requires = "Talent Litanei des Lichts (Heilig); Holy Binding heilt dich um die Hälfte jeder Blitzheilung. Die Sequenz beginnt nach 4 Sekunden ohne Tastendruck von vorn.", mods = {  } },
      ["pvp-mending-enemy-target"] = { title = "Gebet der Besserung über dein gegnerisches Ziel", use = "Leg Gebet der Besserung auf dein freundliches Mouseover-Ziel oder Ziel. Hast du einen Gegner im Ziel, geht der Zauber auf den Verbündeten, hinter dem dieser Gegner her ist, oder auf dich. Alt wählt immer dich, praktisch, bevor ein Schurke eröffnet.",
        requires = "Talent Gebet der Besserung (Heilig); Rang 1 gibt es laut Client ab Stufe 40, mit 10 Sek. Abklingzeit. Du kannst immer nur eins gleichzeitig aktiv haben.", mods = { "Gebet der Besserung auf Mouseover, Ziel, Ziel deines Gegners, sonst dich", "Gebet der Besserung auf dich selbst" } },
      ["pvp-mind-flay-rank-1"] = { title = "Gedankenschinden Rang 1 zum Verlangsamen, Shift für höchsten Rang", use = "Gedankenschinden Rang 1 verlangsamt dein feindliches Ziel für einen Bruchteil des Manas um 50%. Oft reicht das, um einen Nahkämpfer zu kiten. Halte Shift für deinen höchsten Rang. Keins von beiden startet eine laufende Kanalisierung neu.",
        requires = "Talent Gedankenschinden (Schatten, Stufe 20). Rang 1 kostet 45 Mana, der Rang auf Stufe 60 kostet 205.", mods = { "Gedankenschinden Rang 1 auf dein feindliches Ziel", "Gedankenschinden im höchsten Rang auf dein feindliches Ziel" } },
      ["pvp-mind-flay-slow"] = { title = "Gedankenschinden zum Verlangsamen auf Ziel oder Mouseover", use = "Gedankenschinden auf dein Ziel, ohne die Kanalisierung neu zu starten. Halte Shift, um stattdessen dein Mouseover-Ziel zu verlangsamen.",
        requires = "Talent Gedankenschinden (Schatten, Stufe 20). Es verlangsamt das Ziel um 50%; seit dem 15. Oktober lässt Verbessertes Gedankenschinden stattdessen jeden Tick härter treffen.", mods = { "Gedankenschinden auf dein Ziel", "Gedankenschinden auf dein Mouseover-Ziel" } },
      ["pvp-nearest-enemy-pain"] = { title = "Nächster Gegner, dann Schattenwort: Schmerz", use = "Nimm den nächsten Gegner ins Ziel, wenn du kein lebendes feindliches Ziel hast, und leg dann Schattenwort: Schmerz darauf.",
        requires = "", mods = {  } },
      ["pvp-pain-rank-1"] = { title = "Schattenwort: Schmerz Rang 1 gegen Verstohlene", use = "Leg Schattenwort: Schmerz im günstigen Rang 1 auf dein feindliches Mouseover-Ziel oder Ziel. Die Ticks brechen Verstohlenheit, also kann ein Schurke oder Druide kaum entwischen, solange der Effekt läuft.",
        requires = "Schattenwort: Schmerz erlernt. Rang 1 kostet 25 Mana und hält 18 Sek. Ein höherer Rang, den du schon auf das Ziel gelegt hast, wird dadurch nicht ersetzt.", mods = {  } },
      ["pvp-penance-enemy-target"] = { title = "Sühne auf einen Gegner, Shift zum Heilen seines Ziels", use = "Sühne auf dein feindliches Mouseover-Ziel oder Ziel. Halte Shift, um stattdessen den Verbündeten zu heilen, hinter dem dein anvisierter Gegner her ist, ohne das Ziel zu wechseln. Drückst du erneut, darf Sühne zu Ende kanalisieren.",
        requires = "Talent Sühne (Disziplin). Rang 1 gibt es ab Stufe 30, mit 12 Sek. Abklingzeit.", mods = { "Sühne für Schaden auf dein feindliches Mouseover-Ziel, dann dein Ziel", "Sühne als Heilung auf das Ziel deines Gegners, wenn es ein Verbündeter ist" } },
      ["pvp-power-infusion-party"] = { title = "Seele der Macht auf party 1 oder 2", use = "Seele der Macht auf dein freundliches Mouseover oder Ziel. Shift wirkt sie auf Gruppenmitglied 1, Ctrl auf Gruppenmitglied 2 und Alt auf dich, so gibst du sie deinem Caster, ohne das Ziel zu wechseln.",
        requires = "Talent Seele der Macht (Disziplin, Stufe 40). Es hat 3 Min. Abklingzeit.", mods = { "Seele der Macht auf Mouseover, dann freundliches Ziel, dann dich selbst", "Seele der Macht auf Gruppenmitglied 1", "Seele der Macht auf Gruppenmitglied 2", "Seele der Macht auf dich selbst" } },
      ["pvp-scream-fade"] = { title = "Psychischer Schrei, Shift für Verblassen", use = "Brich deinen aktuellen Zauber ab und wirke dann Psychischer Schrei auf die Gegner um dich herum. Halte Shift, um stattdessen Verblassen zu nutzen. Laut Blizzards Guide vom 30. September ist die Bedrohungssenkung von Verblassen verdoppelt.",
        requires = "", mods = { "Brich deinen Zauber ab, Psychischer Schrei", "Brich deinen Zauber ab, Verblassen" } },
      ["pvp-shadow-protection"] = { title = "Schattenschutz, Shift für die Gruppe", use = "Gib deinem Mouseover-Ziel, deinem Ziel oder dir selbst Schattenwiderstand. Halte Shift für Gebet des Schattenschutzes.",
        requires = "Schattenschutz erlernt (Stufe 30). Gebet des Schattenschutzes kommt auf Stufe 56, und der Tooltip in Forever umfasst alle Gruppen- und Schlachtgruppenmitglieder.", mods = { "Schattenschutz auf dein Mouseover-Ziel, dein Ziel oder dich", "Gebet des Schattenschutzes" } },
      ["pvp-shadowform-flay"] = { title = "Gedankenschinden, das Schattengestalt wieder aktiviert", use = "Außerhalb von Schattengestalt bringt dich der erste Tastendruck zurück hinein. In der Gestalt wirkt dieselbe Taste Gedankenschinden auf dein feindliches Mouseover-Ziel oder Ziel, ohne die Kanalisierung neu zu starten. Praktisch, nachdem du die Gestalt zum Heilen verlassen hast.",
        requires = "Talente Schattengestalt und Gedankenschinden (Schatten); Schattengestalt kommt auf Stufe 40 und kostet jedes Mal 40% des Grundmanas. Classic-Makros zählen Schattengestalt als Gestalt 1. Im Forever-Client haben wir das noch nicht geprüft.", mods = {  } },
      ["pvp-shield-party"] = { title = "Schild auf party 1 oder 2, oder auf das Ziel deines Gegners", use = "Schild auf dein freundliches Mouseover oder Ziel. Mit einem Gegner im Ziel schützt es den Verbündeten, den dieser Gegner im Ziel hat, oder dich. Shift schützt Gruppenmitglied 1 und Ctrl Gruppenmitglied 2.",
        requires = "Machtwort: Schild erlernt. Geschwächte Seele verhindert 15 Sek. lang einen zweiten Schild auf demselben Ziel.", mods = { "Schild auf Mouseover, Ziel, Ziel deines Gegners, sonst dich", "Schild auf Gruppenmitglied 1", "Schild auf Gruppenmitglied 2" } },
      ["pvp-shield-then-heal"] = { title = "Schild, Shift für Blitzheilung auf denselben Verbündeten", use = "Leg einen Schild auf dein Mouseover-Ziel, dein freundliches Ziel oder dich selbst. Halte Shift für Blitzheilung auf denselben Verbündeten, solange Geschwächte Seele auf ihm liegt. Erneuerte Hoffnung belohnt das mit mehr kritischer Trefferchance und einer kürzeren Geschwächten Seele.",
        requires = "Talent Erneuerte Hoffnung (Disziplin) für den Bonus; das Makro funktioniert auch ohne. Blitzheilung erlernt (Stufe 20).", mods = { "Schild auf Mouseover, dann Ziel, dann dich selbst", "Blitzheilung auf dein Mouseover-Ziel, dann dein Ziel, dann dich selbst" } },
      ["pvp-silence"] = { title = "Stille auf dein Ziel oder Mouseover", use = "Brich deinen aktuellen Zauber ab und wirke Stille auf dein Ziel. Halte Shift für dein Mouseover-Ziel.",
        requires = "Talent Stille (Schatten, Stufe 30). Es hat 20 Meter Reichweite und 45 Sek. Abklingzeit.", mods = { "Brich deinen Zauber ab, Stille auf dein Ziel", "Brich deinen Zauber ab, Stille auf dein Mouseover-Ziel" } },
      ["pvp-trinket-shield"] = { title = "Schmuckstück und Schild", use = "Brich deinen Zauber ab, nutz dein oberes Schmuckstück und schütz dich mit einem Schild. Halte Shift, um deinen Mouseover-Verbündeten ohne Schmuckstück zu schützen.",
        requires = "Ein benutzbares Schmuckstück im oberen Schmuckstückplatz. Geschwächte Seele verhindert einen zweiten Schild auf demselben Ziel.", mods = { "Zauber stoppen, Schmuckstückplatz 13 nutzen, Schild auf dich", "Zauber stoppen, Schild auf deinen Mouseover-Verbündeten" } },
      ["shadow-death"] = { title = "Schattenwort: Tod aufs Mouseover", use = "Nutze den Finisher von Forever auf ein Mouseover oder dein Ziel. Trifft er und tötet nicht, erleidest du 30 % deiner maximalen Gesundheit als Schaden.",
        requires = "Schattenwort: Tod erlernt", mods = {  } },
      ["shadow-devouring-plague"] = { title = "Verschlingende Seuche aufs Mouseover", use = "Leg Verschlingende Seuche auf dein Mouseover-Ziel oder Ziel. Der verursachte Schaden heilt dich.",
        requires = "Verschlingende Seuche erlernt (Stufe 20). In Forever bekommt jeder Priester den Zauber, seit dem 15. Oktober mit 24 Sek. Abklingzeit. In Classic war es eine Volksfähigkeit der Untoten mit 3 Min. Abklingzeit.", mods = {  } },
      ["shadow-heal-from-shadowform"] = { title = "Schattengestalt verlassen und Blitzheilung", use = "Verlass Schattengestalt und wirke Blitzheilung mit einem Tastendruck auf dein Mouseover-Ziel, dein Ziel oder dich selbst. Wirk Schattengestalt danach neu.",
        requires = "Talent Schattengestalt und Blitzheilung erlernt. In Forever sind Heilzauber in Schattengestalt gesperrt.", mods = {  } },
      ["shadow-mind-blast-flay"] = { title = "Gedankenschlag, Shift für Gedankenschinden", use = "Drück für Gedankenschlag. Halte Shift für Gedankenschinden; läuft die Kanalisierung schon, startet sie nicht neu.",
        requires = "Talent Gedankenschinden (Schatten, Stufe 20)", mods = { "Gedankenschlag wirken", "Wirke Gedankenschinden, sofern du es nicht schon kanalisierst" } },
      ["shadow-mind-flay"] = { title = "Gedankenschinden ohne Neustart", use = "Spamme Gedankenschinden, ohne die Kanalisierung bei jedem Tastendruck neu zu starten.",
        requires = "Talent Gedankenschinden (Schatten, Stufe 20)", mods = {  } },
      ["shadow-pain"] = { title = "Schattenwort: Schmerz aufs Mouseover", use = "Setz deinen DoT auf ein Mouseover, ohne das Ziel zu wechseln.",
        requires = "", mods = {  } },
      ["shadow-pain-wand"] = { title = "Schattenwort: Schmerz, dann Zauberstab", use = "Der erste Tastendruck setzt Schattenwort: Schmerz. Jeder weitere startet den Zauberstab oder hält ihn am Laufen.",
        requires = "Ein Zauberstab im Fernkampfplatz", mods = {  } },
      ["shadow-shadowform"] = { title = "Schattengestalt an, Shift zum Verlassen", use = "Wechsle in Schattengestalt, wenn du nicht schon darin bist. Halte Shift zum Verlassen.",
        requires = "Talent Schattengestalt (Schatten, Stufe 40). Classic-Makros zählen Schattengestalt als Gestalt 1. Im Forever-Client haben wir das noch nicht geprüft.", mods = { "Wechsle in Schattengestalt, wenn du nicht schon darin bist", "Brich Schattengestalt ab" } },
      ["shadow-starshards"] = { title = "Sternensplitter aufs Mouseover", use = "Lass Sternensplitter auf dein Mouseover-Ziel oder Ziel niedergehen.",
        requires = "Nachtelfen-Priester. Sternensplitter ist eine Volksfähigkeit der Nachtelfen. In Forever hat sie 30 Sek. Abklingzeit, in Classic hatte sie keine.", mods = {  } },
      ["shadow-vampiric-embrace"] = { title = "Vampirumarmung aufs Mouseover", use = "Belege dein Mouseover oder Ziel, sodass dein Schattenschaden deine Gruppe heilt.",
        requires = "Talent Vampirumarmung (Schatten), ein 16-Punkte-Talent, das du ab 25 nehmen kannst. Seit dem 15. Oktober hält es 30 Sek. bei 30 Sek. Abklingzeit, du kannst es also dauerhaft aufrechterhalten. In Classic hielt es 1 Min. bei 10 Sek. Abklingzeit.", mods = {  } },
    },
  },
  SHAMAN = {
    guides = {
      ["elemental"] = { name = "Elementar", tagline = "Manasparende Blitzzauber", why = {
        "Blitzschlag und deine Schocks kosten 10% weniger Mana, und sie machen den Großteil deiner Zauber aus.",
        "Blitzschlag hat 2 Sek. Zauberzeit statt 2.5, also hast du ab Stufe 17 den schnelleren Blitz.",
        "Flammenschock, Feuernova und deine Feuertotems verursachen 10% mehr, und Flammenschock hält 6 Sek. länger. Mit diesen Punkten erreichst du auch die 10, die Elementarfokus braucht.",
        "Jeder Schadenszauber hat eine Chance von 10%, deinen nächsten kostenlos zu machen. Seit dem 8. Oktober kann Feuernova den Effekt nicht im selben Zauber auslösen und verbrauchen.",
        "Ein dritter Rang: 15% mehr Feuerschaden, und Flammenschock hält jetzt 21 Sek.",
        "Blitzschlag, Kettenblitzschlag und Erdschock verursachen 3% mehr. Der 15. Punkt schaltet Auge des Sturms frei.",
        "Blitzschlag hat eine Chance von 70%, keine Zauberzeit zu verlieren, wenn du getroffen wirst, also bremst dich ein Mob im Nahkampf nicht aus.",
        "Die letzten zwei Ränge von Erschütterung bringen es auf 5% mehr Schaden für Blitzschlag und Erdschock, und sie sind die 20 Punkte, die die fünfte Reihe braucht.",
        "Dein 21. Punkt: Blitzschlag und Kettenblitzschlag bekommen 5% mehr kritische Trefferchance. Blitzschlagbeherrschung bei 31 Punkten braucht ihn.",
        "Blitzschlag und Kettenblitzschlag haben eine Chance von 30%, kostenlos eine zweite Kopie mit halbem Schaden zu wirken.",
        "Blitzschlag, Kettenblitzschlag und Feuernova reichen 3 Meter weiter, und es ist dein 25. Punkt in Elementar.",
        "Deine kritischen Feuer-, Frost- und Naturtreffer verursachen doppelten Bonusschaden. Mit diesen Punkten kommst du auf 30 in Elementar.",
        "Das 31-Punkte-Talent von Elementar: 15 Sek. lang wird Blitzschlag 0.5 Sek. schneller gewirkt und Kettenblitzschlag hat keine Abklingzeit. Nutze es bei Gruppen.",
        "Der letzte Rang von Elementare Reichweite, 6 Meter mehr für deine Blitze und Feuernova.",
        "5% mehr kritische Trefferchance mit jedem Zauber und Angriff, deren Wert Elementarfuror verdoppelt.",
        "5% mehr Trefferchance mit deinen Zaubern und 5% günstigere Heilungen.",
        "10% mehr Intelligenz für einen größeren Manavorrat.",
        "Die Hälfte deiner Manaregeneration läuft beim Zaubern weiter.",
        "Deine Zauber erzeugen 5% weniger Bedrohung, was hilft, wenn du in einer Gruppe kritisch triffst.",
      } },
      ["enhancement"] = { name = "Verstärkung", tagline = "Waffentreffer und effiziente Schocks", why = {
        "5% mehr Kritchance für Nahkampfschläge und Zauber gleichermaßen. Kritische Nahkampftreffer bereiten später auch Schlaghagel vor.",
        "Deine Angriffskraft steigt um 100% deiner Intelligenz. Schlaghagel braucht alle drei Ränge.",
        "Die Kugeln von Blitzschlagschild verursachen 10% mehr Schaden, und mit diesen Punkten erreichst du die 10, die die dritte Reihe braucht.",
        "Deine Schocks und Blitzschlagschild kosten 45% weniger Mana, so kannst du zwischen den Schlägen jeden Schock nutzen, sobald er bereit ist.",
        "Flammenzunge und Frostbrand treffen 15% härter, und Felsbeißer gibt 20% mehr Angriffskraft. Der Bonus von Waffe des Windzorns wächst um 40%, wenn du es mit 30 lernst.",
        "Der letzte Rang von Verbesserter Blitzschlagschild, 15% mehr Kugelschaden, und der 15. Punkt, den Sturmschlag braucht.",
        "Ein Schlag mit 100% Waffenschaden alle 8 Sek. für 8% deines Grundmanas. Lass Erdschock folgen, mit 20% mehr Schaden innerhalb von 12 Sek.",
        "Ein kritischer Nahkampftreffer beschleunigt deine nächsten 3 Schläge um 24%. Die 5% Krit von Donnernde Stöße lassen das öfter passieren.",
        "Sturmschlag hat eine Chance von 50%, 15 Sek. lang die Hälfte deiner Manaregeneration weiterlaufen zu lassen, und Ausweichen oder Parieren kann die Abklingzeit zurücksetzen.",
        "Der letzte Rang von Schlaghagel: Nach einem kritischen Nahkampftreffer sind deine nächsten 3 Schläge 30% schneller.",
        "Der letzte Rang von Verbesserter Sturmschlag: Sturmschlag lässt dein Mana beim Zaubern weiter regenerieren, und Ausweichen und Parieren können es zurücksetzen.",
        "Zauberschaden und Heilung in Höhe von 30% deiner Intelligenz, damit deine Schocks und Heilungen mithalten.",
