        requires = "", mods = { "Blitzschlag auf dein Ziel", "Blitzschlag auf dein Mouseover-Ziel", "Kettenblitzschlag auf dein Ziel", "Kettenblitzschlag auf dein Mouseover-Ziel" } },
      ["pvp-projection-fire-nova"] = { title = "Totems zu dir holen, dann Feuernova", use = "Shift wirkt Totemischer Ruf, der deine Totems dorthin holt, wo du stehst. Ein normaler Tastendruck löst Feuernova an deinem Feuertotem aus, so kannst du Totem der glühenden Magma in eine Gruppe tragen und zünden.",
        requires = "Ein Feuertotem muss für Feuernova stehen. Totemischer Ruf hat 30 Sek. Abklingzeit.", mods = { "Feuernova um dein Feuertotem herum", "Totemischer Ruf: Deine Totems kommen zu dir" } },
      ["pvp-riptide-chain-heal"] = { title = "Springflut oder Kettenheilung auf denselben Verbündeten", use = "Springflut auf dein Mouseover-Ziel, dein Ziel oder dich, und Shift wirkt Kettenheilung auf denselben Verbündeten. Auf einem Ziel mit Springflut wirkt das 25% stärker.",
        requires = "Talent Springflut und Kettenheilung erlernt", mods = { "Springflut auf Mouseover-Ziel, Ziel oder dich selbst", "Kettenheilung auf Mouseover-Ziel oder Ziel" } },
      ["pvp-riptide-now"] = { title = "Sofortige Springflut, die Wolf und Zauber beendet", use = "Verlässt Geisterwolf, bricht die laufende Heilung ab und wirkt Springflut auf dein Mouseover-Ziel, dein freundliches Ziel oder dich. Shift und Ctrl schicken den Zauber an dein erstes und zweites Gruppenmitglied.",
        requires = "Talent Springflut. Es heilt jetzt nur noch über Zeit, bei 12 Sek. Abklingzeit, und ein Tastendruck bricht deinen Zauber auch dann ab, wenn es Abklingzeit hat.", mods = { "Springflut auf Mouseover-Ziel, freundliches Ziel oder dich", "Springflut auf Gruppenmitglied 1", "Springflut auf Gruppenmitglied 2" } },
      ["pvp-slow-frost-shock"] = { title = "Flüchtende mit Frostschock verlangsamen", use = "Frostschock verlangsamt dein Ziel um 50%; Shift verlangsamt dein Mouseover-Ziel, und Ctrl wirkt den günstigen Rang 1 auf dein Ziel.",
        requires = "", mods = { "Frostschock auf dein Ziel", "Frostschock auf dein Mouseover-Ziel", "Frostschock Rang 1 auf dein Ziel" } },
      ["pvp-stick-earthbind"] = { title = "Erdbindung oder Frostschock und weiterschlagen", use = "Stellt Totem der Erdbindung zu deinen Füßen auf, damit ein kitendes Ziel nicht aus der Nahkampfreichweite läuft, oder Shift wirkt Frostschock auf dein Ziel. Beides startet deine Schläge, und Griff der Erde vergrößert die Reichweite des Totems.",
        requires = "", mods = { "Totem der Erdbindung und fang an zuzuschlagen", "Frostschock auf dein Ziel und fang an zuzuschlagen" } },
      ["pvp-stormstrike-cooldowns"] = { title = "Sturmschlag, mit Ctrl samt deinen Abklingzeiten", use = "Ein normaler Tastendruck startet deine Schläge und wirkt Sturmschlag. Halte Ctrl, wenn du auf den Kill gehst, um im selben Tastendruck Zorn des Scharfsehers und beide Schmuckstücke dazuzunehmen.",
        requires = "Talente Sturmschlag und Zorn des Scharfsehers", mods = { "Fang an zuzuschlagen und Sturmschlag", "Zorn des Scharfsehers und beide Schmuckstücke, dann Sturmschlag" } },
      ["pvp-stormstrike-mouseover"] = { title = "Sturmschlag und Erdschock auf dein Mouseover", use = "Sturmschlag auf den Gegner unter deinem Mauszeiger, etwa einen Heiler neben deinem Ziel, und Shift setzt Erdschock auf denselben Gegner nach, solange der Bonus von 20% aktiv ist. Ohne Mouseover-Ziel treffen beide dein Ziel.",
        requires = "Talent Sturmschlag. Du musst in Nahkampfreichweite des Gegners sein, auf den du zeigst.", mods = { "Sturmschlag auf dein Mouseover-Ziel oder Ziel", "Erdschock auf denselben Gegner" } },
      ["pvp-swap-imbue"] = { title = "Waffenverzauberung für die Waffe in deiner Hand", use = "Waffe des Windzorns auf deine Zweihandwaffe oder Waffe des Frostbrands, wenn du einen Schild trägst, damit dir die Verlangsamungs-Procs beim Peelen helfen, während du dich verteidigst.",
        requires = "Waffe des Windzorns auf Stufe 30 erlernt. Fragt die Waffenverzauberung nach einer Waffe, klick deine Waffenhand an. Elementarwaffen lässt beide Verzauberungen härter treffen.", mods = {  } },
      ["pvp-swift-heal-party"] = { title = "Welle der Heilung mit Schnelligkeit der Natur auf ein Gruppenmitglied", use = "Bricht deinen Zauber ab, dann macht Schnelligkeit der Natur den Zauber Welle der Heilung sofort wirksam, auf dein Mouseover-Ziel, dein freundliches Ziel oder dich. Shift und Ctrl schicken ihn an Gruppenmitglied 1 und 2, Alt an dich selbst.",
        requires = "Talent Schnelligkeit der Natur. Läuft die Abklingzeit, beginnst du Welle der Heilung ganz normal, und erneutes Drücken startet den Zauber neu.", mods = { "Welle der Heilung sofort auf Mouseover-Ziel, freundliches Ziel oder dich", "Welle der Heilung sofort auf Gruppenmitglied 1", "Welle der Heilung sofort auf Gruppenmitglied 2", "Welle der Heilung sofort auf dich selbst" } },
      ["pvp-swift-nuke"] = { title = "Schnelligkeit der Natur für einen sofortigen Schadenszauber", use = "Schnelligkeit der Natur macht den nächsten Zauber sofort: Blitzschlag auf deinen Gegner, mit Shift Kettenblitzschlag oder mit Alt Welle der Heilung auf dich.",
        requires = "Talent Schnelligkeit der Natur. Läuft die Abklingzeit, wird der Zauber normal gewirkt.", mods = { "Blitzschlag sofort auf dein feindliches Ziel", "Kettenblitzschlag ohne Zauberzeit", "Welle der Heilung sofort auf dich selbst" } },
      ["pvp-totem-control"] = { title = "Grounding, Erdstoß, Erdbindung und Steinklaue auf einer Taste", use = "Totem der Erdung lenkt einen schädlichen Zauber um, der auf ein Gruppenmitglied in der Nähe zielt; Shift, Ctrl und Alt stellen stattdessen Erdstoß, Erdbindung und Steinklaue auf.",
        requires = "", mods = { "Totem der Erdung", "Totem des Erdstoßes", "Totem der Erdbindung", "Totem der Steinklaue" } },
      ["pvp-trinket-racial"] = { title = "Schmuckstücke und Volksfähigkeit zur Verteidigung auf einer Taste", use = "Nutzt deine Volksfähigkeit zur Flucht und beide Schmuckstücke zusammen, wenn du betäubt oder in Not bist.",
        requires = "Tauren (Kriegsdonner), Zwerg (Steingestalt) oder Orc (Fluch brechen). Die Zeilen für andere Völker schlagen einfach fehl.", mods = {  } },
      ["pvp-weapon-swap"] = { title = "Zweihänder oder Einhänder und Schild", use = "Legt deinen Zweihänder für Sturmschlag und Windzorn an, oder mit Shift deinen Einhänder und Schild, wenn Nahkämpfer oder Jäger dich fokussieren. Setz deine eigenen Gegenstandsnamen für die drei Platzhalter ein.",
        requires = "Ein Zweihänder, ein Einhänder und ein Schild in den Taschen. Verzauberungen bleiben auf der Waffe, auf die du sie wirkst, also verzaubere beide vor dem Kampf.", mods = { "Zweihänder anlegen", "Einhänder und Schild anlegen" } },
      ["pvp-wolf-shock"] = { title = "Geisterwolf an und aus oder mit Schock raus", use = "Drück, um Geisterwolf ein- oder auszuschalten; halte Shift, um mit einem Tastendruck den Wolf zu verlassen und Frostschock auf dein Ziel zu wirken.",
        requires = "Geisterwolf geht nur im Freien, bis du das Talent Verbesserter Geisterwolf nimmst", mods = { "Geisterwolf an, oder aus, wenn du schon ein Wolf bist", "Verlass den Wolf und wirke Frostschock auf dein Ziel" } },
      ["pvp-wolf-stormstrike"] = { title = "Rein mit Geisterwolf, raus mit Sturmschlag", use = "Shift verwandelt dich in Geisterwolf, um die Distanz zu schließen. Ein normaler Tastendruck verlässt den Wolf, startet deine Schläge und wirkt Sturmschlag in einem Rutsch.",
        requires = "Talent Sturmschlag. Verbesserter Geisterwolf verkürzt die Zauberzeit des Wolfs um bis zu 3 Sek., und du kannst ihn auch drinnen nutzen.", mods = { "Verlass Geisterwolf, fang an zuzuschlagen und Sturmschlag", "Geisterwolf" } },
      ["restoration-ancestral-spirit"] = { title = "Mouseover oder Ziel wiederbeleben", use = "Belebt den toten Spieler unter deinem Cursor oder dein totes Ziel wieder, sobald du nicht mehr im Kampf bist.",
        requires = "", mods = {  } },
      ["restoration-chain-heal"] = { title = "Mouseover-Kettenheilung", use = "Kettenheilung auf dein Mouseover-Ziel, dein Ziel oder dich selbst. In einer Gruppe springt der Zauber nur auf andere Gruppenmitglieder.",
        requires = "", mods = {  } },
      ["restoration-heal-or-bolt"] = { title = "Welle der Heilung auf Verbündete, Blitzschlag auf Gegner", use = "Heilt ein freundliches Ziel, wirft Blitzschlag auf einen Gegner, heilt dich, wenn nichts ausgewählt ist, und Alt heilt dich, egal was du im Ziel hast.",
        requires = "", mods = { "Welle der Heilung auf einen Verbündeten, Blitzschlag auf einen Gegner", "Welle der Heilung auf dich selbst" } },
      ["restoration-healing-wave"] = { title = "Welle der Heilung auf Mouseover", use = "Heile ein freundliches Mouseover, dein Ziel oder dich.",
        requires = "", mods = {  } },
      ["restoration-healing-wave-downrank"] = { title = "Mit niedrigerem Rang von Welle der Heilung nachheilen", use = "Drück für deinen höchsten Rang von Welle der Heilung oder halte Shift für den günstigeren Rang 4, wenn ein bisschen Nachheilen reicht.",
        requires = "", mods = { "Welle der Heilung im höchsten Rang auf Mouseover-Ziel, Ziel oder dich selbst", "Welle der Heilung Rang 4 auf dieselben Ziele" } },
      ["restoration-lesser-healing-wave"] = { title = "Geringe Welle der Heilung auf Mouseover, Ziel oder Ziel des Ziels", use = "Die schnelle Heilung für den Verbündeten unter deinem Cursor, dein freundliches Ziel, wen auch immer dein feindliches Ziel angreift, oder dich.",
        requires = "", mods = {  } },
      ["restoration-nature-swiftness-heal"] = { title = "Schnelligkeit der Natur für eine Sofortheilung", use = "Schnelligkeit der Natur macht deine nächste Heilung sofort wirksam, also wirkt das Makro Welle der Heilung oder mit Shift Kettenheilung auf dein Mouseover-Ziel, dein Ziel oder dich.",
        requires = "Talent Schnelligkeit der Natur. Läuft die Abklingzeit, beginnst du einen normalen Zauber.", mods = { "Welle der Heilung ohne Zauberzeit", "Kettenheilung ohne Zauberzeit" } },
      ["restoration-riptide"] = { title = "Mouseover-Springflut", use = "Nutze das neue Wiederherstellungstalent aus Forever auf dem Gruppenfenster unter deinem Cursor.",
        requires = "Talent Springflut. Seit dem 2. November heilt es nur noch über Zeit, bei 12 Sek. Abklingzeit.", mods = {  } },
      ["restoration-riptide-chain-heal"] = { title = "Springflut, dann Kettenheilung auf denselben Verbündeten", use = "Springflut beim ersten Tastendruck und Kettenheilung beim nächsten. Auf einem Ziel mit Springflut wirkt das 25% stärker, also lass den Mauszeiger auf demselben Verbündeten.",
        requires = "Talent Springflut", mods = {  } },
      ["restoration-utility-totems"] = { title = "Poison Cleansing, Disease Cleansing oder Totem des Erdstoßes", use = "Totem der Giftreinigung oder Shift für Totem der Krankheitsreinigung und Ctrl für Totem des Erdstoßes, das Furcht, Bezauberung und Schlaf entfernt.",
        requires = "", mods = { "Totem der Giftreinigung", "Totem der Krankheitsreinigung", "Totem des Erdstoßes" } },
      ["restoration-water-totems"] = { title = "Heilstrom, Manaquelle oder Totem der Manaflut", use = "Totem des heilenden Flusses heilt die Gruppe, Shift stellt Totem der Manaquelle auf und Ctrl Totem der Manaflut, wenn das Mana knapp wird.",
        requires = "Talent Totem der Manaflut für Ctrl und das zugehörige Wassertotem. Es ist ein 16-Punkte-Talent, du kannst es also ab 25 nehmen (Blizzard, 7. Oktober).", mods = { "Totem des heilenden Flusses", "Totem der Manaquelle", "Totem der Manaflut" } },
    },
