  MAGE = {
    guides = {
      ["arcane"] = { name = "Arkan", tagline = "Kurze Blast-Fenster", why = {
        "Wenn du getroffen wirst, bleibt die Kanalisierung von Arkane Geschosse immer erhalten, und Arkanschlag und Arkaner Zorn behalten ihre Zauberzeit in 70% der Fälle. Fünf Punkte öffnen außerdem die zweite Reihe auf Stufe 15.",
        "Frostblitz und Feuerball haben eine Chance von 20%, dass dein nächster Einsatz von Arkane Geschosse kostenlos und doppelt so schnell ist, und Arkanschlag hat ab 20 eine Chance von 40%. Das Talent ist in die zweite Reihe gerutscht, also kommt es auf Stufe 15.",
        "Jeder Schadenszauber, der trifft, hat eine Chance von 6%, deinen nächsten kostenlos zu machen. Feuerball und Frostblitz zählen auch, und diese Punkte öffnen die dritte Reihe auf Stufe 20.",
        "1.5 Sek. Zauberzeit. Jeder Arkanschlag gibt dir 18 Sek. lang 12% deiner Intelligenz als Zauberschaden, bis zu 4 Stapel, und macht den nächsten 100% teurer. Wirk einen oder zwei, dann nutz das Fenster für andere Zauber.",
        "Zwei weitere Ränge für eine Chance von 10% auf einen kostenlosen Zauber. Alle fünf brauchst du später für Arkane Meditation.",
        "Deine Arkanzauber bekommen 4% mehr Kritchance. Außerdem ist es der 15. Punkt, der Arkaner Zorn auf Stufe 25 freischaltet.",
        "Ein Zauber mit 3.5 Sek. Zauberzeit und 6 Sek. Abklingzeit, der zusätzlichen Zauberschaden in Höhe von 5% deines maximalen Manas bekommt, zusätzlich zu deinen Arkanschlag-Stapeln. Außerdem hat er eine Chance von 20%, Geschosssalve aufleuchten zu lassen.",
        "Beim Zaubern regenerierst du Mana mit halber Rate, das hilft bei den steigenden Kosten von Arkanschlag.",
        "Ein dritter Rang für 6% Krit auf deine Arkanzauber, und der 20. Punkt, der Geistesgegenwart freischaltet.",
        "Dein nächster Zauber ist sofort, einmal alle 3 Min. Nutz das für Verwandlung auf ein Add oder Arkaner Zorn, während du in Bewegung bist.",
        "10% mehr Intelligenz, und deine kritischen Arkantreffer verursachen doppelten Bonusschaden. Das ist der größte Schadensgewinn, der im Baum noch übrig ist.",
        "3% mehr Schaden und 3% mehr kritische Trefferchance bei jedem Zauber.",
        "Deine Ziele widerstehen deinen Zaubern seltener, und deine Arkanzauber erzeugen weniger Bedrohung. Mit diesem Punkt kommst du auf 30 in Arkan.",
        "Das 31-Punkte-Talent von Arkan: 15 Sek. lang 30% mehr Zauberschaden, alle 3 Min., für 30% mehr Mana. Kombinier es bei einem großen Pull mit Geistesgegenwart.",
        "Der letzte Rang von Arkanes Feingefühl: 15 weniger Widerstand bei deinen Zielen und 30% weniger Bedrohung durch Arkanzauber.",
        "Seit dem 2. November 6% mehr Trefferchance mit jedem Zauber, also verfehlen weniger Zauber Mobs über deiner Stufe.",
        "Seit dem 2. November 10% mehr kritische Trefferchance für Arkanschlag, Feuerschlag und Versengen.",
        "Arkaner Zorn, Feuerball und Frostfeuerblitz werden 0.5 Sek. schneller gewirkt.",
        "10 mehr von jedem Widerstand, und ein Zauber, dem vollständig widerstanden wurde, gibt dir 2% deines Manas zurück.",
        "Arkanzauber reichen 6 Meter weiter.",
        "Manaschild zieht pro Treffer ein Drittel weniger Mana ab, und Magische Rüstung gibt mehr Widerstand.",
      } },
      ["fire"] = { name = "Feuer", tagline = "Feuerball mit kontrolliertem Burst", why = {
        "Beschleuniger, früher Verb. Feuerball, senkt die Zauberzeit von Feuerball von 3.5 auf 3 Sek. Bis Stufe 30 ist das dein Hauptzauber.",
        "Feuerkrits lassen das Ziel 4 Sek. lang für weitere 40% des Treffers brennen. Jeder Magier hat Entzünden für sich allein; zwei Feuermagier teilen sich den Effekt nicht.",
        "6 Sek. Zauberzeit, trifft hart und brennt 12 Sek. nach. Eröffne damit aus maximaler Reichweite; sobald ein Mob an dir dran ist, ist er zu langsam.",
        "Feuerschlag ist alle 6 Sek. statt alle 8 wieder bereit und reicht 35 Meter weit, also auch von dort, wo du Feuerball wirkst. Ab Stufe 25 ist jeder Einsatz von Feuerschlag ein Stapel Aufwärmen.",
        "Wenn du getroffen wirst, behalten Feuerzauber in 47% der Fälle ihre Zauberzeit, und Feuerzauber erzeugen 20% weniger Bedrohung. Außerdem ist es der 15. Punkt, für Aufwärmen auf Stufe 25.",
        "Krits von Feuerball oder Versengen verkürzen die Zauberzeit deines nächsten Pyroschlag um 25%, bis zu 3 Stapel für 20 Sek. Seit dem 15. Oktober gibt auch jeder Einsatz von Feuerschlag einen Stapel, und ein kritischer Treffer mit Feuerschlag gibt zwei.",
        "Jeder Einsatz von Versengen erhöht 30 Sek. lang den Feuerschaden, den das Ziel von dir nimmt, um 3%, bis zu 5-mal stapelbar. Das lohnt sich bei Elitegegnern und Bossen, weniger bei Mobs, die nach drei Zaubern tot sind.",
        "Der dritte Rang: 70% deiner Feuerzauber ignorieren Zauberverzögerung, und deine Feuerbedrohung sinkt um 30%. Mit dem Punkt kommst du außerdem auf 20 Punkte für Druckwelle.",
        "Ein sofortiger Feuerring um dich herum, der alles Getroffene 6 Sek. lang um 50% verlangsamt. Nutz ihn, wenn dir ein Pull auf die Pelle rückt, dann geh zurück und zauber weiter.",
        "6% mehr Krit für Feuerzauber, was Entzünden und Aufwärmen füttert.",
        "2% mehr kritische Trefferchance für Feuerschlag und Versengen, und dein 25. Punkt in Feuer für Feuermacht.",
        "Deine Feuerzauber verursachen 3% mehr für jeden deiner Feuereffekte auf dem Ziel, bis zu 12%. Entzünden, Verbessertes Versengen und Pyroschlag zählen alle.",
        "Mehr kritische Trefferchance für Feuerschlag und Versengen. Mit diesen zwei Punkten kommst du auf 30 in Feuer.",
        "Das 31-Punkte-Talent von Feuer: Jeder Feuertreffer gibt 10% Krit, bis du 3 kritische Feuertreffer gelandet hast, alle 3 Min. Nutz es zu Beginn eines Bosses oder eines großen Pulls.",
        "Die letzten zwei Ränge von Verbrennung, 10% mehr Krit für Feuerschlag und Versengen.",
        "Feuerzauber reichen 6 Meter weiter, also trifft Feuerball, bevor der Mob bei dir ist.",
        "Kritische Feuer- und Frosttreffer geben 30% ihrer Grundmanakosten zurück, und du landest jetzt oft kritische Treffer.",
        "Seit dem 2. November 6% mehr Trefferchance mit jedem Zauber.",
        "Frostrüstung und Eisrüstung geben 30% mehr, und Eisbarriere und Frostzauberschutz absorbieren mehr.",
        "Deine Kälteeffekte, auch der von Kältekegel, können das Ziel 5 Sek. lang einfrieren.",
        "Frostnova ist 4 Sek. früher wieder bereit, also kannst du bei den meisten Pulls eine Nova wirken und zurückweichen.",
        "Deine Kälteeffekte halten ein Drittel länger an und verlangsamen um zusätzliche 10%.",
      } },
      ["frost"] = { name = "Frost", tagline = "Einzelne Ziele kiten", why = {
        "Frostblitz hat 2.5 Sek. Zauberzeit statt 3, also bekommst du mehr Blitze raus, bevor ein verlangsamter Mob dich erreicht. Bis Stufe 30 ist das dein Hauptzauber.",
        "Die Verlangsamung von Frostblitz hält ein Drittel länger an und verlangsamt um zusätzliche 10%, insgesamt 50%.",
        "Frostnova ist alle 21 Sek. statt alle 25 wieder bereit, also bei mehr deiner Pulls verfügbar.",
        "Ein sofortiger Frosttreffer, der einem eingefrorenen Ziel vierfachen Schaden zufügt, bei 8 Sek. Abklingzeit. Frostnova, dann Eislanze.",
        "Deine Kälteeffekte, auch die von Frostblitz, haben eine Chance von 15%, das Ziel 5 Sek. lang einzufrieren. Das bereitet Eislanze und später Zertrümmern vor, ohne Frostnova zu verbrauchen. Früher kam hier Stechendes Eis hin, aber der Launch-Client hat es entfernt.",
        "Frostzauber kosten 5% weniger Mana und erzeugen 10% weniger Bedrohung. Zertrümmern und Eisblock brauchen beide die 15 Punkte, die du damit vollmachst.",
        "10 Sek. Immunität bei 5 Min. Abklingzeit. Darin kannst du nicht zaubern, also nutz die Immunität, um einen schlechten Moment zu überleben, bis Frostnova wieder bereit ist.",
        "50% mehr Kritchance gegen eingefrorene Ziele, also trifft Frostblitz oder Eislanze nach Frostnova öfter kritisch als nicht.",
        "Frostblitz und Eislanze reichen 10% weiter und Frostnova deckt 10% mehr Fläche ab. Kälteeinbruch wird frei, sobald dieser 20. Punkt gesetzt ist.",
        "Setzt deine anderen Frost-Abklingzeiten zurück, also kannst du Frostnova oder Eisblock ein zweites Mal nutzen. Die Abklingzeit beträgt 10 Min., also heb dir das für den Pull auf, der schiefgeht.",
        "Deine kritischen Frosttreffer verursachen den doppelten Bonusschaden. Mit Zertrümmern trifft Eislanze auf einem eingefrorenen Ziel sehr hart.",
        "Der letzte Rang von Arktische Reichweite: Frostblitz und Eislanze reichen 20% weiter, und Frostnova deckt 20% mehr Fläche ab.",
        "Deine Kälteeffekte können dafür sorgen, dass deine nächsten 2 Zauber wirken, als wäre das Ziel eingefroren, also funktionieren Eislanze und Zertrümmern ohne Frostnova.",
        "Frostblitz stapelt Winterkälte, wodurch dein nächster Einsatz von Kältekegel härter trifft. Mit diesem Punkt kommst du auf 30 in Frost.",
        "Das 31-Punkte-Talent von Frost: alle 30 Sek. ein Schild, der außerdem 1 Min. lang deinen Frostschaden um 15% erhöht. Halt ihn zwischen den Pulls aufrecht.",
        "Die letzten vier Ränge von Winterkälte, bis zu fünf Stapel mit je 20% mehr Schaden für deinen nächsten Einsatz von Kältekegel.",
        "Die letzten zwei Ränge von Frost-Kanalisierung: Frostzauber kosten 15% weniger Mana und erzeugen 30% weniger Bedrohung.",
        "Eisbarriere und Frostzauberschutz absorbieren seit dem 2. November mehr, und deine Frost- und Eisrüstung geben 30% mehr.",
        "Seit dem 2. November 6% mehr Trefferchance mit jedem Zauber.",
        "Kältekegel verursacht 35% mehr Schaden, zusätzlich zu dem, was Winterkälte bringt.",
        "Seit dem 2. November 10% mehr Krit für Eislanze und Feuerschlag.",
        "Feuerschlag reicht 3 Meter weiter, für den letzten Treffer auf einen Flüchtenden.",
      } },
    },
    macros = {
      ["arcane-arcane-blast"] = { title = "Arkanschlag, mit Geschossen und Frostblitz auf Modifikatoren", use = "Arkanschlag auf der Taste, Shift für Arkane Geschosse und Ctrl für eine günstigere Version von Frostblitz, wenn der Stapel teuer wird. Während du Geschosse kanalisierst, wird nichts ausgelöst.",
        requires = "Talent Arkanschlag", mods = { "Arkanschlag wirken", "Arkane Geschosse wirken, solange deine Arkanschlag-Stapel aktiv sind", "Wirke Frostblitz als günstigeren Füller" } },
      ["arcane-arcane-blast-stack"] = { title = "Dreimal Arkanschlag, dann Geschosse", use = "Jeder Druck geht in der Abfolge weiter: drei Arkanschläge, dann Arkane Geschosse, solange die Stapel halten (18 Sekunden ab dem ersten Arkanschlag). Nach 10 Sekunden oder bei einem neuen Ziel beginnt sie von vorn.",
        requires = "Talent Arkanschlag und Arkane Geschosse. Hör früher auf, wenn das Mana knapp wird, denn jeder Stapel erhöht die Kosten von Arkanschlag um 100%.", mods = {  } },
      ["arcane-arcane-burst"] = { title = "Schmuckstücke und Arkane Macht, dann Arkanschlag", use = "Zündet beide Schmuckstücke und Arkane Macht, dann startet es Arkanschlag. Durch Arkane Macht kosten deine Zauber 15 Sek. lang 30% mehr Mana.",
        requires = "Talente Arkane Macht und Arkanschlag", mods = {  } },
      ["arcane-arcane-explosion-rank"] = { title = "Arkane Explosion, Rang 1 außerhalb des Kampfes", use = "Höchster Rang im Kampf und Rang 1 davor, damit der erste Pull weniger Mana kostet.",
        requires = "Arkane Explosion erlernt", mods = {  } },
      ["arcane-arcane-missiles"] = { title = "Kanalisierung von Arkane Geschosse schützen", use = "Wiederholtes Drücken startet eine laufende Kanalisierung nicht neu.",
        requires = "Arkane Geschosse erlernt", mods = {  } },
      ["arcane-conjure-mana-gems"] = { title = "Jeden Manaedelstein auf einer Taste herbeizaubern", use = "Zaubert standardmäßig einen Manarubin herbei. Shift macht einen Citrin, Ctrl eine Jade und Alt einen Achat.",
        requires = "Jeder Edelsteinzauber erlernt: Achat ab 28, Jade ab 38, Citrin ab 48 und Rubin ab 58", mods = { "Manarubin herbeizaubern", "Manacitrin herbeizaubern", "Manajadestein herbeizaubern", "Manaachat herbeizaubern" } },
      ["arcane-evocation-channel"] = { title = "Hervorrufung, Shift zum Abbrechen", use = "Starte Hervorrufung, ohne es bei wiederholtem Drücken abzubrechen. Halte Shift, um den Kanalzauber zu stoppen, wenn du laufen oder etwas anderes wirken musst.",
        requires = "Hervorrufung erlernt", mods = { "Hervorrufung starten, ohne einen laufenden Kanalzauber neu zu beginnen", "Zaubern abbrechen" } },
      ["arcane-mana-gem-blast"] = { title = "Arkanschlag, mit Manaedelstein auf Shift", use = "Arkanschlag auf der Taste. Halte Shift, um zuerst einen Manastein zu nutzen; der Stein wirkt sofort, also startet der Zauber trotzdem mit demselben Druck.",
        requires = "Talent Arkanschlag und ein herbeigezauberter Manaedelstein. Die Gegenstandsnamen sind die aus Classic.", mods = { "Arkanschlag wirken", "Manastein nutzen, dann Arkanschlag wirken" } },
      ["arcane-target-and-blast"] = { title = "Nächsten Gegner greifen und Arkanschlag", use = "Entfernt ein totes oder freundliches Ziel, wählt den nächsten Gegner, wenn du keins hast, und eröffnet dann mit Arkanschlag.",
        requires = "Talent Arkanschlag", mods = {  } },
      ["arcane-wand"] = { title = "Zauberstab, der sich nicht abschaltet", use = "Startet deinen Zauberstab und lässt ihn weiterlaufen, wenn du die Taste erneut drückst.",
        requires = "Ein angelegter Zauberstab", mods = {  } },
      ["class-wide-arcane-intellect"] = { title = "Arkane Intelligenz auf einen Verbündeten oder dich selbst", use = "Bufft die freundliche Einheit unter deinem Mauszeiger, sonst dein freundliches Ziel, sonst dich. Halte Alt, um in jedem Fall dich selbst zu buffen.",
        requires = "Arkane Intelligenz erlernt", mods = { "Mouseover, freundliches Ziel oder dich selbst buffen", "Dich selbst buffen" } },
      ["class-wide-armors"] = { title = "Eisrüstung, Magische Rüstung oder Frostrüstung", use = "Standardmäßig Eisrüstung, Shift für Magische Rüstung und Ctrl für Frostrüstung. Es kann immer nur eine Rüstung aktiv sein.",
        requires = "Eisrüstung (30) und Magische Rüstung (34). Frostrüstung deckt die Stufen davor ab.", mods = { "Eisrüstung wirken", "Magische Rüstung wirken", "Frostrüstung wirken" } },
      ["class-wide-conjure-water-food"] = { title = "Wasser herbeizaubern, mit Shift Essen", use = "Eine Taste zaubert Wasser im höchsten Rang herbei. Halte Shift für Essen.",
        requires = "Wasser herbeizaubern und Essen herbeizaubern erlernt", mods = { "Wasser herbeizaubern", "Essen herbeizaubern" } },
      ["class-wide-counterspell"] = { title = "Gegenzauber, ohne auf deinen Zauber zu warten", use = "Bricht ab, was du gerade wirkst, und wirkt sofort Gegenzauber auf dein Ziel.",
        requires = "Gegenzauber erlernt (24). Das Makro bricht deinen Zauber auch dann ab, wenn Gegenzauber noch abklingt.", mods = {  } },
      ["class-wide-dampen-amplify"] = { title = "Magie dämpfen oder verstärken auf einen Verbündeten", use = "Magie dämpfen auf den Verbündeten unter deinem Cursor, dein freundliches Ziel oder dich selbst. Shift wechselt zu Magie verstärken.",
        requires = "Magie dämpfen (12) und Magie verstärken (18) erlernt", mods = { "Magie dämpfen auf dein Mouseover-Ziel, dein freundliches Ziel oder dich selbst", "Magie verstärken auf dieselben Einheiten" } },
      ["class-wide-mana-gems"] = { title = "Den Manaedelstein nutzen, den du hast", use = "Versucht Manarubin, Citrin, Jade und Achat in dieser Reihenfolge. Drück es, wenn du Mana brauchst.",
        requires = "Ein herbeigezauberter Manaedelstein in deinen Taschen. Die Gegenstandsnamen sind die aus Classic.", mods = {  } },
      ["class-wide-party-intellect"] = { title = "Intelligenz, Shift für Arkane Brillanz", use = "Gib einem Verbündeten Arkane Intelligenz oder halte Shift für Arkane Brillanz. Beides geht an dein freundliches Mouseover-Ziel, dein Ziel oder dich selbst.",
        requires = "Arkane Brillanz erlernt; Arkanes Pulver für den Gruppenbuff", mods = { "Arkane Intelligenz", "Arkane Brillanz" } },
      ["class-wide-polymorph"] = { title = "Verwandlung aufs Mouseover oder dein Ziel", use = "Verwandelt den Gegner unter deinem Mauszeiger und lässt dein Ziel in Ruhe. Ist kein Gegner unter dem Mauszeiger, verwandelt es dein Ziel.",
        requires = "Verwandlung erlernt", mods = {  } },
      ["class-wide-portals-alliance"] = { title = "Allianz-Portale auf einer Taste", use = "Öffnet ein Portal nach Stormwind. Mit Shift wird es Ironforge, mit Ctrl Darnassus.",
        requires = "Die Portalzauber, die du willst (40 und 50 für Darnassus)", mods = { "Portal: Stormwind", "Portal: Ironforge", "Portal: Darnassus" } },
      ["class-wide-portals-horde"] = { title = "Horde-Portale auf einer Taste", use = "Öffnet ein Portal nach Orgrimmar. Mit Shift wird es Undercity, mit Ctrl Thunder Bluff.",
        requires = "Die Portalzauber, die du willst (40 und 50 für Thunder Bluff)", mods = { "Portal: Orgrimmar", "Portal: Undercity", "Portal: Thunder Bluff" } },
      ["class-wide-remove-lesser-curse"] = { title = "Geringen Fluch aufheben auf einen Verbündeten oder dich selbst", use = "Entfernt einen Fluch von deinem Mouseover, freundlichen Ziel oder dir. Mit Shift befreist du sofort dich selbst.",
        requires = "Geringen Fluch aufheben erlernt (18). Die Forever-Version entfernt auch ein Omen.", mods = { "Mouseover, freundliches Ziel oder dich selbst entfluchen", "Dich selbst entfluchen" } },
      ["class-wide-slow-fall"] = { title = "Langsamer Fall, Shift zum Abbrechen", use = "Steig ab und wirk Langsamer Fall auf dich selbst. Halte Shift, um den Effekt zu entfernen, wenn du wieder am Boden bist.",
        requires = "Langsamer Fall erlernt; eine Leichte Feder", mods = { "Absteigen und Langsamer Fall wirken", "Langsamer Fall abbrechen" } },
      ["class-wide-teleports-alliance"] = { title = "Allianz-Teleports auf einer Taste", use = "Teleportiert dich nach Stormwind. Shift bringt dich nach Ironforge, Ctrl nach Darnassus und Alt nach Dalaran.",
        requires = "Die Teleportzauber, die du willst (20 und 30). Teleportieren: Dalaran ist neu in Forever und kommt ab 50.", mods = { "Teleportieren: Stormwind", "Teleportieren: Ironforge", "Teleportieren: Darnassus", "Teleportieren: Dalaran" } },
      ["class-wide-teleports-horde"] = { title = "Horde-Teleports auf einer Taste", use = "Teleportiert dich nach Orgrimmar. Shift bringt dich nach Undercity, Ctrl nach Thunder Bluff und Alt nach Dalaran.",
        requires = "Die Teleportzauber, die du willst (20 und 30). Teleportieren: Dalaran ist neu in Forever und kommt ab 50.", mods = { "Teleportieren: Orgrimmar", "Teleportieren: Undercity", "Teleportieren: Thunder Bluff", "Teleportieren: Dalaran" } },
      ["fire-blast-wave"] = { title = "Sofortige Druckwelle", use = "Bricht deinen aktuellen Zauber ab, trifft alles in der Nähe und macht es 6 Sek. lang benommen.",
        requires = "Talent Druckwelle; das bricht deinen aktuellen Zauber ab", mods = {  } },
      ["fire-combustion-burst"] = { title = "Schmuckstücke und Verbrennung, dann Feuerball", use = "Nutzt beide Schmuckstücke, zündet Verbrennung und beginnt Feuerball. Halte Shift, um stattdessen Versengen zu nutzen. Verbrennung hält, bis du drei nicht regelmäßige kritische Treffer mit Feuerzaubern erzielt hast.",
        requires = "Talent Verbrennung (40)", mods = { "Schmuckstücke, Verbrennung, dann Feuerball", "Schmuckstücke, Verbrennung, dann Versengen" } },
      ["fire-fire-blast"] = { title = "Sofortiger Feuerschlag", use = "Bricht deinen aktuellen Zauber ab und wirkt sofort Feuerschlag.",
        requires = "Feuerschlag erlernt; das bricht deinen aktuellen Zauber ab", mods = {  } },
      ["fire-fireball-scorch"] = { title = "Feuerball oder Versengen", use = "Halte Shift für Versengen, wenn du eine kürzere Zauberzeit brauchst.",
        requires = "Versengen erlernt (22)", mods = { "Feuerball wirken", "Versengen wirken" } },
      ["fire-flamestrike-rank"] = { title = "Flammenstoß, Rang 1 auf Shift", use = "Wirkt den höchsten Rang von Flammenstoß oder mit Shift Rang 1, um Mana zu sparen, dann klickst du auf den Boden. In Forever kann pro Magier nur ein Flammenstoß gleichzeitig aktiv sein.",
        requires = "Flammenstoß erlernt", mods = { "Wirke deinen höchsten Rang von Flammenstoß", "Wirke Flammenstoß Rang 1" } },
      ["fire-frostfire-kite"] = { title = "Feuerball, mit Frostfeuerblitz zum Kiten", use = "Feuerball auf der Taste. Shift wirkt Frostfeuerblitz. Das verlangsamt das Ziel um 40% und kann beim Aufbau von Aufwärmen helfen.",
        requires = "Frostfeuerblitz (beim Lehrer ab 40); Talent Aufwärmen für den Pyroschlag-Bonus", mods = { "Feuerball wirken", "Frostfeuerblitz wirken" } },
      ["fire-hot-streak"] = { title = "Feuerball, mit Pyroschlag und Feuerschlag auf Modifikatoren", use = "Feuerball auf der Taste. Shift wirkt Pyroschlag, sobald Aufwärmen die Zauberzeit verkürzt hat, und Ctrl wirkt Feuerschlag sofort, während du dich bewegst.",
        requires = "Talente Aufwärmen und Pyroschlag", mods = { "Feuerball wirken", "Pyroschlag wirken", "Feuerschlag wirken" } },
      ["fire-pyroblast-opener"] = { title = "Pyroschlag zum Eröffnen, danach Feuerball", use = "Außerhalb des Kampfes wirkt die Taste Pyroschlag als Opener auf große Distanz. Sobald du im Kampf bist, wirkt sie Feuerball.",
        requires = "Talent Pyroschlag", mods = {  } },
      ["fire-target-and-fireball"] = { title = "Nächsten Gegner greifen und Feuerball", use = "Löst ein totes oder freundliches Ziel, wählt den nächsten Gegner, wenn du keins hast, und wirkt dann Feuerball darauf.",
        requires = "Feuerball erlernt", mods = {  } },
      ["frost-blizzard-rank"] = { title = "Blizzard, Rang 1 auf Shift", use = "Wirkt den höchsten Rang von Blizzard oder mit Shift Rang 1, um Mana zu sparen, dann klickst du auf den Boden.",
        requires = "Blizzard erlernt", mods = { "Wirke deinen höchsten Rang von Blizzard", "Wirke Blizzard Rang 1" } },
      ["frost-buff-sequence"] = { title = "Eisrüstung, dann Arkane Intelligenz", use = "Einmal drücken für Eisrüstung und innerhalb von 10 Sekunden erneut für Arkane Intelligenz, beides auf dich selbst.",
        requires = "Eisrüstung (30) und Arkane Intelligenz erlernt", mods = {  } },
      ["frost-frost-nova"] = { title = "Sofortige Frostnova", use = "Bricht deinen aktuellen Zauber ab, um Gegner in Nahkampfreichweite einzufrieren.",
        requires = "Frostnova erlernt; das bricht deinen aktuellen Zauber ab", mods = {  } },
      ["frost-frostbolt"] = { title = "Schnelle Verlangsamung oder voller Frostblitz", use = "Halte Shift für Rang 1 als günstigere Verlangsamung; drück normal für deinen höchsten Rang.",
        requires = "Frostblitz erlernt; die Rang-Syntax folgt dem englischen Client", mods = { "Wirke deinen höchsten Rang von Frostblitz", "Wirke Frostblitz Rang 1" } },
      ["frost-frostbolt-trinkets"] = { title = "Frostblitz, mit Schmuckstücken auf Shift", use = "Frostblitz auf der Taste. Halte Shift, um beim Zaubern beide Schmuckstücke zu nutzen.",
        requires = "Frostblitz erlernt", mods = { "Frostblitz wirken", "Nutze beide Schmuckstücke und wirke dann Frostblitz" } },
      ["frost-ice-lance-key"] = { title = "Eislanze, Feuerschlag und Kältekegel auf einer Taste", use = "Eislanze auf der Taste oder Feuerschlag mit Shift, wenn das Ziel nicht eingefroren ist; beide teilen sich 8 Sek. Abklingzeit. Ctrl wirkt eine Verlangsamung mit Kältekegel.",
        requires = "Talent Eislanze; Kältekegel erlernt (26). Das bricht deinen aktuellen Zauber ab.", mods = { "Eislanze wirken", "Feuerschlag wirken", "Kältekegel wirken" } },
      ["frost-nova-lance"] = { title = "Frostnova, dann Eislanze", use = "Der erste Druck friert Gegner in der Nähe ein. Ein zweiter Druck innerhalb von 6 Sekunden wirft Eislanze auf das eingefrorene Ziel. Leg Eislanze zusätzlich auf eine eigene Taste, weil dieses Makro auf die Abklingzeit der Frostnova wartet.",
        requires = "Talent Eislanze; das bricht deinen aktuellen Zauber ab", mods = {  } },
      ["frost-target-and-frostbolt"] = { title = "Nächsten Gegner anvisieren und Frostblitz", use = "Löst ein totes oder freundliches Ziel, wählt den nächsten Gegner, wenn du keins hast, und wirkt dann Frostblitz darauf.",
        requires = "Frostblitz erlernt", mods = {  } },
      ["pvp-arcane-wrath-opener"] = { title = "Arkaner Zorn zum Eröffnen, danach Arkanschlag", use = "Außerhalb des Kampfes wirkt die Taste Arkaner Zorn, deinen größten Arkantreffer, auf jemanden, der dich noch nicht gesehen hat. Sobald du kämpfst, wirkt sie Arkanschlag.",
        requires = "Talente Arkaner Zorn (25) und Arkanschlag. Leg Zorn auch auf eine eigene Taste, wegen seiner Abklingzeit von 6 Sek. mitten im Kampf.", mods = {  } },
      ["pvp-blast-wave-blink"] = { title = "Druckwelle, dann Blinzeln", use = "Der erste Tastendruck bricht deinen Zauber ab und trifft alle in der Nähe mit Druckwelle: Sie sind 6 Sek. lang benommen und nur halb so schnell. Dreh dich weg und drück erneut für Blinzeln. Praktisch, wenn Frostnova Abklingzeit hat.",
        requires = "Talent Druckwelle (30) und Blinzeln (20). Die Sequenz wartet auf die Abklingzeit von Druckwelle und setzt sich nach 6 Sek. zurück.", mods = {  } },
      ["pvp-cold-snap-nova"] = { title = "Kälteeinbruch für eine zweite Frostnova oder Eisbarriere", use = "Bricht deinen Zauber für Frostnova ab. Hat Nova oder Eisbarriere Abklingzeit, nutzt Shift Kälteeinbruch und setzt erneut Nova ein, Ctrl nutzt Kälteeinbruch und baut Eisbarriere wieder auf.",
        requires = "Talent Kälteeinbruch; Talent Eisbarriere (40) für Ctrl. Kälteeinbruch hat 10 Min. Abklingzeit und setzt alle deine Frostzauber zurück, auch Eisblock.", mods = { "Frostnova", "Kälteeinbruch, dann Frostnova", "Kälteeinbruch, dann Eisbarriere" } },
      ["pvp-cone-then-blink"] = { title = "Kältekegel, dann Blinzeln", use = "Der erste Tastendruck bricht deinen Zauber ab und trifft alle vor dir mit Kältekegel. Dreh dich weg und drück erneut für Blinzeln, solange sie verlangsamt sind. Nutze es, wenn Frostnova Abklingzeit hat.",
        requires = "Kältekegel (26) und Blinzeln (20). Die Sequenz wartet auf die Abklingzeit von Kältekegel und setzt sich nach 6 Sek. zurück.", mods = {  } },
      ["pvp-counterspell-arcane-wrath"] = { title = "Gegenzauber, dann Arkaner Zorn während der Stille", use = "Wirkt Gegenzauber auf dein Ziel und startet sofort Arkaner Zorn. Mit beiden Rängen von Verb. Gegenzauber ist das Ziel 4 Sek. lang zum Schweigen gebracht, länger als die 3.5 Sek. Zauberzeit von Zorn.",
        requires = "Talente Verbesserter Gegenzauber und Arkaner Zorn (25); Gegenzauber (24). Eine Stille verhindert keine Nahkampf-Unterbrechungen wie Tritt oder Zuschlagen.", mods = {  } },
      ["pvp-counterspell-instant-sheep"] = { title = "Gegenzauber, dann ein sofortiges Schaf", use = "Wirkt Gegenzauber auf den Gegner unter deinem Cursor oder dein Ziel und nutzt dann Geistesgegenwart, um denselben Gegner sofort in ein Schaf zu verwandeln. Gut gegen einen Heiler mitten im Zauber.",
        requires = "Talent Geistesgegenwart und Gegenzauber (24). Klingt Geistesgegenwart noch ab, ist das Schaf ein normaler Zauber. Hast du einen gerade erst begonnenen Zauber abgebrochen, drück noch einmal.", mods = {  } },
      ["pvp-dismount-pyro-opener"] = { title = "Absteigen und mit Pyroschlag und Schmuckstücken eröffnen", use = "Außerhalb des Kampfes holt dich ein Druck vom Reittier, zündet beide Schmuckstücke und startet Pyroschlag auf dein Ziel. Sobald du kämpfst, ist dieselbe Taste Feuerschlag.",
        requires = "Talent Pyroschlag; Schmuckstücke mit Benutzen-Effekt für die Schmuckstück-Zeilen", mods = {  } },
      ["pvp-fire-blast-pyro"] = { title = "Feuerschlag, dann ein schnellerer Pyroschlag", use = "Der erste Tastendruck ist Feuerschlag. Bei einem Treffer gibt es einen Aufwärmen-Stapel (bei einem Krit zwei), sodass Pyroschlag beim nächsten Tastendruck mindestens 25% schneller gewirkt wird. Halte Shift, um Verbrennung dazuzunehmen.",
        requires = "Talente Aufwärmen und Pyroschlag; Verbrennung (40) für Shift. Solange Feuerschlag abklingt, tut der erste Druck nichts.", mods = { "Feuerschlag, beim nächsten Tastendruck dann Pyroschlag", "Zusätzlich Verbrennung" } },
      ["pvp-frostbolt-ice-lance"] = { title = "Frostblitz, dann Eislanze beim Einschlag", use = "Drück bei einem eingefrorenen Ziel einmal für Frostblitz und kurz vor dem Einschlag noch einmal für Eislanze, damit beide treffen, solange das Einfrieren hält. Ein neues Ziel oder 4 Sek. Pause setzen die Sequenz zurück.",
        requires = "Talent Eislanze. Frostnova, Erfrierung oder Eisige Finger frieren das Ziel ein, und Eislanze trifft ein eingefrorenes Ziel viel härter. Seine Abklingzeit von 8 Sek. teilt es sich mit Feuerschlag.", mods = {  } },
      ["pvp-frostbolt-kite"] = { title = "Frostblitz zum Verlangsamen, Kältekegel, wenn sie nah sind", use = "Wirkt Frostblitz auf den Gegner unter deinem Cursor oder dein Ziel. Shift wirkt Rang 1, mit 1.5 Sek. Zauberzeit und kürzerer Verlangsamung. Ctrl bricht deinen Zauber für Kältekegel ab, und deine Stapel von Winterkälte verstärken den Treffer.",
        requires = "Kältekegel (26) für Ctrl", mods = { "Frostblitz auf dein Mouseover-Ziel oder dein Ziel", "Frostblitz Rang 1 auf denselben Gegner", "Zauber abbrechen, dann Kältekegel" } },
      ["pvp-frostfire-slow"] = { title = "Frostfeuerblitz aufs Mouseover, Frostblitz Rang 1 auf Shift", use = "Wirkt Frostfeuerblitz auf den Gegner unter deinem Cursor oder dein Ziel und hinterlässt Brennen und Verlangsamung. Shift wirkt stattdessen Frostblitz Rang 1 mit 1.5 Sek. Zauberzeit, wenn du die Verlangsamung früher brauchst.",
        requires = "Frostfeuerblitz (beim Lehrer ab 40). Krits von Frostfeuerblitz bauen ebenfalls Aufwärmen auf.", mods = { "Frostfeuerblitz auf dein Mouseover-Ziel oder dein Ziel", "Frostblitz Rang 1 auf denselben Gegner" } },
      ["pvp-ice-block-exit"] = { title = "Eisblock verlassen mit Blinzeln, Eisbarriere oder Eislanze", use = "Bricht Eisblock ab und blinzelt weg. Mit Shift kommst du stattdessen mit Eisbarriere heraus, mit Ctrl mit Eislanze auf dein Ziel. Fällt nur der Block weg, drück erneut.",
        requires = "Talent Eisblock; Talente Eisbarriere (40) und Eislanze für die Modifikatoren. Der Zauber nach dem Abbrechen braucht manchmal noch diesen zweiten Tastendruck.", mods = { "Brich Eisblock ab, dann Blinzeln", "Brich Eisblock ab, dann Eisbarriere", "Brich Eisblock ab, dann Eislanze auf dein Ziel" } },
      ["pvp-mana-shield-gem"] = { title = "Manaschild, mit Manaedelstein auf Shift", use = "Bricht deinen Zauber ab und baut Manaschild auf. Halte Shift, um vorher einen Manaedelstein zu nutzen, denn der Schild zieht bei jedem abgefangenen Treffer Mana ab.",
        requires = "Manaschild (20) und ein herbeigezauberter Stein für Shift. Arkane Schilde senkt das Mana, das jeder Schadenspunkt kostet, um ein Drittel. Die Gegenstandsnamen sind die aus Classic.", mods = { "Manaschild wirken", "Manastein nutzen, dann Manaschild wirken" } },
      ["pvp-missile-barrage"] = { title = "Arkane Geschosse bei Geschosssalve-Proc", use = "Leuchtet Geschosssalve auf, bricht das hier deinen Feuerball oder Frostblitz ab und feuert die schnellen, kostenlosen Geschosse auf den Gegner unter deinem Mauszeiger oder dein Ziel. Wiederholtes Hämmern startet die Kanalisierung nicht neu.",
        requires = "Talent Geschosssalve. Ein Zauber, den du vor weniger als 1.5 Sek. begonnen hast, hält noch die globale Abklingzeit, also warten die Geschosse darauf.", mods = {  } },
      ["pvp-nova-pyro"] = { title = "Frostnova, dann Pyroschlag, solange sie festsitzen", use = "Der erste Druck friert alles um dich herum ein. Geh aus der Nahkampfreichweite und drück erneut, um Pyroschlag mit voller Zauberzeit zu wirken, bevor das Einfrieren endet. Nach 8 Sek. setzt es sich zurück.",
        requires = "Talent Pyroschlag. Die Frostnova hält bis zu 8 Sek. und ein voller Pyroschlag dauert 6 Sek., also geben dir Aufwärmen-Stapel Spielraum. Einen laufenden Zauber bricht das Makro nicht ab.", mods = {  } },
      ["pvp-nova-then-blink"] = { title = "Frostnova, dann Blinzeln beim nächsten Druck", use = "Der erste Druck bricht deinen Zauber ab und friert alles um dich herum ein. Dreh dich weg und drück erneut, um mit Blinzeln wegzukommen. Nach 8 Sek. ohne Druck beginnt es wieder bei der Frostnova.",
        requires = "Frostnova und Blinzeln (20) erlernt. Die Abfolge wartet auf die Abklingzeit der Frostnova, also behalte zusätzlich eine normale Taste für Blinzeln.", mods = {  } },
      ["pvp-presence-arcane-wrath"] = { title = "Sofortiger Arkaner Zorn, mit Arkane Macht auf Shift", use = "Mit Geistesgegenwart wirkst du Arkaner Zorn beim nächsten Mal ohne Zauberzeit. Shift zündet zusätzlich beide Schmuckstücke und Arkane Macht. Am härtesten trifft es nach ein paar Arkanschlägen.",
        requires = "Talente Geistesgegenwart und Arkaner Zorn (25), dazu Arkane Macht für Shift. Alle drei liegen im Arkanbaum.", mods = { "Geistesgegenwart, dann Arkaner Zorn ohne Zauberzeit", "Dazu Schmuckstücke und Arkane Macht, dann Arkaner Zorn ohne Zauberzeit" } },
      ["pvp-pvp-burst"] = { title = "Burst: Schmuckstücke, Arkane Macht und Geistesgegenwart", use = "Nutzt beide Schmuckstücke, Arkane Macht und Geistesgegenwart und wirkt dann sofort Pyroschlag. Halte Shift für Frostblitz, wenn du Pyroschlag nicht hast.",
        requires = "Talente Arkane Macht und Geistesgegenwart (Arkan), dazu das Talent Pyroschlag (Feuer) für den Standardzauber", mods = { "Abklingzeiten, dann Pyroschlag als Sofortzauber", "Abklingzeiten, dann Frostblitz als Sofortzauber" } },
      ["pvp-pvp-counterspell"] = { title = "Gegenzauber auf Ziel, Mouseover oder mit Folgezauber", use = "Bricht deinen Zauber und Eisblock ab und wirkt dann Gegenzauber auf dein Ziel. Mit Shift trifft es dein Mouseover-Ziel, mit Ctrl folgt direkt danach ein Frostblitz.",
        requires = "Gegenzauber erlernt (24). Das Makro bricht deinen Zauber auch dann ab, wenn Gegenzauber noch abklingt. Gegenzauber ist nicht an die globale Abklingzeit gebunden, also kann die Zeile mit Frostblitz direkt folgen.", mods = { "Gegenzauber auf dein Ziel", "Stattdessen Gegenzauber auf dein Mouseover-Ziel", "Gegenzauber auf dein Ziel, dann Frostblitz starten" } },
      ["pvp-pvp-decurse-counter"] = { title = "Verbündeten entfluchen oder Gegenzauber auf den Gegner unter dem Mauszeiger", use = "Bricht deinen Zauber ab und entflucht dann den Verbündeten unter deinem Mauszeiger oder wirkt Gegenzauber auf den Gegner dort. Ist nichts unter dem Mauszeiger, nimmt es dein Ziel. Shift entflucht dich.",
