      ["pvp-pvp-escape"] = { title = "Blinzeln, Flucht-Volksfähigkeit, Schmuckstücke und Trank der freien Aktion", use = "Steigt ab, bricht deinen Zauber ab und nutzt Blinzeln. Shift nutzt stattdessen deine Volksfähigkeit zur Flucht, Ctrl nutzt zu Blinzeln noch beide Schmuckstücke und Alt einen Trank der freien Aktion.",
