      ["pvp-pvp-finisher"] = { title = "Feuerschlag oder Eislanze aufs Mouseover", use = "Bricht deinen Zauber ab und wirkt sofort Feuerschlag auf den Gegner unter deinem Mauszeiger oder auf dein Ziel. Mit Shift wirfst du stattdessen Eislanze, den besseren Treffer auf ein eingefrorenes Ziel. Beide teilen sich 8 Sek. Abklingzeit.",
