      ["pvp-pvp-ice-block"] = { title = "Eisblock an und aus, mit Kälteeinbruch auf Shift", use = "Wirkt Eisblock, ein zweiter Tastendruck beendet die Wirkung vorzeitig. Mit Shift wirkst du Kälteeinbruch, um deine Frost-Abklingzeiten zurückzusetzen, damit der nächste Tastendruck wieder Eisblock wirken kann.",
