      ["pvp-pvp-polymorph"] = { title = "Verwandlung aufs Mouseover oder Ziel, Rang 1 auf Shift", use = "Bricht deinen Zauber ab und verwandelt den Gegner unter deinem Mauszeiger oder dein Ziel. Shift wirkt Rang 1, der weniger Mana kostet und kürzer hält.",
        requires = "Verwandlung erlernt", mods = { "Verwandlung auf dein Mouseover-Ziel oder dein Ziel", "Wirke Verwandlung Rang 1 auf denselben Gegner" } },
      ["pvp-pvp-presence"] = { title = "Geistesgegenwart plus ein Sofortzauber", use = "Nutzt Geistesgegenwart und wirkt einen Zauber sofort. Standardmäßig Arkanschlag, Shift für Pyroschlag, Ctrl für Verwandlung und Alt für Frostblitz.",
