      ["pvp-pvp-school-swap"] = { title = "Schule wechseln nach Gegenzauber-Sperre", use = "Frostblitz auf der Taste. Sperrt ein gegnerischer Gegenzauber Frost, wirkt Shift Feuerball und Ctrl Arkane Geschosse.",
