      ["pvp-pvp-sheep-and-back"] = { title = "Zweiten Gegner sheepen und zurückwechseln", use = "Wechsle mit Tab zu einem zweiten Gegner, drück das hier, um ihn zu sheepen, und du bist sofort wieder auf deinem ersten Ziel.",
