      ["pvp-pvp-shields"] = { title = "Manaschild, Eisbarriere und beide Schutzzauber auf einer Taste", use = "Bricht deinen Zauber ab und baut einen Schild auf. Manaschild auf der Taste, Shift für Eisbarriere, Ctrl für Frostzauberschutz und Alt für Feuerzauberschutz.",
