      ["pvp-pvp-slow"] = { title = "Frostblitz aufs Mouseover zum Verlangsamen", use = "Wirkt Frostblitz auf den Gegner unter deinem Mauszeiger oder auf dein Ziel, wenn dort keiner ist. Shift wirkt Rang 1, der billiger ist und kürzer verlangsamt.",
