      ["pvp-racial-burst"] = { title = "Schmuckstücke und dein Volks-Burst auf einer Taste", use = "Nutzt beide Schmuckstücke und Berserker, Kochendes Blut oder Heureka!, je nachdem, was dein Volk hat. Drück es kurz vor deinem Burst, damit alles zusammenfällt.",
