      ["pvp-sheep-evocation"] = { title = "Sheepen, dann Hervorrufung", use = "Der erste Tastendruck verwandelt dein Ziel in ein Schaf. Der zweite startet Hervorrufung, während es herumläuft, damit du in einem langen Duell dein Mana zurückbekommst. Ein neues Ziel oder 20 Sek. Pause starten die Sequenz neu.",
