        requires = "Verbannen erlernt; wirkt nur auf Dämonen und Elementare", mods = {  } },
      ["demonology-breath-and-sight"] = { title = "Unendlicher Atem und Unsichtbarkeit entdecken", use = "Gib deinem Mouseover-Ziel, deinem freundlichen Ziel oder dir selbst Unendlicher Atem und halte Shift, um stattdessen Unsichtbarkeit entdecken zu geben.",
        requires = "", mods = { "Unendlicher Atem", "Unsichtbarkeit entdecken" } },
      ["demonology-fel-domination-summon"] = { title = "Teufelsbeherrschung und beschwören", use = "Zünde Teufelsbeherrschung und beginne im selben Tastendruck die Beschwörung: Leerwandler oder mit Modifikator ein anderer Dämon.",
        requires = "Talent Teufelsbeherrschung (Stufe 25) und jeder Dämon erlernt. Die Abklingzeit beträgt in Forever 5 Minuten", mods = { "Leerwandler beschwören", "Wichtel beschwören", "Sukkubus beschwören", "Teufelsjäger beschwören" } },
      ["demonology-health-funnel"] = { title = "Lebenslinie, Shift zum Stoppen", use = "Kanalisiere in deinen lebenden Dämon. Wiederholtes Drücken startet Lebenslinie nicht neu; halte Shift, um aufzuhören, sobald dein Begleiter gesund ist.",
        requires = "Lebenslinie erlernt; lebender Begleiter", mods = { "Kanalisiere Lebenslinie, ohne neu zu starten", "Zaubern abbrechen" } },
      ["demonology-sacrifice-resummon"] = { title = "Opfern, dann einen anderen Dämon beschwören", use = "Opfere deinen Dämon für seinen 2-Stunden-Effekt und beschwöre sofort einen neuen.",
        requires = "Talente Dämonische Opferung und Dämonischer Pakt, mit einem Dämon draußen. Der Pakt braucht 31 Punkte in Dämonologie, im Planer Stufe 40; wann er im Spiel freigeschaltet wird, haben wir noch nicht getestet. Beschwörst du den geopferten Dämon, endet der Effekt.", mods = { "Teufelsjäger beschwören", "Wichtel beschwören", "Leerwandler beschwören", "Sukkubus beschwören" } },
      ["demonology-sayaad-summon"] = { title = "Sukkubus oder Inkubus beschwören", use = "Beschwöre deinen Sukkubus, oder halte Shift für den Inkubus, der in Forever eine eigene Beschwörung ist.",
        requires = "Sukkubus beschwören und Inkubus beschwören, beide ab Stufe 20. Mit jedem der beiden bekommst du beim Opfern den Feuerschaden-Bonus", mods = { "Sukkubus beschwören", "Inkubus beschwören" } },
      ["demonology-subjugate-demon"] = { title = "Dämon unterwerfen auf Mouseover", use = "Nutze den umbenannten Dämonenkontrollzauber aus Forever auf ein Mouseover.",
        requires = "Dämon unterwerfen erlernt", mods = {  } },
      ["demonology-summon-or-recall"] = { title = "Leerwandler beschwören oder zurückrufen", use = "Beschwöre den Leerwandler, wenn er fehlt oder tot ist, sonst ruf ihn an deine Seite zurück.",
        requires = "Leerwandler beschwören erlernt (Stufe 10)", mods = {  } },
      ["demonology-torment"] = { title = "Qual des Leerwandlers auf Mouseover oder Ziel", use = "Spott des Leerwandlers auf dein Mouseover oder auf den Gegner in deinem Ziel.",
        requires = "Ein lebender Leerwandler (Stufe 10)", mods = {  } },
      ["destruction-bane-of-havoc"] = { title = "Omen der Verwüstung auf Mouseover", use = "Leg Omen der Verwüstung auf den Gegner unter deinem Mauszeiger oder auf dein Ziel, damit 15% deines Schadens an anderen Zielen auch ihn treffen.",
        requires = "Talent Omen der Verwüstung. Es belegt den Omen-Platz auf diesem Gegner, also kann Omen der Pein nicht daneben liegen", mods = {  } },
      ["destruction-conflagrate"] = { title = "Mouseover-Feuersbrunst", use = "Feuersbrunst auf ein Mouseover-Ziel, auf dem dein Feuerbrand liegt, oder auf dein Ziel, wenn nichts unter dem Mauszeiger ist.",
        requires = "Talent Feuersbrunst, das du in Forever ab Stufe 25 erreichst", mods = {  } },
      ["destruction-hellfire-toggle"] = { title = "Höllenfeuer an und aus", use = "Beginne Höllenfeuer und drück erneut, um es zu stoppen, denn es verbrennt dich genauso wie Gegner in der Nähe. Seit dem Update vom 1. Oktober kann es kritisch treffen.",
        requires = "Höllenfeuer erlernt (Stufe 30)", mods = {  } },
      ["destruction-immolate"] = { title = "Mouseover-Feuerbrand", use = "Leg Feuerbrand auf einen anderen Gegner, ohne das Ziel zu wechseln.",
        requires = "Feuerbrand erlernt", mods = {  } },
      ["destruction-incinerate-loop"] = { title = "Feuerbrand, dann Verbrennen", use = "Schick deinen Dämon rein und drück wiederholt: zuerst Feuerbrand, dann fünfmal Verbrennen, das härter trifft, solange Feuerbrand auf dem Ziel liegt.",
        requires = "Talent Verbrennen (Stufe 40); ein Dämon draußen", mods = {  } },
      ["destruction-nuke-chooser"] = { title = "Schadenszauber per Modifikatortaste wählen", use = "Wirke Schattenblitz oder halte einen Modifikator für Verbrennen, Feuersbrunst oder Schattenbrand.",
        requires = "Talente Verbrennen, Feuersbrunst und Schattenbrand und ein Seelensplitter für Schattenbrand", mods = { "Schattenblitz", "Verbrennen", "Feuersbrunst", "Schattenbrand" } },
      ["destruction-shadow-bolt"] = { title = "Schattenblitz und Begleiterangriff", use = "Schick deinen Dämon auf den Gegner, während du Schattenblitz beginnst.",
        requires = "Lebender Dämon für den Begleiterbefehl", mods = {  } },
      ["destruction-shadow-bolt-imp"] = { title = "Schattenblitz mit Feuerblitz-Befehl für den Wichtel", use = "Wirke Schattenblitz auf dein Ziel und fordere Feuerblitz auf den aktuellen Gegner deines Wichtels an. Das schickt den Wichtel nicht auf ein neues Ziel und umgeht weder sein Mana noch seine Zauberzeit oder Abklingzeit.",
        requires = "Ein lebender Wichtel mit erlerntem Feuerblitz und ein feindliches Ziel", mods = {  } },
      ["destruction-shadowburn"] = { title = "Mouseover-Schattenbrand", use = "Erledige ein Mouseover-Ziel mit Schattenbrand; stirbt es innerhalb von 8 Sekunden, bekommst du einen Seelensplitter zurück.",
        requires = "Talent Schattenbrand und ein Seelensplitter zum Wirken", mods = {  } },
      ["pvp-amplify-exhaustion"] = { title = "Fluch verstärken in Fluch der Erschöpfung", use = "Brich deinen Zauber ab, zünde Fluch verstärken und verlangsame dein Mouseover-Ziel oder Ziel mit Fluch der Erschöpfung. Hat Fluch verstärken Abklingzeit, kommt die Verlangsamung trotzdem.",
        requires = "Talente Fluch verstärken und Fluch der Erschöpfung. Fluch verstärken macht die Verlangsamung stärker und hat 3 Minuten Abklingzeit. Drückst du in den ersten 1.5 Sekunden eines anderen Zaubers, geht der Fluch nicht raus, also drück erneut", mods = {  } },
      ["pvp-amplify-weakness"] = { title = "Fluch verstärken in Fluch der Schwäche", use = "Zünde Fluch verstärken und leg Fluch der Schwäche auf den Schurken oder Krieger, der auf dich einschlägt, auf dein Mouseover-Ziel oder Ziel. Fluch verstärken macht den Fluch 50% stärker.",
        requires = "Talent Fluch verstärken (3 Minuten Abklingzeit). In Forever senkt Fluch der Schwäche den körperlichen Schaden, den der Gegner verursacht. Du hast einen Fluch pro Gegner, also ersetzt er Erschöpfung oder Sprachen", mods = {  } },
      ["pvp-assist-strike"] = { title = "Assist, dann Fluch oder Omen", use = "Übernimm das Ziel des freundlichen Spielers, den du im Ziel hast, und eröffne darauf mit Omen der Pein oder mit Modifikator mit einem Fluch.",
        requires = "Ein freundlicher Spieler im Ziel; Talent Fluch der Erschöpfung für Ctrl", mods = { "Omen der Pein auf das Ziel deines Verbündeten", "Fluch der Sprachen darauf", "Fluch der Erschöpfung darauf" } },
      ["pvp-bane-picker"] = { title = "Omen der Verwüstung oder Omen der Pein auf einer Taste", use = "Leg Omen der Verwüstung auf dein Mouseover-Ziel oder Ziel, etwa ihren Heiler, damit 15% deines Schadens an anderen Gegnern auch ihn treffen. Halte Shift für Omen der Pein auf dein Ziel.",
        requires = "Talent Omen der Verwüstung. Havoc liegt immer nur auf einem Gegner, und jeder Gegner trägt ein Omen von dir", mods = { "Omen der Verwüstung auf dein Mouseover-Ziel oder Ziel", "Omen der Pein auf dein Ziel" } },
      ["pvp-burst-trinkets"] = { title = "Schmuckstücke, Volksfähigkeit und ein Schadenszauber", use = "Nutze beide Schmuckstücke und deine Orc- oder Troll-Volksfähigkeit und wirke dann Schattenblitz oder mit Modifikator Feuersbrunst oder Schattenbrand.",
        requires = "Schmuckstücke mit Benutzen-Effekt, falls du welche hast; Kochendes Blut (Orc) oder Berserker (Troll), wenn das dein Volk ist; Talente Feuersbrunst und Schattenbrand für die Modifikatoren", mods = { "Abklingzeiten, dann Schattenblitz", "Abklingzeiten, dann Feuersbrunst", "Abklingzeiten, dann Schattenbrand" } },
      ["pvp-coil-howl"] = { title = "Todesmantel oder Schreckensgeheul", use = "Brich deinen Zauber ab und wirke Todesmantel auf dein Ziel, mit Shift auf dein Mouseover-Ziel oder mit Ctrl Schreckensgeheul.",
        requires = "Todesmantel (Stufe 42) und Schreckensgeheul (Stufe 40) erlernt. Todesmantel hat 2 Minuten Abklingzeit", mods = { "Brich deinen Zauber ab und wirke Todesmantel auf dein Ziel", "Stattdessen Todesmantel auf dein Mouseover-Ziel", "Brich deinen Zauber ab und Schreckensgeheul" } },
      ["pvp-conflag-daze"] = { title = "Zauber abbrechen und Feuersbrunst auf einen Flüchtenden", use = "Brich deinen Zauber ab und wirke Feuersbrunst auf dein Ziel oder mit Shift auf dein Mouseover-Ziel. Mit 5 Punkten in Nachwirkung macht Feuersbrunst das Ziel jedes Mal benommen und verlangsamt es 5 Sekunden lang um 50%.",
        requires = "Talent Feuersbrunst und dein Feuerbrand auf dem Ziel; Nachwirkung für die Benommenheit. Drückst du in den ersten 1.5 Sekunden eines anderen Zaubers, bricht das nur diesen Zauber ab", mods = { "Brich deinen Zauber ab und wirke Feuersbrunst auf dein Ziel", "Brich deinen Zauber ab und wirke Feuersbrunst auf dein Mouseover-Ziel" } },
      ["pvp-corruption-rank-1"] = { title = "Verderbnis Rang 1 gegen Verstohlene", use = "Markiere einen Schurken oder Druiden auf deinem Mouseover-Ziel oder Ziel mit Verderbnis Rang 1 für 35 Mana. Die Ticks holen ihn immer wieder aus der Verstohlenheit, und jeder kann trotzdem Einbruch der Nacht auslösen.",
        requires = "5 Punkte in Verbesserte Verderbnis, sonst hat der Zauber 2 Sekunden Zauberzeit. Hast du schon einen höheren Rang von Verderbnis auf dem Gegner, wird der Zauber blockiert", mods = {  } },
      ["pvp-curse-swap"] = { title = "Fluch der Sprachen, Erschöpfung, Schwäche oder Elemente", use = "Verfluche dein Mouseover oder Ziel mit Sprachen, oder halte eine Modifikatortaste für Erschöpfung, Schwäche oder Elemente.",
        requires = "Talent Fluch der Erschöpfung (Stufe 25); Sprachen ab Stufe 26", mods = { "Fluch der Sprachen", "Fluch der Erschöpfung", "Fluch der Schwäche", "Fluch der Elemente auf dein Ziel" } },
      ["pvp-decimation-soul-fire"] = { title = "Sengender Schmerz in ein Seelenfeuer mit Dezimierung", use = "Halte Shift für Sengender Schmerz auf einen Gegner unter 35% Gesundheit und drück dann für Seelenfeuer. Dank Dezimierung geht der Zauber 10 Sekunden lang schneller und kostet keinen Seelensplitter.",
        requires = "Talent Dezimierung und Seelenfeuer (Stufe 48). Mit 2 Punkten verkürzt Dezimierung auch die Abklingzeit von Seelenfeuer (1 Minuten) um 90%. Schattenblitz löst sie ebenfalls aus", mods = { "Seelenfeuer auf dein Ziel", "Sengender Schmerz auf dein Ziel" } },
      ["pvp-demonic-brand"] = { title = "Gegner mit Sengender Schmerz für deinen Dämon brandmarken", use = "Schick deinen Dämon auf dein Mouseover-Ziel oder Ziel und wirke Sengender Schmerz darauf, damit die nächsten Treffer des Dämons an diesem Gegner zusätzlichen Feuer- oder Schattenschaden verursachen.",
        requires = "Talent Dämonisches Brandmal und ein Dämon draußen. Das Brandmal hält 10 Sekunden und gilt bei 3 Punkten für bis zu 6 Angriffe des Begleiters", mods = {  } },
      ["pvp-devour-magic"] = { title = "Teufelsjäger: Magie verschlingen auf dich oder einen Verbündeten", use = "Magie verschlingen auf dein Mouseover oder Ziel, oder mit Shift auf dich.",
        requires = "Ein lebender Teufelsjäger", mods = { "Magie verschlingen auf dein Mouseover oder dein Ziel", "Magie verschlingen auf dich selbst" } },
      ["pvp-devour-party"] = { title = "Teufelsjäger: Magie verschlingen auf deine Gruppe", use = "Entferne einen Magieeffekt von deinem ersten Gruppenmitglied, ohne es ins Ziel zu nehmen, oder halte eine Modifikatortaste für das zweite, dritte oder vierte. In einem Schlachtfeld-Raid ist das deine eigene Fünfergruppe.",
        requires = "Ein lebender Teufelsjäger. Gruppenmitglieder sind so nummeriert, wie die Standard-Gruppenfenster sie auflisten", mods = { "Magie verschlingen auf dein erstes Gruppenmitglied", "Magie verschlingen auf dein zweites Gruppenmitglied", "Magie verschlingen auf dein drittes Gruppenmitglied", "Magie verschlingen auf dein viertes Gruppenmitglied" } },
      ["pvp-dot-spread"] = { title = "DoTs mit einer Taste verteilen", use = "Leg Verderbnis auf dein Mouseover-Ziel oder Ziel oder halte einen Modifikator für Omen der Pein oder Lebensentzug.",
        requires = "Talent Lebensentzug (Stufe 30). Omen der Pein kann zusammen mit einem Fluch auf demselben Spieler liegen", mods = { "Verderbnis", "Omen der Pein", "Lebensentzug" } },
      ["pvp-drain-swap"] = { title = "Blutsauger, Mana entziehen oder Aderlass", use = "Blutsauger auf dein Ziel, ohne die Kanalisierung neu zu starten, oder halte einen Modifikator für ein Mouseover-Ziel, Mana entziehen oder Aderlass.",
        requires = "Mana entziehen erlernt (Stufe 24). Blizzard hat Dunkler Pakt entfernt, also ist Alt Aderlass", mods = { "Blutsauger auf dein Ziel", "Blutsauger auf dein Mouseover-Ziel", "Mana entziehen auf dein Ziel", "Aderlass, beendet auch eine Kanalisierung" } },
      ["pvp-fear-stop"] = { title = "Zauber abbrechen und Furcht", use = "Brich ab, was du gerade wirkst, spring vom Reittier und wirke Furcht auf dein Ziel oder mit Shift auf dein Mouseover-Ziel.",
        requires = "Furcht erlernt", mods = { "Brich deinen Zauber ab und wirke Furcht auf dein Ziel", "Stattdessen Furcht auf dein Mouseover-Ziel" } },
      ["pvp-felhunter-lock"] = { title = "Zaubersperre, oder Teufelsbeherrschung für einen neuen Teufelsjäger", use = "Ist dein Teufelsjäger draußen, wirkt er Zaubersperre auf den Gegner, den er bekämpft, mit Shift auf dein Mouseover-Ziel. Ohne Teufelsjäger beschwört das Makro einen, im Kampf vorher mit Teufelsbeherrschung.",
        requires = "Talent Teufelsbeherrschung und Teufelsjäger beschwören (Stufe 30). Jeder andere Dämon, den du draußen hast, wird ersetzt. Verbesserter Teufelsjäger verkürzt die Abklingzeit von Zaubersperre um bis zu 6 Sekunden", mods = { "Zaubersperre, oder Teufelsjäger beschwören, wenn er nicht draußen ist", "Zaubersperre auf dein Mouseover" } },
      ["pvp-fire-burst"] = { title = "Burst mit Feuerbrand, Feuersbrunst, Schattenbrand", use = "Drück dreimal für Feuerbrand, Feuersbrunst und Schattenbrand auf dein Ziel oder halte Shift, um mit Fluch der Elemente anzufangen. Ein Zielwechsel startet die Sequenz neu.",
        requires = "Talente Feuersbrunst und Schattenbrand und ein Seelensplitter. Hat Feuersbrunst oder Schattenbrand noch Abklingzeit, passiert bei diesem Tastendruck nichts, bis es bereit ist", mods = { "Feuerbrand, Feuersbrunst, Schattenbrand", "Fluch der Elemente, dann dieselben drei" } },
      ["pvp-funnel-or-sacrifice"] = { title = "Lebenslinie, Shift zum Opfern", use = "Halte deinen Dämon mit Lebenslinie am Leben, ohne die Kanalisierung neu zu starten. Stirbt er sowieso, halte Shift, um ihn für den Effekt von 2 Stunden zu opfern.",
        requires = "Talent Dämonische Opferung und ein lebender Dämon. Ohne das Talent Dämonischer Pakt beendet das Beschwören eines beliebigen Dämons den Effekt", mods = { "Lebenslinie auf deinen Dämon, ohne den Zauber neu zu starten", "Dämonische Opferung" } },
      ["pvp-kite-dots"] = { title = "Sofort-DoT-Abfolge zum Kiten", use = "Drück im Laufen: Fluch der Erschöpfung, Verderbnis, Omen der Pein, dann Lebensentzug auf dein Ziel. Halte Shift, um gegen einen Zauberwirker mit Fluch der Sprachen anzufangen.",
        requires = "Talente Fluch der Erschöpfung und Lebensentzug und 5 Punkte in Verbesserte Verderbnis, damit Verderbnis sofort wirkt. In Forever können ein Omen und ein Fluch auf demselben Gegner liegen. Die Sequenz beginnt neu, wenn du das Ziel wechselst oder den Kampf verlässt", mods = { "Erschöpfung, dann Verderbnis, Omen der Pein und Lebensentzug", "Sprachen, dann Verderbnis, Omen der Pein und Lebensentzug" } },
      ["pvp-nightfall-bolt"] = { title = "Sofortiger Schattenblitz bei Schattentrance-Proc", use = "Leuchtet Schattentrance auf, drück, um deinen Entzug oder Zauber abzubrechen und Schattenblitz sofort auf dein Ziel zu feuern, mit Shift auf dein Mouseover-Ziel.",
        requires = "Talent Einbruch der Nacht. Ohne Schattentrance beginnst du Schattenblitz ganz normal mit 3 Sekunden Zauberzeit. Drückst du in den ersten 1.5 Sekunden eines Entzugs oder Zaubers, bricht das nur diesen ab", mods = { "Brich deinen Zauber ab und wirke Schattenblitz auf dein Ziel", "Brich deinen Zauber ab und wirke Schattenblitz auf dein Mouseover-Ziel" } },
      ["pvp-pact-swap"] = { title = "Mitten im Kampf opfern und schnell einen neuen Dämon holen", use = "Opfere deinen Dämon, dann im selben Tastendruck Teufelsbeherrschung und ein Leerwandler oder mit Modifikator ein anderer Dämon. Ein geopferter Teufelsjäger stellt alle 4 Sekunden 3% deiner Gesundheit wieder her.",
        requires = "Talente Dämonische Opferung, Teufelsbeherrschung und Dämonischer Pakt, mit einem Dämon draußen. Der Pakt behält den Effekt, wenn ein anderer Dämon kommt; beschwörst du den geopferten, endet er", mods = { "Leerwandler beschwören", "Teufelsjäger beschwören", "Sukkubus beschwören" } },
      ["pvp-pet-ability"] = { title = "Die wichtigste Fähigkeit deines Dämons auf einer Taste", use = "Drück für Feuerschild, Opferung, Zaubersperre oder Verführung, je nachdem, was dein aktueller Dämon hat.",
        requires = "Ein lebender Dämon", mods = {  } },
      ["pvp-pet-command"] = { title = "Begleiter angreifen, zurückrufen und passiv auf einer Taste", use = "Schick deinen Dämon auf dein Ziel oder mit Shift auf dein Mouseover, ruf ihn mit Ctrl zurück oder stell ihn mit Alt auf passiv.",
        requires = "Ein lebender Dämon", mods = { "Begleiter greift dein Ziel an", "Begleiter greift dein Mouseover an", "Begleiter folgt dir", "Begleiter wird passiv" } },
      ["pvp-racial-break"] = { title = "Mit der Volksfähigkeit befreien", use = "Drück, um die Volksfähigkeit zu nutzen, die dein Hexenmeister hat: Überlebenswille, Wille der Verlassenen, Entfesselungskünstler oder Fluch brechen.",
        requires = "Ein Hexenmeister als Mensch (entfernt Betäubungen), Untoter (entfernt Bezauberung, Furcht und Schlaf), Gnom (löst bewegungseinschränkende Effekte) oder Orc (entfernt Flüche und Banne). Die anderen Zeilen tun für dein Volk nichts", mods = {  } },
      ["pvp-rain-of-fire-flush"] = { title = "Feuerregen Rang 1 gegen Verstohlenheit", use = "Leg den günstigsten Rang von Feuerregen auf einen Flaggenraum oder einen Punkt, den du bewachst. Die Ticks holen jeden Schurken oder Druiden darin aus der Verstohlenheit. Klick zum Platzieren auf den Boden.",
        requires = "Feuerregen erlernt (Stufe 20). Rang 1 kostet 295 Mana, Rang 4 dagegen 1,185", mods = {  } },
      ["pvp-searing-pain"] = { title = "Sengender Schmerz auf Mouseover", use = "Sengender Schmerz auf dein Mouseover-Ziel oder Ziel. Das ist dein kürzester Zauber, also der, den du weiterwirkst, während dich jemand schlägt.",
        requires = "Sengender Schmerz erlernt (Stufe 18). Peinigende Flammen gibt bis zu 10% kritische Trefferchance darauf, und Intensität hilft gegen Pushback", mods = {  } },
      ["pvp-seduce-fear"] = { title = "Verführung auf Mouseover und Furcht auf dein Ziel", use = "Zeig mit der Maus auf einen zweiten Gegner und drück: Dein Sukkubus verführt ihn, während du Furcht auf dein Ziel beginnst. Ist nichts unter dem Mauszeiger, ist es einfach Furcht.",
        requires = "Sukkubus draußen und am Leben; Furcht erlernt. Schaden an einem der beiden Gegner kann den Effekt brechen", mods = {  } },
      ["pvp-seduction"] = { title = "Verführung des Sukkubus auf Mouseover oder Ziel", use = "Schick den Sukkubus mit Shift auf dein Mouseover oder auf den Gegner, den er schon bekämpft.",
        requires = "Ein lebender Sukkubus. Ob der Inkubus Verführung hat, ist noch nicht bestätigt", mods = { "Verführung auf das Ziel deines Dämons, oder auf deins, wenn er keins hat", "Verführung auf dein Mouseover" } },
      ["pvp-shadow-ward"] = { title = "Zauber abbrechen und Schattenzauberschutz", use = "Brich deinen Zauber ab und aktiviere Schattenzauberschutz, wenn ein Schattenzauberer auf dich loslegt.",
        requires = "Schattenzauberschutz erlernt (Stufe 32). Abklingzeit 30 Sekunden", mods = {  } },
      ["pvp-shadowburn-stop"] = { title = "Zauber abbrechen und Schattenbrand", use = "Brich deinen Schattenblitz ab und erledige dein Ziel mit Schattenbrand als Sofortzauber, bevor die Heilung ankommt, oder mit Shift dein Mouseover-Ziel.",
        requires = "Talent Schattenbrand und ein Seelensplitter; 15 Sekunden Abklingzeit. Drückst du in den ersten 1.5 Sekunden eines anderen Zaubers, bricht das nur diesen Zauber ab", mods = { "Brich deinen Zauber ab und wirke Schattenbrand auf dein Ziel", "Brich deinen Zauber ab und wirke Schattenbrand auf dein Mouseover-Ziel" } },
      ["pvp-soul-fire-opener"] = { title = "Seelenfeuer-Opener mit vorgeschicktem Dämon", use = "Eröffne auf einen Gegner, der dich nicht gesehen hat: Dein Dämon läuft los, sobald Seelenfeuer beginnt. Feuerschwall gibt dem Treffer eine Chance zu betäuben.",
        requires = "Seelenfeuer (Stufe 48) kostet einen Seelensplitter und hat 1 Minuten Abklingzeit. Feuerschwall bringt die Chance auf Betäubung, und 5 Punkte in Dunkle Macht verkürzen die Zauberzeit von 6 Sekunden um 2 Sekunden", mods = {  } },
      ["pvp-soul-link-summon"] = { title = "Seelenverbindung, oder Teufelsbeherrschung und ein neuer Dämon", use = "Ist ein Dämon draußen, wirkt das Makro Seelenverbindung. Ohne Dämon beschwört es einen Teufelsjäger oder mit Shift einen Leerwandler, im Kampf vorher mit Teufelsbeherrschung.",
        requires = "Talente Seelenverbindung (Stufe 30) und Teufelsbeherrschung. Seelenverbindung endet, wenn dein Dämon stirbt, also drück erneut, sobald der neue draußen ist. Mit 2 Punkten in Meister der Beschwörung dauert die schnelle Beschwörung etwa eine halbe Sekunde", mods = { "Seelenverbindung oder ein Teufelsjäger, wenn kein Dämon draußen ist", "Beschwört stattdessen einen Leerwandler, wenn kein Dämon draußen ist" } },
      ["pvp-spell-lock"] = { title = "Zaubersperre des Teufelsjägers auf Mouseover oder Ziel", use = "Schick die Zaubersperre des Teufelsjägers mit Shift auf dein Mouseover oder auf das, was er schon bekämpft.",
