        requires = "Talent Wilde Attacke; Hieb erlernt", mods = { "Anstürmen und Hieb auf dein Ziel", "Anstürmen und Hieb auf dein Mouseover-Ziel" } },
      ["pvp-charge-grasp"] = { title = "Wilde Attacke mit Griff der Natur", use = "In Bärengestalt stürmst du auf dein Mouseover-Ziel oder Ziel und aktivierst im selben Druck Griff der Natur, sodass der nächste Nahkampftreffer gegen dich den Angreifer festwurzelt. Außerhalb der Bärengestalt verwandelt dich der erste Druck.",
        requires = "Talent Wilde Attacke; Griff der Natur (in Forever auch in Gestalt wirkbar)", mods = {  } },
      ["pvp-cleanse-self"] = { title = "Dich oder einen Freund reinigen", use = "Fluch aufheben auf ein Mouseover-Ziel oder dich selbst, Vergiftung aufheben mit Shift, und Ctrl oder Alt, um beides auf dich selbst zu erzwingen. Vorher verlässt du deine Gestalt.",
        requires = "Fluch aufheben und Vergiftung aufheben erlernt", mods = { "Fluch aufheben auf dein Mouseover-Ziel oder dich selbst", "Vergiftung aufheben auf dein Mouseover-Ziel oder dich selbst", "Fluch aufheben auf dich selbst", "Vergiftung aufheben auf dich selbst" } },
      ["pvp-instant-hibernate"] = { title = "Schnelligkeit der Natur, dann Winterschlaf", use = "Verlass deine Gestalt und schick ein Wildtier oder einen Drachkin sofort schlafen, auf deinem Mouseover-Ziel oder feindlichen Ziel; meist ist es der Begleiter eines Jägers. Kann der Zauber nicht starten, bleibt Schnelligkeit der Natur aktiv.",
        requires = "Talent Schnelligkeit der Natur; Winterschlaf erlernt", mods = {  } },
      ["pvp-instant-party-heal"] = { title = "Sofortige Heilende Berührung nach Gruppenplatz", use = "Brich deinen Zauber ab, verlass deine Gestalt und mach Heilende Berührung mit Schnelligkeit der Natur sofort wirkbar, auf dein Mouseover-Ziel oder dich selbst oder mit Shift, Ctrl oder Alt auf Gruppenmitglied 1, 2 oder 3.",
        requires = "Talent Schnelligkeit der Natur", mods = { "Schnelligkeit der Natur, dann Heilende Berührung auf dein Mouseover-Ziel oder dich selbst", "Schnelligkeit der Natur, dann Heilende Berührung auf Gruppenmitglied 1", "Schnelligkeit der Natur, dann Heilende Berührung auf Gruppenmitglied 2", "Schnelligkeit der Natur, dann Heilende Berührung auf Gruppenmitglied 3" } },
      ["pvp-instant-rebirth"] = { title = "Schnelligkeit der Natur, dann Wiedergeburt", use = "Hol den toten Spieler unter deinem Cursor oder dein Ziel mitten im Kampf mit Wiedergeburt ohne Zauberzeit zurück. Vorher verlässt du deine Gestalt, und Wiedergeburt hat 30 Min. Abklingzeit.",
        requires = "Talent Schnelligkeit der Natur; Wiedergeburt erlernt", mods = {  } },
      ["pvp-leap-reveal"] = { title = "Katzensprung und Feenfeuer mit einem Druck", use = "Spring mit Wilde Attacke (Katze) hinter dein Ziel und belege es im selben Druck mit Feenfeuer, damit es sich nicht tarnen oder unsichtbar machen kann. Schlägt einer der Zauber fehl, prüf den Namen in deiner Katzen-Aktionsleiste.",
        requires = "Talent Wilde Attacke; Katzengestalt; 8 bis 25 Meter vom Ziel entfernt", mods = {  } },
      ["pvp-moonkin-heal"] = { title = "Nachwachsen, dann zurück in Moonkingestalt", use = "Moonkingestalt blockiert Heilungen, also verlässt das Makro die Gestalt und wirkt Nachwachsen auf dich; der nächste Druck bringt dich zurück. Nach 10 Sekunden ohne Druck beginnt die Abfolge von vorn.",
        requires = "Talent Moonkingestalt", mods = {  } },
      ["pvp-moonkin-shift"] = { title = "Zurück in Moonkingestalt, um Wurzeln zu brechen", use = "Wechsle erneut in Moonkingestalt, um Wurzeln, Verlangsamungen oder Verwandlung abzuschütteln; aus Moonkin kann es einen zweiten Druck brauchen. Halte Shift für Terrorbärengestalt, wenn dich ein Schurke anspringt, oder Ctrl für Reisegestalt im Freien.",
        requires = "Talent Moonkingestalt; Terrorbärengestalt und Reisegestalt erlernt", mods = { "Moonkingestalt; bist du schon in der Gestalt, verlässt du sie zuerst", "Terrorbärengestalt", "Reisegestalt (im Freien)" } },
      ["pvp-moonkin-support"] = { title = "Reinigen oder Anregen, ohne Moonkin zu verlassen", use = "Fluch aufheben auf dein Mouseover-Ziel oder dich selbst, Vergiftung aufheben mit Shift oder mit Ctrl Anregen auf dich selbst. In Forever blockiert Moonkingestalt nur Heilzauber, also bleibt sie aktiv; andere Gestalten fallen weg.",
        requires = "Talent Moonkingestalt; Fluch aufheben, Vergiftung aufheben und Anregen erlernt", mods = { "Fluch aufheben auf dein Mouseover-Ziel oder dich selbst", "Vergiftung aufheben auf dein Mouseover-Ziel oder dich selbst", "Anregen auf dich selbst" } },
      ["pvp-moving-heals"] = { title = "Sofortheilungen in Bewegung", use = "Verjüngung bei normalem Druck oder Rasche Heilung mit Shift, beide ohne Zauberzeit, auf dein Mouseover-Ziel oder dich selbst. Vorher verlässt du deine Gestalt.",
        requires = "Talent Rasche Heilung; deine eigene Verjüngung oder dein eigenes Nachwachsen auf dem Ziel für Rasche Heilung", mods = { "Verjüngung auf dein Mouseover-Ziel oder dich selbst", "Rasche Heilung auf dein Mouseover-Ziel oder dich selbst" } },
      ["pvp-panic-button"] = { title = "Defensivtaste per Modifier", use = "Baumrinde bei normalem Druck, Griff der Natur mit Ctrl oder in Bärengestalt mit Shift Wutanfall gefolgt von Rasende Regeneration. Baumrinde und Griff der Natur funktionieren beide in Tiergestalt.",
        requires = "Baumrinde, Griff der Natur und Rasende Regeneration erlernt", mods = { "Baumrinde", "Wutanfall, dann Rasende Regeneration (Bärengestalt)", "Griff der Natur" } },
      ["pvp-peel-roots"] = { title = "Festwurzeln, was dein Freund bekämpft", use = "Wurzle den Gegner unter deinem Cursor fest, oder fahr über den Rahmen eines Freundes, um dessen Ziel festzuwurzeln; sonst dein feindliches Ziel oder das Ziel deines freundlichen Ziels. Ohne Wildes Wachstum befreit eine neue Wurzel die letzte.",
        requires = "Wucherwurzeln erlernt; Talent Wildes Wachstum für mehr als eine Wurzel gleichzeitig", mods = {  } },
      ["pvp-potion-in-form"] = { title = "Freie Aktion oder Hurtigkeitstrank, in Gestalt bleiben", use = "Trink einen Trank der freien Aktion, oder mit gehaltenem Shift einen Hurtigkeitstrank, ohne deine Gestalt zu verlassen. In Forever können Druiden Tränke in Tiergestalt nutzen; in Classic musstest du dich erst zurückverwandeln.",
        requires = "Trank der freien Aktion und Hurtigkeitstrank in deinen Taschen", mods = { "Trank der freien Aktion", "Hurtigkeitstrank" } },
      ["pvp-pounce-opener"] = { title = "Anspringen aus der Verstohlenheit, Shift für Verheeren", use = "Betäube aus Schleichen mit Anspringen oder eröffne mit gehaltenem Shift mit Verheeren; außerhalb der Verstohlenheit wird daraus Krallenhieb. Für beide Opener musst du hinter dem Ziel stehen.",
        requires = "Katzengestalt; hinter deinem Ziel", mods = { "Anspringen aus der Verstohlenheit, sonst Krallenhieb", "Verheeren aus der Verstohlenheit" } },
      ["pvp-pounce-roots"] = { title = "Anspringen aus Schleichen, dann Wucherwurzeln", use = "Anspringen aus Schleichen zum Betäuben, dann erneut drücken, um die Katzengestalt zu verlassen und Wucherwurzeln zu starten, solange das Ziel noch betäubt ist. Für Anspringen musst du hinter dem Ziel stehen, und die Blutung kann die Wurzeln brechen.",
        requires = "Katzengestalt und Schleichen; das Talent Verb. Wucherwurzeln hilft, dass die Wurzeln trotz der Blutung halten", mods = {  } },
      ["pvp-reveal"] = { title = "Feenfeuer auf dein Ziel oder Mouseover", use = "Feenfeuer auf dein Ziel oder mit Shift auf dein Mouseover-Ziel, um Verstohlenheit und Unsichtbarkeit zu verhindern. Bleib in Bären-, Katzen-, Terrorbären- oder Moonkingestalt; in Bären-, Katzen- und Terrorbärengestalt kostet der Zauber keine Ressourcen und hat 6 Sek. Abklingzeit.",
        requires = "Feenfeuer erlernt. Wir haben den Zaubernamen von Feenfeuer in Tiergestalten nicht getestet. Falls es fehlschlägt, nimm den Namen aus der Aktionsleiste deiner Gestalt.", mods = { "Feenfeuer auf dein Ziel", "Feenfeuer auf dein Mouseover-Ziel" } },
      ["pvp-roots-run"] = { title = "Wurzeln, Shift für Reisegestalt, Ctrl für Winterschlaf", use = "Wurzle dein Mouseover-Ziel oder Ziel fest, lauf mit Shift in Reisegestalt davon oder schick mit Ctrl ein Wildtier schlafen (ein Jägerbegleiter zählt). Wucherwurzeln funktioniert drinnen wie draußen.",
        requires = "Wucherwurzeln, Winterschlaf und Reisegestalt erlernt", mods = { "Wucherwurzeln auf dein Mouseover-Ziel oder Ziel", "Reisegestalt (im Freien)", "Winterschlaf auf dein Mouseover-Ziel" } },
      ["pvp-starfire-burst"] = { title = "Schmuckstück und Elunes Licht, dann Sternenfeuer", use = "Sternenfeuer bei normalem Druck. Halte Shift, um zuerst dein unteres Schmuckstück und Elunes Licht zu zünden. Wir haben nicht geprüft, ob Elunes Licht die globale Abklingzeit auslöst; falls ja, drück noch einmal für Sternenfeuer.",
        requires = "Sternenfeuer erlernt; ein Schmuckstück mit Benutzen-Effekt im unteren Platz; Elunes Licht nur für Nachtelfen", mods = { "Sternenfeuer", "Unteres Schmuckstück und Elunes Licht, dann Sternenfeuer" } },
      ["pvp-stealth-dance"] = { title = "Schleichen, Spurt oder Schattenmimik auf einer Taste", use = "Wechsle bei Bedarf in Katzengestalt, dann Schleichen oder mit gehaltenem Shift Spurt; Nachtelfen bekommen Schattenmimik auf Ctrl.",
        requires = "Schleichen und Spurt erlernt; Schattenmimik nur für Nachtelfen", mods = { "Bei Bedarf Katzengestalt, dann Schleichen (außerhalb des Kampfes)", "Bei Bedarf Katzengestalt, dann Spurt", "Schattenmimik (Nachtelf)" } },
      ["pvp-swiftmend-party"] = { title = "Rasche Heilung nach Gruppenplatz", use = "Rasche Heilung auf dein Mouseover-Ziel oder dich selbst oder mit Shift, Ctrl oder Alt auf Gruppenmitglied 1, 2 oder 3. Auf dem Ziel muss deine eigene Verjüngung oder dein eigenes Nachwachsen liegen.",
        requires = "Talent Rasche Heilung", mods = { "Rasche Heilung auf dein Mouseover-Ziel oder dich selbst", "Rasche Heilung auf Gruppenmitglied 1", "Rasche Heilung auf Gruppenmitglied 2", "Rasche Heilung auf Gruppenmitglied 3" } },
      ["pvp-swiftness-pvp"] = { title = "Sofortheilung oder sofortige Wurzeln", use = "Schnelligkeit der Natur, dann Heilende Berührung auf ein Mouseover-Ziel oder dich selbst, oder mit gehaltenem Shift Wucherwurzeln ohne Zauberzeit auf dein Ziel.",
        requires = "Talent Schnelligkeit der Natur", mods = { "Schnelligkeit der Natur, dann Heilende Berührung auf dein Mouseover-Ziel oder dich selbst", "Schnelligkeit der Natur, dann Wucherwurzeln auf dein Ziel" } },
      ["pvp-totem-moonfire"] = { title = "Mondfeuer Rang 1 auf ein Schamanentotem", use = "Nimm ein Totem der Erdung ins Ziel und wirk Mondfeuer Rang 1 darauf; Shift für Erdstoß, Ctrl für Erdbindung, Alt für Manaflut. Du bleibst auf dem Totem, und ist keins in Reichweite, trifft Mondfeuer dein Ziel.",
        requires = "Mondfeuer erlernt; Normal- oder Moonkingestalt", mods = { "Mondfeuer Rang 1 auf ein Totem der Erdung", "Mondfeuer Rang 1 auf ein Totem des Erdstoßes", "Mondfeuer Rang 1 auf ein Totem der Erdbindung", "Mondfeuer Rang 1 auf ein Totem der Manaflut" } },
      ["pvp-travel-heal"] = { title = "Verjüngung, dann zurück in Reisegestalt", use = "Für Flaggenläufe und Kiten: Verlass Reisegestalt und wirk Verjüngung auf dich, dann drück erneut, um zurückzuwechseln. Reisegestalt funktioniert nur im Freien, und nach 12 Sekunden ohne Druck beginnt die Abfolge von vorn.",
        requires = "Reisegestalt erlernt", mods = {  } },
      ["pvp-trinket-shift"] = { title = "PvP-Schmuckstück und Bärengestalt", use = "Brich deinen Zauber ab, nutze im Kampf dein oberes Schmuckstück und wechsle in Terrorbärengestalt oder mit Shift in Katzengestalt.",
        requires = "Ein PvP-Schmuckstück im oberen Platz, etwa Großes Insigne der Allianz oder der Horde (Rang Fußknecht oder Grunzer, 5 Min. Abklingzeit)", mods = { "Schmuckstück, dann Terrorbärengestalt", "Schmuckstück, dann Katzengestalt" } },
      ["pvp-victim-heal"] = { title = "Heile, wen dein feindliches Ziel gerade angreift", use = "Behalte einen Gegner im Ziel und wirk Verjüngung auf den, den er im Ziel hat, oder mit Shift Rasche Heilung. Ein freundliches Ziel bekommt stattdessen die Heilung, und sonst bist du selbst dran. Vorher verlässt du deine Gestalt.",
        requires = "Talent Rasche Heilung für die Shift-Hälfte", mods = { "Verjüngung auf dein freundliches Ziel, das Ziel deines feindlichen Ziels oder dich selbst", "Rasche Heilung auf dein freundliches Ziel, das Ziel deines feindlichen Ziels oder dich selbst" } },
      ["restoration-healing-touch-rank"] = { title = "Heilende Berührung, Shift für einen niedrigeren Rang", use = "Wirk den höchsten Rang von Heilende Berührung auf ein Mouseover-Ziel, dein Ziel oder dich selbst, oder halte Shift für Rang 3, wenn eine kleinere Heilung reicht; pass die Zahl an deine Stufe an.",
        requires = "Heilende Berührung Rang 3 erlernt", mods = { "Heilende Berührung mit deinem höchsten Rang", "Heilende Berührung Rang 3" } },
      ["restoration-natures-swiftness"] = { title = "Schnelligkeit der Natur, dann eine Heilung", use = "Verlass deine Gestalt, zünde Schnelligkeit der Natur und mach deine nächste Heilung sofort wirkbar: Heilende Berührung oder mit gehaltenem Shift Nachwachsen.",
        requires = "Talent Schnelligkeit der Natur", mods = { "Schnelligkeit der Natur, dann Heilende Berührung", "Schnelligkeit der Natur, dann Nachwachsen" } },
      ["restoration-regrowth"] = { title = "Mouseover-Nachwachsen oder das Ziel deines Ziels", use = "Nachwachsen auf den Verbündeten unter deinem Cursor, dein Ziel, denjenigen, den dein feindliches Ziel angreift, oder dich selbst.",
        requires = "Nachwachsen erlernt", mods = {  } },
      ["restoration-rejuv-party"] = { title = "Verjüngung nach Gruppenplatz", use = "Wirk Verjüngung auf dich, oder halt Shift, Ctrl oder Alt für Gruppenmitglied 1, 2 oder 3, ohne einen Rahmen anzuklicken.",
        requires = "Verjüngung erlernt", mods = { "Verjüngung auf dich selbst", "Verjüngung auf Gruppenmitglied 1", "Verjüngung auf Gruppenmitglied 2", "Verjüngung auf Gruppenmitglied 3" } },
      ["restoration-rejuv-swiftmend"] = { title = "Verjüngung, dann Rasche Heilung", use = "Verjüngung beim ersten Druck und Rasche Heilung beim zweiten, auf dein freundliches Ziel oder dich selbst, damit der HoT, den Rasche Heilung braucht, immer dein eigener ist.",
        requires = "Talent Rasche Heilung", mods = {  } },
      ["restoration-rejuvenation"] = { title = "Mouseover-Verjüngung", use = "Heile den Spieler im Gruppenrahmen unter deinem Cursor, dein Ziel oder dich selbst.",
        requires = "", mods = {  } },
      ["restoration-swiftmend"] = { title = "Rasche Heilung per Mouseover", use = "Rasche Heilung auf dein freundliches Mouseover-Ziel, dein Ziel oder dich selbst. Blizzard sagte am 30. September, dass der HoT weiterläuft; laut dem neuesten Tooltip verbraucht Rasche Heilung ihn, also wissen wir nicht sicher, was live gilt.",
        requires = "Talent Rasche Heilung; deine eigene Verjüngung oder dein eigenes Nachwachsen schon auf dem Ziel", mods = {  } },
      ["restoration-tranquility-channel"] = { title = "Gelassenheit, Shift zum Abbrechen", use = "Verlass deine Gestalt und kanalisiere Gelassenheit. Weitere Drücke lassen den Kanalzauber weiterlaufen; halte Shift, um ihn früher abzubrechen.",
        requires = "Gelassenheit erlernt", mods = { "Gelassenheit starten, ohne einen laufenden Kanalzauber neu zu beginnen", "Zaubern abbrechen" } },
      ["restoration-wild-growth"] = { title = "Mouseover-Wildwuchs", use = "Heile die nahe Gruppe samt Begleitern deines freundlichen Mouseovers oder Ziels in sieben abnehmenden Ticks. Der Zauber hat 3 Sek. Zauberzeit und 6 Sek. Abklingzeit. Im Raid bestimmt das Ziel, welche Gruppe geheilt wird.",
        requires = "Talent Wildwuchs", mods = {  } },
    },
  },
}
